/// How the viewport maps the model onto the screen.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ProjectionMode {
    /// Converging view — parallel edges meet, the way an eye sees a room.
    Perspective,
    /// Parallel view — parallel edges stay parallel, the way a drawing measures.
    Parallel,
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct CameraViewState {
    projection_mode: ProjectionMode,
    yaw: f32,
    pitch: f32,
    target_z: f64,
    zoom: f32,
    pan: Vec2,
    grid_axes_visible: bool,
    white_background_visible: bool,
    shadows_visible: bool,
    fog_visible: bool,
    hidden_objects_visible: bool,
    xray_visible: bool,
    wireframe_visible: bool,
    monochrome_visible: bool,
    hidden_line_visible: bool,
    edges_visible: bool,
    profiles_visible: bool,
    halos_visible: bool,
    depth_cue_visible: bool,
    fade_distant_edges_visible: bool,
    high_contrast_edges_visible: bool,
    selection_halo_visible: bool,
    endpoints_visible: bool,
    midpoints_visible: bool,
    extensions_visible: bool,
    jitter_visible: bool,
    dashes_visible: bool,
    color_by_axis_visible: bool,
}

impl ProjectionMode {
    const fn toggled(self) -> Self {
        match self {
            Self::Perspective => Self::Parallel,
            Self::Parallel => Self::Perspective,
        }
    }

    const fn label_key(self) -> &'static str {
        match self {
            Self::Perspective => "view-projection-perspective",
            Self::Parallel => "view-projection-parallel",
        }
    }
}

