    fn new_document(&mut self) {
        self.cancel_pending_assistant_work();
        let dialogs = std::mem::replace(&mut self.dialogs, Box::new(NativeFileDialogs::default()));
        let assistant_transport = Arc::clone(&self.assistant_transport);
        let assistant_request_sequence = self.assistant_request_sequence;
        let assistant_diagnostics_enabled = self.assistant_diagnostics_enabled;
        let assistant_inspector_tab = self.assistant_inspector_tab;
        let catalog = self.catalog.clone();
        let outliner_visible = self.outliner_visible;
        let tags_visible = self.tags_visible;
        let dimensions_visible = self.dimensions_visible;
        let about_open = self.about_open;
        // The graphics device outlives the document: losing its target format
        // here would silently drop the whole instanced scene until restart.
        let wgpu_target_format = self.wgpu_target_format;
        *self = Self::with_catalog(catalog)
            .with_dialogs(dialogs)
            .with_assistant_transport(assistant_transport);
        self.wgpu_target_format = wgpu_target_format;
        self.assistant_request_sequence = assistant_request_sequence;
        self.assistant_diagnostics_enabled = assistant_diagnostics_enabled;
        self.assistant_inspector_tab = assistant_inspector_tab;
        self.outliner_visible = outliner_visible;
        self.tags_visible = tags_visible;
        self.dimensions_visible = dimensions_visible;
        self.about_open = about_open;
        self.digest = self.catalog.text("digest-new-document");
    }

    fn migration_review_identity(
        outcome: &ketchup_core::persistence::LoadOutcome,
    ) -> Result<MigrationReviewIdentity, String> {
        let candidate = outcome
            .review_candidate()
            .ok_or_else(|| "loaded document is not a review-only migration candidate".to_owned())?;
        let snapshot = candidate.snapshot();
        let mut audit = candidate.audit().clone();
        audit.recovered_from_backup = false;
        let container =
            ketchup_core::persistence::save_container(snapshot, candidate.container_data())
                .map_err(|error| error.to_string())?;
        Ok(MigrationReviewIdentity {
            document_id: snapshot.document_id(),
            revision_id: snapshot.revision_id(),
            canonical_digest: snapshot.canonical_digest(),
            audit,
            container_sha256: sha256_bytes(&container),
        })
    }

    fn prepare_migration_review_plan(
        &self,
        path: &Path,
        outcome: &ketchup_core::persistence::LoadOutcome,
    ) -> Result<MigrationReviewPlan, String> {
        let effective_path = if outcome.audit().recovered_from_backup {
            let mut recovery = path.as_os_str().to_os_string();
            recovery.push(".recovery");
            PathBuf::from(recovery)
        } else {
            path.to_owned()
        };
        let source = std::fs::read(&effective_path).map_err(|error| error.to_string())?;
        let rederived =
            ketchup_core::persistence::load(&source).map_err(|error| error.to_string())?;
        let review = Self::migration_review_identity(outcome)?;
        if Self::migration_review_identity(&rederived)? != review {
            return Err("migration review does not match the exact loaded source bytes".to_owned());
        }
        let active = self.document.current();
        Ok(MigrationReviewPlan {
            source: MigrationReviewSourcePlan {
                path: path.to_owned(),
                effective_path,
                source_sha256: sha256_bytes(&source),
                source_byte_len: source.len() as u64,
                source,
                active_document_id: active.document_id(),
                active_revision_id: active.revision_id(),
                active_canonical_digest: active.canonical_digest(),
            },
            review,
        })
    }

    fn open_document_from(&mut self, path: &Path) -> bool {
        self.cancel_pending_assistant_work();
        match ketchup_core::persistence::load_file(path) {
            Ok(outcome) => {
                if !outcome.is_editable() {
                    let plan = match self.prepare_migration_review_plan(path, &outcome) {
                        Ok(plan) => plan,
                        Err(reason) => {
                            self.review_candidate = None;
                            self.migration_review_plan = None;
                            self.digest = self.catalog.format(
                                "error-open-document",
                                &BTreeMap::from([
                                    ("path", path.display().to_string()),
                                    ("reason", reason),
                                ]),
                            );
                            return false;
                        }
                    };
                    self.review_candidate = Some(outcome);
                    self.migration_review_plan = Some(plan);
                    self.digest = self.catalog.format(
                        "error-open-document",
                        &BTreeMap::from([
                            ("path", path.display().to_string()),
                            (
                                "reason",
                                "document requires read-only migration review".to_owned(),
                            ),
                        ]),
                    );
                    return false;
                }
                let Ok((mut document, container_data)) = outcome.into_editable_with_container()
                else {
                    unreachable!("editable load outcome must contain an editable document");
                };
                document.discard_history_before_current();
                document
                    .configure_human_confirmation_policy(
                        self.confirmation_surface.verifying_key(),
                        1,
                    )
                    .expect("an opened document accepts the application confirmation policy");
                self.document = document;
                self.container_data = container_data;
                self.review_candidate = None;
                self.migration_review_plan = None;
                self.document_path = Some(path.to_owned());
                self.saved_digest = self.document.current().canonical_digest();
                self.reset_document_presentation();
                self.load_assistant_conversation();
                self.load_assistant_memory();
                self.digest = self.catalog.format(
                    "digest-opened-document",
                    &BTreeMap::from([("path", path.display().to_string())]),
                );
                true
            }
            Err(error) => {
                self.digest = self.catalog.format(
                    "error-open-document",
                    &BTreeMap::from([
                        ("path", path.display().to_string()),
                        ("reason", error.to_string()),
                    ]),
                );
                false
            }
        }
    }

    fn authorize_path_side_effect(
        &mut self,
        class: HighRiskClass,
        operation: &str,
        title: &str,
        risk: &str,
        path: &Path,
        payload: &[u8],
    ) -> Result<(), String> {
        let scope = HighRiskScope::new(class, None, None, Some(path.display().to_string()))
            .map_err(|error| error.to_string())?;
        let proposal = self
            .document
            .prepare_high_risk_side_effect(
                operation,
                ProposalPrincipal::LocalAssistant,
                scope,
                payload,
            )
            .map_err(|error| error.to_string())?;
        let description = format!(
            "Risk: {risk}\nPath: {}\nDocument revision: {}\nPayload SHA-256: {}\nOperation digest: {}",
            path.display(),
            proposal.provenance_revision(),
            proposal.payload_digest(),
            proposal.operation_digest(),
        );
        let Some(approving_human) = self.dialogs.confirm_high_risk(HighRiskConfirmationRequest {
            title,
            description: &description,
        }) else {
            return Err(format!("authenticated human declined {risk}"));
        };
        let now_ms = current_unix_time_ms()?;
        let approval = self
            .confirmation_surface
            .issue_side_effect(
                &proposal,
                AuthenticatedApprover::Human(approving_human),
                now_ms,
                now_ms
                    .checked_add(MAX_HUMAN_CONFIRMATION_LIFETIME_MS)
                    .ok_or_else(|| "confirmation expiry exceeds the supported clock".to_owned())?,
            )
            .map_err(|error| error.to_string())?;
        let receipt = self
            .document
            .authorize_high_risk_side_effect(&proposal, &approval, now_ms)
            .map_err(|error| error.to_string())?;
        self.side_effect_receipts.push(receipt);
        Ok(())
    }

    #[cfg(feature = "named-product-fixtures")]
    fn authorize_beam_path_side_effect(
        &mut self,
        class: HighRiskClass,
        operation: &str,
        title: &str,
        risk: &str,
        path: &Path,
        payload: &[u8],
    ) -> Result<(), String> {
        self.side_effect_receipts.clear();
        let scope = HighRiskScope::new(class, None, None, Some(path.display().to_string()))
            .map_err(|error| error.to_string())?;
        let proposal = self
            .beam_workspace
            .as_ref()
            .ok_or_else(|| "Beam workspace is unavailable".to_owned())?
            .prepare_high_risk_side_effect(
                operation,
                ProposalPrincipal::LocalAssistant,
                scope,
                payload,
            )
            .map_err(|error| error.to_string())?;
        let description = format!(
            "Risk: {risk}\nPath: {}\nDocument revision: {}\nPayload SHA-256: {}\nOperation digest: {}",
            path.display(),
            proposal.provenance_revision(),
            proposal.payload_digest(),
            proposal.operation_digest(),
        );
        let Some(approving_human) = self.dialogs.confirm_high_risk(HighRiskConfirmationRequest {
            title,
            description: &description,
        }) else {
            return Err(format!("authenticated human declined {risk}"));
        };
        let now_ms = current_unix_time_ms()?;
        let approval = self
            .confirmation_surface
            .issue_side_effect(
                &proposal,
                AuthenticatedApprover::Human(approving_human),
                now_ms,
                now_ms
                    .checked_add(MAX_HUMAN_CONFIRMATION_LIFETIME_MS)
                    .ok_or_else(|| "confirmation expiry exceeds the supported clock".to_owned())?,
            )
            .map_err(|error| error.to_string())?;
        let receipt = self
            .beam_workspace
            .as_mut()
            .ok_or_else(|| "Beam workspace is unavailable".to_owned())?
            .authorize_high_risk_side_effect(&proposal, &approval, now_ms)
            .map_err(|error| error.to_string())?;
        self.side_effect_receipts.push(receipt);
        Ok(())
    }

    fn authorize_overwrite(&mut self, path: &Path, payload: &[u8]) -> Result<(), String> {
        self.side_effect_receipts.clear();
        self.authorize_path_side_effect(
            HighRiskClass::Overwrite,
            "overwrite-native-document",
            "Confirm high-risk overwrite",
            "overwrite existing file",
            path,
            payload,
        )
    }

    fn save_document_to(&mut self, path: &Path) -> bool {
        if path.is_dir() {
            self.digest = self.catalog.format(
                "error-save-document",
                &BTreeMap::from([
                    ("path", path.display().to_string()),
                    ("reason", "the target path is a directory".to_owned()),
                ]),
            );
            return false;
        }
        self.store_assistant_conversation();
        self.store_assistant_memory();
        let snapshot = self.document.current();
        let prepared = ketchup_core::persistence::save_container(&snapshot, &self.container_data);
        if path.exists()
            && let Err(error) = prepared
                .as_ref()
                .map_err(ToString::to_string)
                .and_then(|bytes| self.authorize_overwrite(path, bytes))
        {
            self.digest = self.catalog.format(
                "error-save-document",
                &BTreeMap::from([("path", path.display().to_string()), ("reason", error)]),
            );
            return false;
        }
        let result = prepared.map_err(|error| error.to_string()).and_then(|_| {
            ketchup_core::persistence::save_atomic_with_container(
                path,
                &snapshot,
                &self.container_data,
            )
            .map_err(|error| error.to_string())
        });
        match result {
            Ok(()) => {
                self.document_path = Some(path.to_owned());
                self.saved_digest = snapshot.canonical_digest();
                self.saved_assistant_conversation_digest =
                    assistant_conversation_digest(&self.assistant_messages);
                self.digest = self.catalog.format(
                    "digest-saved-document",
                    &BTreeMap::from([("path", path.display().to_string())]),
                );
                true
            }
            Err(error) => {
                self.digest = self.catalog.format(
                    "error-save-document",
                    &BTreeMap::from([
                        ("path", path.display().to_string()),
                        ("reason", error.to_string()),
                    ]),
                );
                false
            }
        }
    }

    fn confirm_discard_if_dirty(&mut self) -> bool {
        if !self.is_dirty() {
            return true;
        }
        let title = self.catalog.text("dialog-unsaved-title");
        let description = self.catalog.text("dialog-unsaved-description");
        self.dialogs.confirm_discard(DiscardRequest {
            title: &title,
            description: &description,
        })
    }

