    fn prepare_sketchup_scene_import_preview_plan(
        &self,
        source: SketchupSceneImportSourcePlan,
    ) -> Result<SketchupSceneImportPreviewPlan, String> {
        let snapshot = self.document.current();
        if snapshot.document_id() != source.document_id
            || snapshot.revision_id() != source.revision_id
            || snapshot.canonical_digest() != source.canonical_digest
        {
            return Err("SketchUp scene import review is stale for the active document".to_owned());
        }
        if source.source.len() as u64 != source.source_byte_len
            || sha256_bytes(&source.source) != source.source_sha256
        {
            return Err(
                "sealed SketchUp scene source identity does not match its bytes".to_owned(),
            );
        }
        let source_name = source
            .path
            .file_name()
            .and_then(|name| name.to_str())
            .ok_or_else(|| "SketchUp scene source name is not valid UTF-8".to_owned())?;
        let review = std::panic::catch_unwind(|| inspect_sketchup_scene(&source.source))
            .map_err(|_| {
                "bounded SketchUp scene parser stopped without publishing geometry".to_owned()
            })?
            .map_err(|error| error.to_string())?;
        let batch = std::panic::catch_unwind(|| {
            plan_sketchup_scene_import(&snapshot, &source.source, source_name)
        })
        .map_err(|_| {
            "bounded SketchUp scene parser stopped without publishing geometry".to_owned()
        })?
        .map_err(|error| error.to_string())?;
        let proposal = self
            .document
            .prepare_proposal_with_context(batch, ProposalContext::canonical_preview())
            .map_err(|error| error.to_string())?;
        Ok(SketchupSceneImportPreviewPlan {
            source,
            review,
            proposal,
        })
    }

    fn import_sketchup_scene_from(&mut self, pending: &PendingSketchupSceneImport) -> bool {
        let path = &pending.plan.source.path;
        let result = (|| {
            if pending.invalidated {
                return Err(
                    "SketchUp scene import review is stale for the active document".to_owned(),
                );
            }
            let source = Self::read_sketchup_scene_source(path)?;
            if source.len() as u64 != pending.plan.source.source_byte_len
                || sha256_bytes(&source) != pending.plan.source.source_sha256
                || source != pending.plan.source.source
            {
                return Err(
                    "SketchUp scene package changed after it was selected for review".to_owned(),
                );
            }
            let rederived =
                self.prepare_sketchup_scene_import_preview_plan(pending.plan.source.clone())?;
            if rederived != pending.plan {
                return Err("SketchUp scene review or proposal changed after preview".to_owned());
            }
            self.document
                .commit_verified_proposal(&pending.plan.proposal)
                .map_err(|error| error.to_string())?;
            Ok::<(), String>(())
        })();
        match result {
            Ok(()) => {
                self.digest = self.catalog.format(
                    "digest-imported-sketchup-scene",
                    &BTreeMap::from([("path", path.display().to_string())]),
                );
                true
            }
            Err(reason) => {
                self.digest = self.catalog.format(
                    "error-import-sketchup-scene",
                    &BTreeMap::from([("path", path.display().to_string()), ("reason", reason)]),
                );
                false
            }
        }
    }

    fn current_visible_exact_model(
        &self,
        snapshot: &Snapshot,
    ) -> Result<Vec<(ExactBodyPackage, Transform)>, String> {
        let occurrences = snapshot
            .scene_query()
            .into_iter()
            .filter(|occurrence| occurrence.visible)
            .filter(|occurrence| {
                snapshot
                    .definition(occurrence.definition_id)
                    .is_some_and(|definition| {
                        definition.feature_ids().iter().any(|feature_id| {
                            snapshot
                                .feature(*feature_id)
                                .is_some_and(|feature| feature.kind().produces_body())
                        })
                    })
            })
            .collect::<Vec<_>>();
        if occurrences.is_empty() {
            return Err("the visible model is empty".to_owned());
        }
        let mut model = Vec::new();
        for occurrence in occurrences {
            let packages = self
                .exact_results
                .render_values(snapshot)
                .filter(|package| package.definition_id() == occurrence.definition_id)
                .collect::<Vec<_>>();
            if packages.is_empty() {
                return Err(format!(
                    "visible occurrence {:?} has no current accepted exact result",
                    occurrence.instance_path
                ));
            }
            model.extend(
                packages
                    .into_iter()
                    .map(|package| ((**package).clone(), occurrence.transform)),
            );
        }
        Ok(model)
    }

    fn export_current_model_stl_to(&mut self, path: &Path) -> bool {
        self.side_effect_receipts.clear();
        let snapshot = self.document.current();
        let result = self
            .current_visible_exact_model(&snapshot)
            .and_then(|model| {
                if model
                    .iter()
                    .any(|(package, _)| matches!(package, ExactBodyPackage::Imported(_)))
                {
                    return Err("imported STEP bounds proxies cannot be exported as STL".to_owned());
                }
                let bodies = model
                    .iter()
                    .map(|(package, transform)| (package, *transform))
                    .collect::<Vec<_>>();
                exact_model_stl_export(&snapshot, &bodies).map_err(|error| error.to_string())
            })
            .and_then(|bundle| {
                let report_path = path.with_extension("stl.loss.txt");
                let precondition = ExportBundlePrecondition::capture(path, &report_path)?;
                let evidence = exact_stl_export_evidence(path, &bundle);
                let title = self.catalog.text("dialog-export-lossy-title");
                let risk = self.catalog.text("dialog-export-lossy-risk");
                self.authorize_path_side_effect(
                    HighRiskClass::LossyConversion,
                    "export-current-model-stl-with-loss-report",
                    &title,
                    &risk,
                    path,
                    &evidence,
                )?;
                if precondition.primary_sha256.is_some() {
                    let title = self.catalog.text("dialog-export-overwrite-title");
                    let risk = self.catalog.text("dialog-export-overwrite-risk");
                    self.authorize_path_side_effect(
                        HighRiskClass::Overwrite,
                        "overwrite-current-model-stl-export",
                        &title,
                        &risk,
                        path,
                        &evidence,
                    )?;
                }
                if precondition.report_sha256.is_some() {
                    let title = self.catalog.text("dialog-export-overwrite-title");
                    let risk = self.catalog.text("dialog-export-overwrite-risk");
                    self.authorize_path_side_effect(
                        HighRiskClass::Overwrite,
                        "overwrite-current-model-stl-loss-report",
                        &title,
                        &risk,
                        &report_path,
                        &evidence,
                    )?;
                }
                write_export_bundle(
                    path,
                    bundle.mesh_stl.as_bytes(),
                    &report_path,
                    bundle.loss_report.as_bytes(),
                    &precondition,
                )
            });
        match result {
            Ok(()) => {
                self.digest = self.catalog.format(
                    "digest-exported-stl",
                    &BTreeMap::from([("path", path.display().to_string())]),
                );
                true
            }
            Err(error) => {
                self.digest = self.catalog.format(
                    "error-export-stl",
                    &BTreeMap::from([("path", path.display().to_string()), ("reason", error)]),
                );
                false
            }
        }
    }

    fn export_current_model_step_to(&mut self, path: &Path) -> bool {
        self.side_effect_receipts.clear();
        let snapshot = self.document.current();
        let result = (|| {
            let model = self.current_visible_exact_model(&snapshot)?;
            let executable = self
                .exact_worker_path
                .clone()
                .or_else(|| {
                    exact_worker_candidates()
                        .into_iter()
                        .find(|candidate| candidate.is_file())
                })
                .ok_or_else(|| "exact worker is unavailable".to_owned())?;
            let parent = path.parent().unwrap_or_else(|| Path::new("."));
            let prepared_directory = tempfile::Builder::new()
                .prefix(".ketchup-prepared-export-")
                .tempdir_in(parent)
                .map_err(|error| error.to_string())?;
            let prepared_step = prepared_directory.path().join("model.step");
            let mut worker =
                ExactWorkerSupervisor::spawn(executable).map_err(|error| error.to_string())?;
            worker
                .export_current_model_step_with_imported_sources(
                    &snapshot,
                    &model,
                    &prepared_step,
                    self.container_data.blobs(),
                )
                .map_err(|error| error.to_string())?;
            let mut step = String::from_utf8(
                std::fs::read(&prepared_step).map_err(|error| error.to_string())?,
            )
            .map_err(|error| error.to_string())?;
            let timestamp_marker = "FILE_NAME('Open CASCADE Shape Model','";
            let timestamp_start = step
                .find(timestamp_marker)
                .map(|index| index + timestamp_marker.len())
                .ok_or_else(|| {
                    "STEP export is missing the canonical FILE_NAME header".to_owned()
                })?;
            let timestamp_end = step[timestamp_start..]
                .find("',(")
                .map(|index| timestamp_start + index)
                .ok_or_else(|| "STEP export has an invalid FILE_NAME header".to_owned())?;
            step.replace_range(timestamp_start..timestamp_end, "1970-01-01T00:00:00");
            let step = step.into_bytes();
            let report = exact_model_step_loss_report(&snapshot, &model);
            let report_path = path.with_extension("step.loss.txt");
            let evidence = export_bundle_evidence(
                b"ketchup.current-model-step-export.v1",
                path,
                &step,
                &report_path,
                report.as_bytes(),
            );
            let precondition = ExportBundlePrecondition::capture(path, &report_path)?;
            let title = self.catalog.text("dialog-export-lossy-title");
            let risk = self.catalog.text("dialog-export-lossy-risk");
            self.authorize_path_side_effect(
                HighRiskClass::LossyConversion,
                "export-current-model-step-with-loss-report",
                &title,
                &risk,
                path,
                &evidence,
            )?;
            if precondition.primary_sha256.is_some() {
                let title = self.catalog.text("dialog-export-overwrite-title");
                let risk = self.catalog.text("dialog-export-overwrite-risk");
                self.authorize_path_side_effect(
                    HighRiskClass::Overwrite,
                    "overwrite-current-model-step-export",
                    &title,
                    &risk,
                    path,
                    &evidence,
                )?;
            }
            if precondition.report_sha256.is_some() {
                let title = self.catalog.text("dialog-export-overwrite-title");
                let risk = self.catalog.text("dialog-export-overwrite-risk");
                self.authorize_path_side_effect(
                    HighRiskClass::Overwrite,
                    "overwrite-current-model-step-loss-report",
                    &title,
                    &risk,
                    &report_path,
                    &evidence,
                )?;
            }
            write_export_bundle(path, &step, &report_path, report.as_bytes(), &precondition)
        })();
        match result {
            Ok(()) => {
                self.digest = self.catalog.format(
                    "digest-exported-step",
                    &BTreeMap::from([("path", path.display().to_string())]),
                );
                true
            }
            Err(error) => {
                self.digest = self.catalog.format(
                    "error-export-step",
                    &BTreeMap::from([("path", path.display().to_string()), ("reason", error)]),
                );
                false
            }
        }
    }

    fn dispatch_file_command(&mut self, id: AppCommand) {
        match id {
            AppCommand::New if self.confirm_discard_if_dirty() => self.new_document(),
            AppCommand::Open if self.confirm_discard_if_dirty() => {
                if let Some(path) = self.choose_open_path() {
                    self.open_document_from(&path);
                }
            }
            AppCommand::Save => {
                if let Some(path) = self
                    .document_path
                    .clone()
                    .or_else(|| self.choose_save_path())
                {
                    self.save_document_to(&path);
                }
            }
            AppCommand::SaveAs => {
                if let Some(path) = self.choose_save_path() {
                    self.save_document_to(&path);
                }
            }
            AppCommand::ImportMeshStl => {
                if let Some(path) = self.choose_stl_import_path() {
                    match Self::read_stl_source(&path).and_then(|source| {
                        let snapshot = self.document.current();
                        let source_plan = StlImportSourcePlan {
                            path: path.clone(),
                            source_sha256: sha256_bytes(&source),
                            source_byte_len: source.len() as u64,
                            source,
                            unit: ImportLengthUnit::Millimetre,
                            document_id: snapshot.document_id(),
                            revision_id: snapshot.revision_id(),
                            canonical_digest: snapshot.canonical_digest(),
                        };
                        let plan = self.prepare_stl_import_preview_plan(source_plan)?;
                        Ok(PendingStlImport {
                            plan,
                            review_error: None,
                            invalidated: false,
                        })
                    }) {
                        Ok(pending) => self.pending_stl_import = Some(pending),
                        Err(reason) => {
                            self.pending_stl_import = None;
                            self.digest = self.catalog.format(
                                "error-import-stl",
                                &BTreeMap::from([
                                    ("path", path.display().to_string()),
                                    ("reason", reason),
                                ]),
                            );
                        }
                    }
                }
            }
            AppCommand::ImportExactStep => {
                if let Some(path) = self.choose_step_import_path() {
                    let result = Self::read_step_source(&path).and_then(|source| {
                        let snapshot = self.document.current();
                        let source_plan = StepImportSourcePlan {
                            path: path.clone(),
                            source_sha256: sha256_bytes(&source),
                            source_byte_len: source.len() as u64,
                            source,
                            document_id: snapshot.document_id(),
                            revision_id: snapshot.revision_id(),
                            canonical_digest: snapshot.canonical_digest(),
                        };
                        let plan = self.prepare_step_import_preview_plan(source_plan)?;
                        Ok(PendingStepImport {
                            plan,
                            invalidated: false,
                        })
                    });
                    match result {
                        Ok(pending) => self.pending_step_import = Some(pending),
                        Err(reason) => {
                            self.pending_step_import = None;
                            self.digest = self.catalog.format(
                                "error-import-step",
                                &BTreeMap::from([
                                    ("path", path.display().to_string()),
                                    ("reason", reason),
                                ]),
                            );
                        }
                    }
                }
            }
            AppCommand::ImportSketchupScene => {
                if let Some(path) = self.choose_sketchup_scene_import_path() {
                    let result = Self::read_sketchup_scene_source(&path).and_then(|source| {
                        let snapshot = self.document.current();
                        let source_plan = SketchupSceneImportSourcePlan {
                            path: path.clone(),
                            source_sha256: sha256_bytes(&source),
                            source_byte_len: source.len() as u64,
                            source,
                            document_id: snapshot.document_id(),
                            revision_id: snapshot.revision_id(),
                            canonical_digest: snapshot.canonical_digest(),
                        };
                        let plan = self.prepare_sketchup_scene_import_preview_plan(source_plan)?;
                        Ok(PendingSketchupSceneImport {
                            plan,
                            invalidated: false,
                        })
                    });
                    match result {
                        Ok(pending) => self.pending_sketchup_scene_import = Some(pending),
                        Err(reason) => {
                            self.pending_sketchup_scene_import = None;
                            self.digest = self.catalog.format(
                                "error-import-sketchup-scene",
                                &BTreeMap::from([
                                    ("path", path.display().to_string()),
                                    ("reason", reason),
                                ]),
                            );
                        }
                    }
                }
            }
            AppCommand::ImportDrawingDxf => {
                if let Some(path) = self.choose_dxf_import_path() {
                    let result = Self::read_dxf_source(&path).and_then(|source| {
                        let initial_review = Self::inspect_dxf_for_review(&source)?;
                        let unit = initial_review.units().source_unit();
                        let unit_confirmed =
                            initial_review.units().authority() == ImportUnitAuthority::FileDeclared;
                        let snapshot = self.document.current();
                        let source_plan = DxfImportSourcePlan {
                            path: path.clone(),
                            source_sha256: sha256_bytes(&source),
                            source_byte_len: source.len() as u64,
                            source,
                            unit,
                            document_id: snapshot.document_id(),
                            revision_id: snapshot.revision_id(),
                            canonical_digest: snapshot.canonical_digest(),
                        };
                        let plan = self.prepare_dxf_import_preview_plan(source_plan)?;
                        Ok(PendingDxfImport {
                            plan,
                            unit_confirmed,
                            review_error: None,
                            invalidated: false,
                        })
                    });
                    match result {
                        Ok(pending) => self.pending_dxf_import = Some(pending),
                        Err(reason) => {
                            self.digest = self.catalog.format(
                                "error-import-dxf",
                                &BTreeMap::from([
                                    ("path", path.display().to_string()),
                                    ("reason", reason),
                                ]),
                            );
                        }
                    }
                }
            }
            AppCommand::ExportExactStep => {
                if let Some(path) = self.choose_export_path("step") {
                    self.export_current_model_step_to(&path);
                }
            }
            AppCommand::ExportMeshStl => {
                if let Some(path) = self.choose_export_path("stl") {
                    self.export_current_model_stl_to(&path);
                }
            }
            AppCommand::New | AppCommand::Open => {}
            _ => unreachable!("only file commands are routed here"),
        }
    }

    #[must_use]
    pub fn native_options() -> eframe::NativeOptions {
        Self::native_options_for_adapter(None, Arc::new(Mutex::new(None)))
    }

    #[must_use]
    pub fn native_options_for_adapter(
        requirement: Option<AdapterRequirement>,
        selected_info: SelectedAdapterInfo,
    ) -> eframe::NativeOptions {
        let mut setup = eframe::egui_wgpu::WgpuSetupCreateNew::default();
        setup.instance_descriptor.backends = eframe::wgpu::Backends::DX12;
        setup.native_adapter_selector = Some(Arc::new(move |adapters, surface| {
            let mut matching = adapters.iter().filter(|adapter| {
                let info = adapter.get_info();
                info.backend == eframe::wgpu::Backend::Dx12
                    && !matches!(
                        info.device_type,
                        eframe::wgpu::DeviceType::Cpu | eframe::wgpu::DeviceType::VirtualGpu
                    )
                    && requirement.as_ref().is_none_or(|required| {
                        info.name == required.name && info.device_type == required.device_type
                    })
                    && surface.is_none_or(|surface| adapter.is_surface_supported(surface))
            });
            let selected = matching.next().ok_or_else(|| {
                "no Direct3D 12 physical adapter matched the frozen requirement".to_owned()
            })?;
            if matching.next().is_some() {
                return Err(
                    "multiple Direct3D 12 physical adapters matched the frozen requirement"
                        .to_owned(),
                );
            }
            let info = selected.get_info();
            *selected_info
                .lock()
                .map_err(|_| "selected-adapter evidence lock is unavailable".to_owned())? =
                Some(info);
            Ok(selected.clone())
        }));

        eframe::NativeOptions {
            renderer: eframe::Renderer::Wgpu,
            wgpu_options: eframe::egui_wgpu::WgpuConfiguration {
                present_mode: eframe::wgpu::PresentMode::AutoNoVsync,
                wgpu_setup: setup.into(),
                ..Default::default()
            },
            viewport: egui::ViewportBuilder::default()
                .with_inner_size([1_100.0, 720.0])
                .with_min_inner_size([1_100.0, 600.0]),
            ..Default::default()
        }
    }

