    fn derive_assistant_workflow_proposal(
        &self,
        intent: &WorkflowIntent,
    ) -> AssistantPlanningResult<Proposal> {
        let target = format!("document:{}", self.document.current().document_id().0);
        let proposal = propose_intent(&self.document, IntentRequest::m7a(intent.clone())).map_err(
            |error| match error {
                ketchup_core::intent::IntentError::Canonical(error) => {
                    assistant_canonical_rejection(error, "workflow_intent", &target)
                }
                ketchup_core::intent::IntentError::Proposal(error) => {
                    assistant_proposal_prepare_rejection(error, "workflow_intent", &target)
                }
                error => assistant_planning_rejection(
                    "planning.intent_capability_denied",
                    "workflow_intent",
                    &target,
                    error.to_string(),
                    "Request an operation granted to the local Assistant capability set.",
                ),
            },
        )?;
        if !matches!(intent, WorkflowIntent::SetFeatureDimension { .. }) {
            return Ok(proposal);
        }
        let context = ProposalContext {
            principal: ProposalPrincipal::LocalAssistant,
            goal: proposal.goal(),
            assumptions: proposal.assumptions().to_vec(),
            risk: proposal.risk(),
            confirmation: proposal.confirmation().clone(),
            requested_budget: proposal.requested_budget(),
        };
        self.prepare_smart_push_pull_proposal_with_context(proposal.batch().clone(), context)
            .map_err(|error| {
                assistant_proposal_prepare_rejection(error, "set_feature_dimension", &target)
            })
    }

    pub fn prepare_assistant_intent(&mut self, intent: WorkflowIntent) -> bool {
        match self.derive_assistant_workflow_proposal(&intent) {
            Ok(proposal) => {
                self.digest = self.catalog.format(
                    "assistant-digest-preview",
                    &BTreeMap::from([
                        (
                            "reads",
                            proposal.authoritative_dependencies().len().to_string(),
                        ),
                        ("writes", proposal.authoritative_writes().len().to_string()),
                    ]),
                );
                self.status_key = "status-preview";
                self.assistant_verification = None;
                self.assistant_proposal = Some(AssistantPreviewPlan {
                    source: AssistantPreviewSource::Workflow(intent),
                    proposal,
                    repair: None,
                });
                true
            }
            Err(error) => {
                self.assistant_proposal = None;
                self.digest = self.catalog.format(
                    "assistant-digest-rejected",
                    &BTreeMap::from([("reason", error.failed_invariant)]),
                );
                false
            }
        }
    }

    pub fn apply_assistant_intent(&mut self, intent: WorkflowIntent) -> bool {
        self.prepare_assistant_intent(intent)
            && self
                .assistant_proposal
                .as_ref()
                .is_some_and(|plan| Self::assistant_proposal_is_low_risk(&plan.proposal))
            && self.confirm_assistant_proposal()
    }

    pub fn confirm_assistant_proposal(&mut self) -> bool {
        let Some(plan) = self.assistant_proposal.take() else {
            return false;
        };
        let snapshot = self.document.current();
        let rederived = self.derive_assistant_preview_plan(&plan.source);
        if plan.document_id() != snapshot.document_id()
            || plan.provenance_revision() != snapshot.revision_id()
            || plan.provenance_digest() != snapshot.canonical_digest()
            || rederived.as_ref().ok() != Some(&plan)
        {
            let reason = rederived
                .err()
                .map(|diagnostic| diagnostic.failed_invariant)
                .unwrap_or_else(|| self.catalog.text("assistant-error-stale-response"));
            self.status_key = "status-ready";
            self.digest = self.catalog.format(
                "assistant-digest-rejected",
                &BTreeMap::from([("reason", reason)]),
            );
            return false;
        }
        let repair_selection = match &plan.source {
            AssistantPreviewSource::ValidationRepair(selection) => Some(selection.clone()),
            AssistantPreviewSource::Workflow(_)
            | AssistantPreviewSource::Assembly(_)
            | AssistantPreviewSource::Model(_)
            | AssistantPreviewSource::CadEdit(_) => None,
        };
        let repair_preview = plan.repair.clone();
        match self.document.commit_verified_proposal(&plan.proposal) {
            Ok(committed) => {
                let (repair_program, repair_validator, validation_before, validation_after) =
                    repair_preview.map_or((None, None, None, None), |repair| {
                        let snapshot = self.document.current();
                        self.rebind_exact_results(&snapshot);
                        let selection = repair_selection
                            .as_ref()
                            .expect("repair preview carries its validator selection");
                        let revalidated = self.assistant_validation_context(
                            &snapshot,
                            &self.exact_results,
                            selection,
                        );
                        debug_assert_eq!(revalidated, repair.validation_after);
                        let validators = repair
                            .program
                            .operations
                            .iter()
                            .map(AssistantRepairOperation::validator)
                            .collect::<BTreeSet<_>>()
                            .into_iter()
                            .collect::<Vec<_>>()
                            .join(" + ");
                        (
                            Some(repair.program),
                            Some(validators),
                            Some(repair.validation_before),
                            Some(revalidated),
                        )
                    });
                let verification = AssistantVerification {
                    revision_id: committed.revision().id(),
                    command_digest: committed.command_digest().to_owned(),
                    result_digest: committed.result_digest().to_owned(),
                    canonical_digest: self.document.current().canonical_digest(),
                    verified_write_count: committed.verified_writes().len(),
                    repair_program,
                    repair_validator,
                    validation_before,
                    validation_after,
                };
                self.digest = self.catalog.format(
                    "assistant-digest-committed",
                    &BTreeMap::from([
                        ("revision", verification.revision_id.to_string()),
                        ("writes", verification.verified_write_count.to_string()),
                    ]),
                );
                self.status_key = "status-ready";
                self.assistant_verification = Some(verification);
                true
            }
            Err(error) => {
                self.digest = self.catalog.format(
                    "assistant-digest-rejected",
                    &BTreeMap::from([("reason", error.to_string())]),
                );
                false
            }
        }
    }

    pub fn cancel_assistant_proposal(&mut self) -> bool {
        if self.assistant_proposal.take().is_none() {
            return false;
        }
        self.status_key = "status-ready";
        self.digest = self.catalog.text("assistant-digest-cancelled");
        true
    }

    #[must_use]
    pub fn assistant_proposal(&self) -> Option<&Proposal> {
        self.assistant_proposal.as_ref().map(|plan| &plan.proposal)
    }

    #[must_use]
    pub fn assistant_repair_program(&self) -> Option<&AssistantRepairProgram> {
        self.assistant_proposal
            .as_ref()
            .and_then(|plan| plan.repair.as_ref())
            .map(|repair| &repair.program)
    }

    fn assistant_proposal_target_label(&self, target: &AuthoritativeDependency) -> String {
        let identified = match target {
            AuthoritativeDependency::EvaluatorNode(id) => {
                Some(("assistant-entity-evaluator", id.0))
            }
            AuthoritativeDependency::Override(id) => Some(("assistant-entity-override", *id)),
            AuthoritativeDependency::Joint(id) => Some(("assistant-entity-joint", id.0)),
            AuthoritativeDependency::Space(id) => Some(("assistant-entity-space", id.0)),
            AuthoritativeDependency::ClearanceVolume(id) => {
                Some(("assistant-entity-clearance", id.0))
            }
            AuthoritativeDependency::PersistentDimension(id) => {
                Some(("assistant-entity-persistent-dimension", id.0))
            }
            AuthoritativeDependency::ClassificationDimension(_)
            | AuthoritativeDependency::OccurrenceClassification(_, _) => None,
            AuthoritativeDependency::Tag(id) => Some(("assistant-entity-tag", id.0)),
            AuthoritativeDependency::Collection(id) => Some(("assistant-entity-collection", id.0)),
            AuthoritativeDependency::Import(_) => None,
            AuthoritativeDependency::Definition(id) => Some(("assistant-entity-definition", id.0)),
            AuthoritativeDependency::DefinitionUsers(id) => {
                Some(("assistant-entity-definition-users", id.0))
            }
            AuthoritativeDependency::Feature(id) => Some(("assistant-entity-feature", id.0)),
            AuthoritativeDependency::FeatureUsers(id) => {
                Some(("assistant-entity-feature-users", id.0))
            }
            AuthoritativeDependency::FeatureParameterBindings(id) => {
                Some(("assistant-entity-feature-bindings", id.0))
            }
            AuthoritativeDependency::BodyFeatureSuppression(definition, body) => {
                return self.catalog.format(
                    "assistant-target-body-suppression",
                    &BTreeMap::from([
                        ("definition", definition.0.to_string()),
                        ("body", body.0.to_string()),
                    ]),
                );
            }
            AuthoritativeDependency::Occurrence(id) => Some(("assistant-entity-occurrence", id.0)),
            AuthoritativeDependency::GroundedOccurrence(id) => {
                Some(("assistant-entity-grounded-occurrence", id.0))
            }
            AuthoritativeDependency::AssemblyMate(id) => {
                Some(("assistant-entity-assembly-mate", id.0))
            }
            AuthoritativeDependency::AssemblyJoint(id) => {
                Some(("assistant-entity-assembly-joint", id.0))
            }
            AuthoritativeDependency::AssemblyMotionCoupling(id) => {
                Some(("assistant-entity-assembly-motion-coupling", id.0))
            }
            AuthoritativeDependency::AssemblyMotionStudy(id) => {
                Some(("assistant-entity-assembly-motion-study", id.0))
            }
            AuthoritativeDependency::MechanicalInterface(id) => {
                Some(("assistant-entity-mechanical-interface", id.0))
            }
            AuthoritativeDependency::MechanicalCondition(id) => {
                Some(("assistant-entity-mechanical-condition", id.0))
            }
            AuthoritativeDependency::DrawingSheet(_) => None,
            AuthoritativeDependency::OccurrenceCollections(id) => {
                Some(("assistant-entity-occurrence-collections", id.0))
            }
            AuthoritativeDependency::Group(id) => Some(("assistant-entity-group", id.0)),
            AuthoritativeDependency::GroupChildren(id) => {
                Some(("assistant-entity-group-children", id.0))
            }
            AuthoritativeDependency::GroupSubtree(id) => {
                Some(("assistant-entity-group-subtree", id.0))
            }
            AuthoritativeDependency::FeatureParameterBinding(target) => {
                return self.catalog.format(
                    "assistant-target-feature-parameter",
                    &BTreeMap::from([
                        ("feature", target.feature_id.0.to_string()),
                        ("slot", target.path.as_str().to_owned()),
                    ]),
                );
            }
            AuthoritativeDependency::LocalGroup(key) => {
                return self.catalog.format(
                    "assistant-target-local-group",
                    &BTreeMap::from([
                        ("definition", key.definition_id.0.to_string()),
                        ("local", key.local_id.0.to_string()),
                    ]),
                );
            }
            AuthoritativeDependency::LocalOccurrence(key) => {
                return self.catalog.format(
                    "assistant-target-local-occurrence",
                    &BTreeMap::from([
                        ("definition", key.definition_id.0.to_string()),
                        ("local", key.local_id.0.to_string()),
                    ]),
                );
            }
        };
        identified.map_or_else(
            || self.catalog.text("assistant-target-canonical"),
            |(kind, id)| {
                self.catalog.format(
                    "assistant-target-identified",
                    &BTreeMap::from([("kind", self.catalog.text(kind)), ("id", id.to_string())]),
                )
            },
        )
    }

    fn assistant_derived_identity_label(identity: &DerivedIdentity) -> String {
        let path = identity
            .slot_path
            .segments()
            .iter()
            .map(|segment| {
                format!(
                    "{}:{}:{}",
                    segment.producer_rule_id.0, segment.output_port, segment.semantic_key
                )
            })
            .collect::<Vec<_>>()
            .join(" / ");
        format!("{} / {path}", identity.root_rule_node_id.0)
    }

    fn assistant_rule_outputs_label(outputs: &[RuleOutput]) -> String {
        fn collect(output: &RuleOutput, prefix: &str, labels: &mut Vec<String>) {
            let segment = output.segment();
            let current = format!(
                "{prefix}{}:{}:{}",
                segment.producer_rule_id.0, segment.output_port, segment.semantic_key
            );
            labels.push(current.clone());
            for child in output.children() {
                collect(child, &format!("{current} / "), labels);
            }
        }

        let mut labels = Vec::new();
        for output in outputs {
            collect(output, "", &mut labels);
        }
        labels.join(", ")
    }

    fn assistant_instance_path_label(path: &InstancePath) -> String {
        let mut label = path.root_occurrence().0.to_string();
        for step in path.steps() {
            match step {
                ketchup_core::document::InstancePathStep::Group(id) => {
                    label.push_str(&format!(" / G{}", id.0));
                }
                ketchup_core::document::InstancePathStep::Occurrence(id) => {
                    label.push_str(&format!(" / O{}", id.0));
                }
            }
        }
        label
    }

    fn assistant_transform_matrix_label(transform: &Transform) -> String {
        transform
            .matrix()
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>()
            .join(", ")
    }

    fn assistant_proposal_diff_label(
        &self,
        target: &AuthoritativeDependency,
        before: &ProposalValue,
        after: &ProposalValue,
    ) -> String {
        let target = self.assistant_proposal_target_label(target);
        let key = match (before, after) {
            (ProposalValue::Missing, ProposalValue::Digest(_))
            | (ProposalValue::Missing, ProposalValue::Missing) => "assistant-diff-created-opaque",
            (ProposalValue::Missing, _) => "assistant-diff-created",
            (_, ProposalValue::Missing) => "assistant-diff-removed",
            (ProposalValue::Digest(_), _) | (_, ProposalValue::Digest(_)) => {
                "assistant-diff-updated-opaque"
            }
            _ => "assistant-diff-changed",
        };
        self.catalog.format(
            key,
            &BTreeMap::from([
                ("target", target),
                ("before", self.assistant_proposal_value_label(before)),
                ("after", self.assistant_proposal_value_label(after)),
            ]),
        )
    }

    fn assistant_proposal_value_label(&self, value: &ProposalValue) -> String {
        match value {
            ProposalValue::Missing => self.catalog.text("assistant-value-missing"),
            ProposalValue::Boolean(value) => self.catalog.text(if *value {
                "assistant-value-true"
            } else {
                "assistant-value-false"
            }),
            ProposalValue::Dimension(value) => self.catalog.format(
                "assistant-value-dimension",
                &BTreeMap::from([
                    ("source", value.source_token().to_owned()),
                    ("value", value.millimetres().to_string()),
                ]),
            ),
            ProposalValue::BottleEdgeFinishKind(BottleEdgeFinishKind::Fillet) => {
                self.catalog.text("assistant-value-fillet")
            }
            ProposalValue::BottleEdgeFinishKind(BottleEdgeFinishKind::Chamfer) => {
                self.catalog.text("assistant-value-chamfer")
            }
            ProposalValue::ProfilePoints(points) => self.catalog.format(
                "assistant-value-profile-points",
                &BTreeMap::from([(
                    "points",
                    points
                        .iter()
                        .map(|point| format!("{},{}", point[0], point[1]))
                        .collect::<Vec<_>>()
                        .join("; "),
                )]),
            ),
            ProposalValue::Transform(value) => self.catalog.format(
                "assistant-value-transform",
                &BTreeMap::from([("matrix", Self::assistant_transform_matrix_label(value))]),
            ),
            ProposalValue::Tag(Some(id)) => self.catalog.format(
                "assistant-value-tag",
                &BTreeMap::from([("id", id.0.to_string())]),
            ),
            ProposalValue::Tag(None) => self.catalog.text("assistant-value-no-tag"),
            ProposalValue::Definition(id) => self.catalog.format(
                "assistant-value-definition",
                &BTreeMap::from([("id", id.0.to_string())]),
            ),
            ProposalValue::Group(Some(id)) => self.catalog.format(
                "assistant-value-group",
                &BTreeMap::from([("id", id.0.to_string())]),
            ),
            ProposalValue::Group(None) => self.catalog.text("assistant-value-no-group"),
            ProposalValue::Occurrences(ids) => self.catalog.format(
                "assistant-value-occurrences",
                &BTreeMap::from([(
                    "ids",
                    ids.iter()
                        .map(|id| id.0.to_string())
                        .collect::<Vec<_>>()
                        .join(", "),
                )]),
            ),
            ProposalValue::Text(value) => value.clone(),
            ProposalValue::Digest(value) => self.catalog.format(
                "assistant-value-digest",
                &BTreeMap::from([("digest", value.clone())]),
            ),
            ProposalValue::EvaluatorInputState {
                name,
                dimension,
                dependencies,
            } => self.catalog.format(
                "assistant-value-evaluator-input-state",
                &BTreeMap::from([
                    ("name", name.clone()),
                    ("source", dimension.source_token().to_owned()),
                    ("value", dimension.millimetres().to_string()),
                    (
                        "dependencies",
                        dependencies
                            .iter()
                            .map(|id| id.0.to_string())
                            .collect::<Vec<_>>()
                            .join(", "),
                    ),
                ]),
            ),
            ProposalValue::EvaluatorExpressionState {
                name,
                expression,
                dependencies,
            } => self.catalog.format(
                "assistant-value-evaluator-expression-state",
                &BTreeMap::from([
                    ("name", name.clone()),
                    ("expression", expression.clone()),
                    (
                        "dependencies",
                        dependencies
                            .iter()
                            .map(|id| id.0.to_string())
                            .collect::<Vec<_>>()
                            .join(", "),
                    ),
                ]),
            ),
            ProposalValue::EvaluatorRuleState {
                name,
                expression,
                dependencies,
                input_ports,
                output_ports,
                outputs,
                override_parameters,
            } => self.catalog.format(
                "assistant-value-evaluator-rule-state",
                &BTreeMap::from([
                    ("name", name.clone()),
                    ("expression", expression.clone()),
                    (
                        "dependencies",
                        dependencies
                            .iter()
                            .map(|id| id.0.to_string())
                            .collect::<Vec<_>>()
                            .join(", "),
                    ),
                    (
                        "inputs",
                        input_ports
                            .iter()
                            .map(|port| port.name().to_owned())
                            .collect::<Vec<_>>()
                            .join(", "),
                    ),
                    (
                        "output-ports",
                        output_ports
                            .iter()
                            .map(|port| port.name().to_owned())
                            .collect::<Vec<_>>()
                            .join(", "),
                    ),
                    ("outputs", Self::assistant_rule_outputs_label(outputs)),
                    (
                        "overrides",
                        override_parameters
                            .iter()
                            .map(|parameter| parameter.name().to_owned())
                            .collect::<Vec<_>>()
                            .join(", "),
                    ),
                ]),
            ),
            ProposalValue::RuleOverrideState {
                target,
                parameter,
                value,
                health,
            } => {
                let health = match health {
                    ketchup_core::graph::SlotResolution::Resolved => {
                        self.catalog.text("assistant-health-resolved")
                    }
                    ketchup_core::graph::SlotResolution::Ambiguous { segment_index } => {
                        self.catalog.format(
                            "assistant-health-ambiguous",
                            &BTreeMap::from([("segment", segment_index.to_string())]),
                        )
                    }
                    ketchup_core::graph::SlotResolution::Lost { segment_index } => {
                        self.catalog.format(
                            "assistant-health-lost",
                            &BTreeMap::from([("segment", segment_index.to_string())]),
                        )
                    }
                };
                self.catalog.format(
                    "assistant-value-rule-override-state",
                    &BTreeMap::from([
                        ("rule", target.root_rule_node_id.0.to_string()),
                        ("path", Self::assistant_derived_identity_label(target)),
                        ("parameter", parameter.clone()),
                        ("value", value.to_string()),
                        ("health", health),
                    ]),
                )
            }
            ProposalValue::FeatureParameterBindingState {
                target,
                derived_from,
            } => self.catalog.format(
                "assistant-value-feature-parameter-binding-state",
                &BTreeMap::from([
                    ("feature", target.feature_id.0.to_string()),
                    ("slot", target.path.as_str().to_owned()),
                    ("rule", derived_from.root_rule_node_id.0.to_string()),
                    ("path", Self::assistant_derived_identity_label(derived_from)),
                ]),
            ),
            ProposalValue::JointState {
                participant_a,
                participant_b,
                volume_min,
                volume_max,
            } => self.catalog.format(
                "assistant-value-joint-state",
                &BTreeMap::from([
                    (
                        "participant-a",
                        Self::assistant_derived_identity_label(participant_a),
                    ),
                    (
                        "participant-b",
                        Self::assistant_derived_identity_label(participant_b),
                    ),
                    (
                        "min",
                        format!("{},{},{}", volume_min[0], volume_min[1], volume_min[2]),
                    ),
                    (
                        "max",
                        format!("{},{},{}", volume_max[0], volume_max[1], volume_max[2]),
                    ),
                ]),
            ),
            ProposalValue::SpaceState {
                purpose,
                volume_min,
                volume_max,
                adjacent_to,
                accessible_to,
            } => self.catalog.format(
                "assistant-value-space-state",
                &BTreeMap::from([
                    ("purpose", purpose.clone()),
                    (
                        "min",
                        format!("{},{},{}", volume_min[0], volume_min[1], volume_min[2]),
                    ),
                    (
                        "max",
                        format!("{},{},{}", volume_max[0], volume_max[1], volume_max[2]),
                    ),
                    (
                        "adjacent",
                        adjacent_to
                            .iter()
                            .map(|id| id.0.to_string())
                            .collect::<Vec<_>>()
                            .join(", "),
                    ),
                    (
                        "accessible",
                        accessible_to
                            .iter()
                            .map(|id| id.0.to_string())
                            .collect::<Vec<_>>()
                            .join(", "),
                    ),
                ]),
            ),
            ProposalValue::ClearanceVolumeState {
                owner,
                reason,
                volume_min,
                volume_max,
                coordinate_frame: _,
                tolerance_mm,
                severity,
                derived_from,
            } => {
                let owner = match owner {
                    ketchup_core::space::ClearanceOwner::Occurrence(path) => {
                        Self::assistant_instance_path_label(path)
                    }
                    ketchup_core::space::ClearanceOwner::Space(id) => id.0.to_string(),
                };
                let severity = match severity {
                    ClearanceSeverity::Advisory => "assistant-severity-advisory",
                    ClearanceSeverity::Required => "assistant-severity-required",
                };
                self.catalog.format(
                    "assistant-value-clearance-volume-state",
                    &BTreeMap::from([
                        ("reason", reason.clone()),
                        ("owner", owner),
                        (
                            "min",
                            format!("{},{},{}", volume_min[0], volume_min[1], volume_min[2]),
                        ),
                        (
                            "max",
                            format!("{},{},{}", volume_max[0], volume_max[1], volume_max[2]),
                        ),
                        ("frame", self.catalog.text("assistant-frame-world")),
                        ("tolerance", tolerance_mm.to_string()),
                        ("severity", self.catalog.text(severity)),
                        (
                            "derived",
                            derived_from.as_ref().map_or_else(
                                || self.catalog.text("assistant-value-missing"),
                                Self::assistant_derived_identity_label,
                            ),
                        ),
                    ]),
                )
            }
            ProposalValue::PersistentDimensionState {
                name,
                target,
                presentation,
            } => {
                let target = match target {
                    ketchup_core::document::PersistentDimensionTarget::FeatureParameter(target) => {
                        format!("{}:{}", target.feature_id.0, target.path.as_str())
                    }
                    ketchup_core::document::PersistentDimensionTarget::DerivedOutput(identity) => {
                        Self::assistant_derived_identity_label(identity)
                    }
                    ketchup_core::document::PersistentDimensionTarget::ExactFeatureParameter {
                        definition_id,
                        producer_feature_id,
                        semantic_role,
                        source_element_id,
                        path,
                        value_type,
                    } => format!(
                        "{}:{}:{}:{}:{}:{value_type:?}",
                        definition_id.0,
                        producer_feature_id.0,
                        semantic_role,
                        source_element_id,
                        path.as_str()
                    ),
                };
                self.catalog.format(
                    "assistant-value-persistent-dimension-state",
                    &BTreeMap::from([
                        ("name", name.clone()),
                        ("target", target),
                        ("unit", presentation.unit.label().to_owned()),
                        ("precision", presentation.decimal_places.to_string()),
                    ]),
                )
            }
            ProposalValue::RuleOutputs(outputs) => self.catalog.format(
                "assistant-value-rule-outputs",
                &BTreeMap::from([("outputs", Self::assistant_rule_outputs_label(outputs))]),
            ),
            ProposalValue::TagState { name, visible } => self.catalog.format(
                "assistant-value-tag-state",
                &BTreeMap::from([
                    ("name", name.clone()),
                    (
                        "visible",
                        self.catalog.text(if *visible {
                            "assistant-value-true"
                        } else {
                            "assistant-value-false"
                        }),
                    ),
                ]),
            ),
            ProposalValue::CollectionState {
                name,
                occurrence_ids,
            } => self.catalog.format(
                "assistant-value-collection-state",
                &BTreeMap::from([
                    ("name", name.clone()),
                    (
                        "ids",
                        occurrence_ids
                            .iter()
                            .map(|id| id.0.to_string())
                            .collect::<Vec<_>>()
                            .join(", "),
                    ),
                ]),
            ),
            ProposalValue::DefinitionState {
                name,
                feature_ids,
                local_occurrence_ids,
                local_group_ids,
            } => self.catalog.format(
                "assistant-value-definition-state",
                &BTreeMap::from([
                    ("name", name.clone()),
                    (
                        "features",
                        feature_ids
                            .iter()
                            .map(|id| id.0.to_string())
                            .collect::<Vec<_>>()
                            .join(", "),
                    ),
                    (
                        "occurrences",
                        local_occurrence_ids
                            .iter()
                            .map(|id| id.0.to_string())
                            .collect::<Vec<_>>()
                            .join(", "),
                    ),
                    (
                        "groups",
                        local_group_ids
                            .iter()
                            .map(|id| id.0.to_string())
                            .collect::<Vec<_>>()
                            .join(", "),
                    ),
                ]),
            ),
            ProposalValue::DefinitionFeatures(ids) => self.catalog.format(
                "assistant-value-definition-features",
                &BTreeMap::from([(
                    "ids",
                    ids.iter()
                        .map(|id| id.0.to_string())
                        .collect::<Vec<_>>()
                        .join(", "),
                )]),
            ),
            ProposalValue::ProfileFeatureState {
                definition,
                name,
                points_mm,
            } => self.catalog.format(
                "assistant-value-profile-feature-state",
                &BTreeMap::from([
                    ("name", name.clone()),
                    ("definition", definition.0.to_string()),
                    (
                        "points",
                        points_mm
                            .iter()
                            .map(|point| format!("{},{}", point[0], point[1]))
                            .collect::<Vec<_>>()
                            .join("; "),
                    ),
                ]),
            ),
            ProposalValue::GroupState {
                name,
                transform,
                parent,
            } => {
                let matrix = transform.matrix();
                self.catalog.format(
                    "assistant-value-group-state",
                    &BTreeMap::from([
                        ("name", name.clone()),
                        ("x", matrix[3].to_string()),
                        ("y", matrix[7].to_string()),
                        ("z", matrix[11].to_string()),
                        ("matrix", Self::assistant_transform_matrix_label(transform)),
                        (
                            "parent",
                            parent.map_or_else(
                                || self.catalog.text("assistant-value-no-group"),
                                |id| id.0.to_string(),
                            ),
                        ),
                    ]),
                )
            }
            ProposalValue::OccurrenceState {
                definition,
                name,
                transform,
                parent,
                tag,
                visible,
            } => {
                let matrix = transform.matrix();
                self.catalog.format(
                    "assistant-value-occurrence-state",
                    &BTreeMap::from([
                        ("name", name.clone()),
                        ("definition", definition.0.to_string()),
                        ("x", matrix[3].to_string()),
                        ("y", matrix[7].to_string()),
                        ("z", matrix[11].to_string()),
                        ("matrix", Self::assistant_transform_matrix_label(transform)),
                        (
                            "parent",
                            parent.map_or_else(
                                || self.catalog.text("assistant-value-no-group"),
                                |id| id.0.to_string(),
                            ),
                        ),
                        (
                            "tag",
                            tag.map_or_else(
                                || self.catalog.text("assistant-value-no-tag"),
                                |id| id.0.to_string(),
                            ),
                        ),
                        (
                            "visible",
                            self.catalog.text(if *visible {
                                "assistant-value-true"
                            } else {
                                "assistant-value-false"
                            }),
                        ),
                    ]),
                )
            }
        }
    }

    fn assistant_proposal_is_low_risk(proposal: &Proposal) -> bool {
        matches!(
            proposal.goal(),
            ProposalGoal::SetRuleDimension(_)
                | ProposalGoal::SetFeatureDimension(_)
                | ProposalGoal::SetBottleControlDimension(_, _)
                | ProposalGoal::SetBottleEdgeFinishKind(_)
                | ProposalGoal::SetOccurrenceVisibility(_)
                | ProposalGoal::SetTagVisibility(_)
        )
    }

    #[must_use]
    pub const fn assistant_provider(&self) -> AssistantProvider {
        self.assistant_provider
    }

    #[must_use]
    pub fn assistant_model(&self) -> &str {
        &self.assistant_model
    }

    pub fn select_assistant_provider(&mut self, provider: AssistantProvider) {
        self.assistant_provider = provider;
        self.assistant_model = provider.default_model().to_owned();
    }

    pub fn set_assistant_model(&mut self, model: impl Into<String>) {
        self.assistant_model = model.into();
    }

    #[must_use]
    pub const fn assistant_workspace_mode(&self) -> AssistantWorkspaceMode {
        self.assistant_workspace_mode
    }

    pub fn set_assistant_workspace_mode(&mut self, mode: AssistantWorkspaceMode) {
        self.assistant_workspace_mode = mode;
    }

    #[must_use]
    pub fn assistant_messages(&self) -> &[AssistantChatMessage] {
        &self.assistant_messages
    }

    pub fn new_assistant_chat(&mut self) {
        self.assistant_input.clear();
        self.assistant_messages.clear();
        self.cancel_pending_assistant_work();
        self.assistant_verification = None;
        self.assistant_request_sequence = self.assistant_request_sequence.saturating_add(1);
        self.store_assistant_conversation();
    }

    fn store_assistant_conversation(&mut self) {
        let conversation = AssistantConversation {
            document_id: self.document.current().document_id().0,
            messages: self.assistant_messages.clone(),
        };
        let Ok(bytes) = serde_json::to_vec(&conversation) else {
            return;
        };
        let Ok(entry) = ketchup_core::persistence::ExtensionEntry::new(
            ASSISTANT_CHAT_NAMESPACE,
            ASSISTANT_CHAT_PATH,
            false,
            bytes,
        ) else {
            return;
        };
        self.container_data.set_extension(entry);
    }

    fn store_assistant_memory(&mut self) {
        let Ok(bytes) = serde_json::to_vec(&self.assistant_memory) else {
            return;
        };
        if bytes.len() > MAX_ASSISTANT_MEMORY_STORAGE_BYTES {
            return;
        }
        let Ok(entry) = ketchup_core::persistence::ExtensionEntry::new(
            ASSISTANT_CHAT_NAMESPACE,
            ASSISTANT_MEMORY_PATH,
            false,
            bytes,
        ) else {
            return;
        };
        self.container_data.set_extension(entry);
    }

    fn remember_latest_assistant_exchange(&mut self, answer: &str) {
        let Some(user) = self
            .assistant_messages
            .iter()
            .rev()
            .find(|message| message.role == AssistantMessageRole::User)
            .map(|message| message.text.clone())
        else {
            return;
        };
        self.assistant_memory.remember(&user, answer);
        self.store_assistant_memory();
    }

    fn load_assistant_conversation(&mut self) {
        let document_id = self.document.current().document_id().0;
        self.assistant_messages = self
            .container_data
            .extensions()
            .find(|entry| {
                entry.namespace() == ASSISTANT_CHAT_NAMESPACE && entry.path() == ASSISTANT_CHAT_PATH
            })
            .and_then(|entry| serde_json::from_slice::<AssistantConversation>(entry.bytes()).ok())
            .filter(|conversation| {
                conversation.document_id == document_id
                    && conversation.messages.iter().all(|message| {
                        message
                            .diagnostic
                            .as_ref()
                            .is_none_or(|diagnostic| diagnostic.validate().is_ok())
                    })
            })
            .map_or_else(Vec::new, |conversation| conversation.messages);
        self.saved_assistant_conversation_digest =
            assistant_conversation_digest(&self.assistant_messages);
    }

    fn load_assistant_memory(&mut self) {
        let document_id = self.document.current().document_id().0;
        self.assistant_memory = self
            .container_data
            .extensions()
            .find(|entry| {
                entry.namespace() == ASSISTANT_CHAT_NAMESPACE
                    && entry.path() == ASSISTANT_MEMORY_PATH
            })
            .filter(|entry| entry.bytes().len() <= MAX_ASSISTANT_MEMORY_STORAGE_BYTES)
            .and_then(|entry| serde_json::from_slice::<AssistantProjectMemory>(entry.bytes()).ok())
            .filter(|memory| memory.validate(document_id))
            .unwrap_or_else(|| AssistantProjectMemory::empty(document_id));
    }

    #[must_use]
    pub fn assistant_models(&self) -> Vec<String> {
        assistant_models_for(self.assistant_provider)
    }

    fn assistant_source_label(&self) -> String {
        format!(
            "{} · {}",
            self.catalog.text(self.assistant_provider.label_key()),
            self.assistant_model
        )
    }

    #[must_use]
    pub fn assistant_handshake(&self) -> AssistantHandshake {
        let mut capabilities = BTreeSet::from([
            AssistantCapability::Chat,
            AssistantCapability::LocalMemory,
            AssistantCapability::QueryDocument,
            AssistantCapability::ProposeWorkflowIntent,
        ]);
        if self.assistant_diagnostics_enabled {
            capabilities.insert(AssistantCapability::DebugObservability);
        }
        AssistantHandshake {
            protocol_version: ASSISTANT_PROTOCOL_VERSION,
            distribution: self.assistant_provider.distribution(),
            provider: self.assistant_provider.protocol_name().to_owned(),
            model: self.assistant_model.clone(),
            capabilities,
        }
    }

    pub fn assistant_context(&self) -> serde_json::Value {
        self.assistant_context_for("")
    }

    fn assistant_validation_context(
        &self,
        snapshot: &Snapshot,
        exact_results: &ExactResultRegistry,
        selection: &AssistantValidationSelection,
    ) -> serde_json::Value {
        let tolerance = TolerancePolicy::default();
        let visible_occurrences = snapshot
            .scene_query()
            .into_iter()
            .filter(|occurrence| occurrence.visible)
            .collect::<Vec<_>>();
        let requested = ASSISTANT_VALIDATOR_IDS
            .into_iter()
            .filter(|validator| selection.requested.contains(validator))
            .collect::<Vec<_>>();
        let skipped = ASSISTANT_VALIDATOR_IDS
            .into_iter()
            .filter(|validator| !selection.requested.contains(validator))
            .collect::<Vec<_>>();
        if !selection.is_valid() {
            let not_evaluated = selection
                .unknown
                .iter()
                .map(|name| {
                    serde_json::json!({
                        "validator": name,
                        "reason": "unknown_validator",
                    })
                })
                .collect::<Vec<_>>();
            return serde_json::json!({
                "schema": "ketchup.assistant-validation-context.v1",
                "document_id": snapshot.document_id().0,
                "revision": snapshot.revision_id(),
                "canonical_digest": snapshot.canonical_digest(),
                "selection_mode": selection.mode,
                "requested": requested,
                "executed": [],
                "skipped": ASSISTANT_VALIDATOR_IDS,
                "not_evaluated": not_evaluated,
                "selection_error": "unknown_or_empty_validator_selection",
                "state": "not_evaluated",
                "complete": false,
                "visible_occurrence_count": visible_occurrences.len(),
                "checked_occurrence_count": 0,
                "checked_pair_count": 0,
                "issue_count": 0,
                "issues_complete": true,
                "issues": [],
                "collision": {
                    "state": "skipped",
                    "complete": false,
                    "checked_occurrence_count": 0,
                    "checked_pair_count": 0,
                    "issue_count": 0,
                    "issues_complete": true,
                    "issues": [],
                },
                "gravity_support": {
                    "state": "skipped",
                    "complete": false,
                    "gravity_axis": "-Z",
                    "floor_z_mm": 0.0,
                    "checked_occurrence_count": 0,
                    "unsupported_count": 0,
                    "issues_complete": true,
                    "issues": [],
                    "assumptions": [],
                },
                "shelf_deflection": {
                    "state": "skipped",
                    "complete": false,
                    "applicable_count": 0,
                    "issue_count": 0,
                    "issues": [],
                },
                "tipping": {
                    "state": "skipped",
                    "complete": false,
                    "applicable_count": 0,
                    "issue_count": 0,
                    "issues": [],
                },
                "anchoring": {
                    "state": "skipped",
                    "complete": false,
                    "applicable_count": 0,
                    "required_count": 0,
                    "issue_count": 0,
                    "issues": [],
                },
                "hardware_manufacturing": {
                    "state": "skipped",
                    "complete": false,
                    "applicable_count": 0,
                    "issue_count": 0,
                    "issues": [],
                    "not_evaluated": [],
                },
                "room_placement": {
                    "state": "skipped",
                    "complete": false,
                    "applicable_count": 0,
                    "issue_count": 0,
                    "issues": [],
                    "not_evaluated": [],
                },
                "passage_clearance": {
                    "state": "skipped",
                    "complete": false,
                    "applicable_count": 0,
                    "issue_count": 0,
                    "issues": [],
                    "not_evaluated": [],
                },
                "static_load": {
                    "state": "skipped",
                    "complete": false,
                    "applicable_count": 0,
                    "issue_count": 0,
                    "issues": [],
                    "not_evaluated": [],
                },
                "unavailable_occurrences": [],
            });
        }
        let occurrence_limit_complete =
            visible_occurrences.len() <= MAX_ASSISTANT_VALIDATION_OCCURRENCES;
        let names = visible_occurrences
            .iter()
            .take(MAX_ASSISTANT_VALIDATION_OCCURRENCES)
            .map(|occurrence| {
                (
                    occurrence.instance_path.root_occurrence(),
                    occurrence.occurrence_name.clone(),
                )
            })
            .collect::<BTreeMap<_, _>>();
        let mut participants = Vec::new();
        let mut unavailable = Vec::new();
        for occurrence in visible_occurrences
            .iter()
            .take(MAX_ASSISTANT_VALIDATION_OCCURRENCES)
        {
            match GeneralBodyParticipant::accept(
                snapshot,
                exact_results,
                occurrence.instance_path.clone(),
                tolerance,
            ) {
                Ok(participant) => participants.push(participant),
                Err(error) => unavailable.push(serde_json::json!({
                    "occurrence_id": occurrence.instance_path.root_occurrence().0,
                    "name": occurrence.occurrence_name.clone(),
                    "reason": format!("{error:?}"),
                })),
            }
        }
        let validator_roles = ValidatorRoleIndex::from_snapshot(snapshot);
        let gravity_participants = validator_roles
            .as_ref()
            .ok()
            .map(|roles| {
                participants
                    .iter()
                    .filter_map(|body| {
                        let occurrence_id = body.instance_path().root_occurrence();
                        let role = roles
                            .role(occurrence_id)
                            .and_then(|role| assistant_physics_role(role.as_str()))?;
                        matches!(
                            role.kind,
                            AssistantPhysicsRoleKind::GravityBody
                                | AssistantPhysicsRoleKind::GravityGround
                        )
                        .then(|| {
                            GravitySupportParticipant::new(
                                body.clone(),
                                role.group,
                                role.kind == AssistantPhysicsRoleKind::GravityGround
                                    || snapshot.occurrence_is_grounded(occurrence_id),
                            )
                        })
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        let gravity_validator_input = assistant_gravity_input(snapshot)
            .ok()
            .filter(|_| !gravity_participants.is_empty())
            .and_then(|gravity| {
                GravitySupportInput::new(gravity_participants.clone(), gravity.vector_m_s2).ok()
            });
        let mut cases = Vec::new();
        if selection.requested.contains("collision") {
            for left_index in 0..participants.len() {
                for right in &participants[left_index + 1..] {
                    cases.push(
                        GeneralClearanceCase::new(
                            participants[left_index].clone(),
                            right.clone(),
                            0.0,
                        )
                        .expect("zero collision clearance is valid"),
                    );
                }
            }
        }
        let report = selection.requested.contains("collision").then(|| {
            let validator = BuiltinGeneralBodyValidator::new(tolerance);
            let policy = general_body_validation_policy();
            let input = general_body_input_bytes(&cases);
            let invocation = ValidationInvocation::bind(
                snapshot,
                validator.descriptor(),
                &policy,
                Vec::new(),
                &input,
            );
            validator.invoke(ValidationExecution {
                snapshot,
                invocation,
                policy: &policy,
                input: &cases,
            })
        });
        let gravity_report = selection
            .requested
            .contains("gravity_support")
            .then_some(gravity_validator_input.as_ref())
            .flatten()
            .map(|validator_input| {
                let validator = BuiltinGravitySupportValidator::new(tolerance);
                let policy = gravity_support_validation_policy();
                let input = gravity_support_input_bytes(validator_input);
                let invocation = ValidationInvocation::bind(
                    snapshot,
                    validator.descriptor(),
                    &policy,
                    Vec::new(),
                    &input,
                );
                validator.invoke(ValidationExecution {
                    snapshot,
                    invocation,
                    policy: &policy,
                    input: validator_input,
                })
            });
        let coverage_complete = occurrence_limit_complete && unavailable.is_empty();
        let shelf_deflection = assistant_shelf_deflection_report(
            &participants,
            &names,
            &validator_roles,
            selection.requested.contains("shelf_deflection"),
            coverage_complete,
        );
        let tipping = assistant_tipping_report(
            &participants,
            &names,
            &validator_roles,
            selection.requested.contains("tipping"),
            coverage_complete,
        );
        let anchoring = assistant_anchoring_report(
            &participants,
            &names,
            &validator_roles,
            selection.requested.contains("anchoring"),
            coverage_complete,
        );
        let hardware_manufacturing = assistant_hardware_manufacturing_report(
            &participants,
            &names,
            &validator_roles,
            selection.requested.contains("hardware_manufacturing"),
            coverage_complete,
        );
        let room_placement = assistant_room_placement_report(
            &participants,
            &names,
            &validator_roles,
            tolerance,
            selection.requested.contains("room_placement"),
            coverage_complete,
        );
        let passage_clearance = assistant_passage_clearance_report(
            &participants,
            &names,
            &validator_roles,
            tolerance,
            selection.requested.contains("passage_clearance"),
            coverage_complete,
        );
        let static_load = assistant_static_load_report(
            snapshot,
            &names,
            &validator_roles,
            selection.requested.contains("static_load"),
            coverage_complete,
        );
        let (collision_state, issue_count, issues) = if let Some(report) = &report {
            let issue_count = report
                .diagnostics
                .iter()
                .filter(|diagnostic| diagnostic.code == "collision.detected")
                .count();
            let issues = cases
                .iter()
                .zip(&report.diagnostics)
                .filter(|(_, diagnostic)| diagnostic.code == "collision.detected")
                .take(MAX_ASSISTANT_VALIDATION_ISSUES)
                .map(|(case, diagnostic)| {
                    let left_id = case.left.instance_path().root_occurrence();
                    let right_id = case.right.instance_path().root_occurrence();
                    serde_json::json!({
                        "code": diagnostic.code.as_str(),
                        "severity": match diagnostic.severity {
                            DiagnosticSeverity::Information => "information",
                            DiagnosticSeverity::Advisory => "advisory",
                            DiagnosticSeverity::Warning => "warning",
                            DiagnosticSeverity::Error => "error",
                        },
                        "evidence_class": match &diagnostic.evidence_class {
                            EvidenceClass::Exact => "exact",
                            EvidenceClass::Tolerant(_) => "tolerant",
                        },
                        "left_occurrence_id": left_id.0,
                        "left_name": names.get(&left_id),
                        "right_occurrence_id": right_id.0,
                        "right_name": names.get(&right_id),
                        "evidence": diagnostic.evidence.as_str(),
                    })
                })
                .collect::<Vec<_>>();
            let state = if report.state == ValidationState::Failed {
                "failed"
            } else if !coverage_complete {
                "not_evaluated"
            } else {
                match report.state {
                    ValidationState::Passed => "passed",
                    ValidationState::Failed => "failed",
                    ValidationState::NotEvaluated => "not_evaluated",
                    ValidationState::Unavailable => "unavailable",
                }
            };
            (state, issue_count, issues)
        } else {
            ("skipped", 0, Vec::new())
        };
        let (gravity_state, gravity_issue_count, gravity_issues, gravity_assumptions) =
            if let Some(report) = &gravity_report {
                let issue_count = report
                    .diagnostics
                    .iter()
                    .filter(|diagnostic| diagnostic.code == "gravity.unsupported")
                    .count();
                let issues = gravity_participants
                    .iter()
                    .zip(&report.diagnostics)
                    .filter(|(_, diagnostic)| diagnostic.code == "gravity.unsupported")
                    .take(MAX_ASSISTANT_VALIDATION_ISSUES)
                    .map(|(participant, diagnostic)| {
                        let occurrence_id = participant.body.instance_path().root_occurrence();
                        serde_json::json!({
                            "code": diagnostic.code.as_str(),
                            "severity": match diagnostic.severity {
                                DiagnosticSeverity::Information => "information",
                                DiagnosticSeverity::Advisory => "advisory",
                                DiagnosticSeverity::Warning => "warning",
                                DiagnosticSeverity::Error => "error",
                            },
                            "evidence_class": match &diagnostic.evidence_class {
                                EvidenceClass::Exact => "exact",
                                EvidenceClass::Tolerant(_) => "tolerant",
                            },
                            "occurrence_id": occurrence_id.0,
                            "name": names.get(&occurrence_id),
                            "evidence": diagnostic.evidence.as_str(),
                        })
                    })
                    .collect::<Vec<_>>();
                let state = if !coverage_complete {
                    "not_evaluated"
                } else {
                    match report.state {
                        ValidationState::Passed => "passed",
                        ValidationState::Failed => "failed",
                        ValidationState::NotEvaluated => "not_evaluated",
                        ValidationState::Unavailable => "unavailable",
                    }
                };
                (state, issue_count, issues, report.assumptions.clone())
            } else if selection.requested.contains("gravity_support") {
                (
                    "not_evaluated",
                    0,
                    Vec::new(),
                    vec![
                        "explicit gravity roles and a typed non-zero gravity vector are required"
                            .to_owned(),
                    ],
                )
            } else {
                ("skipped", 0, Vec::new(), Vec::new())
            };
        let shelf_state = shelf_deflection["state"]
            .as_str()
            .unwrap_or("not_evaluated");
        let tipping_state = tipping["state"].as_str().unwrap_or("not_evaluated");
        let anchoring_state = anchoring["state"].as_str().unwrap_or("not_evaluated");
        let hardware_manufacturing_state = hardware_manufacturing["state"]
            .as_str()
            .unwrap_or("not_evaluated");
        let room_placement_state = room_placement["state"].as_str().unwrap_or("not_evaluated");
        let passage_clearance_state = passage_clearance["state"]
            .as_str()
            .unwrap_or("not_evaluated");
        let static_load_state = static_load["state"].as_str().unwrap_or("not_evaluated");
        let shelf_issue_count = shelf_deflection["issue_count"].as_u64().unwrap_or(0) as usize;
        let tipping_issue_count = tipping["issue_count"].as_u64().unwrap_or(0) as usize;
        let anchoring_issue_count = anchoring["issue_count"].as_u64().unwrap_or(0) as usize;
        let hardware_manufacturing_issue_count =
            hardware_manufacturing["issue_count"].as_u64().unwrap_or(0) as usize;
        let room_placement_issue_count =
            room_placement["issue_count"].as_u64().unwrap_or(0) as usize;
        let passage_clearance_issue_count =
            passage_clearance["issue_count"].as_u64().unwrap_or(0) as usize;
        let static_load_issue_count = static_load["issue_count"].as_u64().unwrap_or(0) as usize;
        let mut not_evaluated = Vec::new();
        for (validator, validator_state) in [
            ("collision", collision_state),
            ("gravity_support", gravity_state),
            ("shelf_deflection", shelf_state),
            ("tipping", tipping_state),
            ("anchoring", anchoring_state),
            ("hardware_manufacturing", hardware_manufacturing_state),
            ("room_placement", room_placement_state),
            ("passage_clearance", passage_clearance_state),
            ("static_load", static_load_state),
        ] {
            if selection.requested.contains(validator)
                && (!coverage_complete
                    || matches!(validator_state, "not_evaluated" | "unavailable"))
            {
                not_evaluated.push(serde_json::json!({
                    "validator": validator,
                    "reason": if coverage_complete {
                        "validator_specific_context_unavailable"
                    } else {
                        "incomplete_geometry_coverage"
                    },
                }));
            }
        }
        let state = if [
            collision_state,
            gravity_state,
            shelf_state,
            tipping_state,
            anchoring_state,
            hardware_manufacturing_state,
            room_placement_state,
            passage_clearance_state,
            static_load_state,
        ]
        .contains(&"failed")
        {
            "failed"
        } else if not_evaluated.is_empty() {
            "passed"
        } else {
            "not_evaluated"
        };
        let complete = coverage_complete
            && not_evaluated.is_empty()
            && (!selection.requested.contains("collision")
                || issue_count <= MAX_ASSISTANT_VALIDATION_ISSUES)
            && (!selection.requested.contains("gravity_support")
                || gravity_issue_count <= MAX_ASSISTANT_VALIDATION_ISSUES)
            && (!selection.requested.contains("shelf_deflection")
                || shelf_deflection["complete"].as_bool() == Some(true))
            && (!selection.requested.contains("tipping")
                || tipping["complete"].as_bool() == Some(true))
            && (!selection.requested.contains("anchoring")
                || anchoring["complete"].as_bool() == Some(true))
            && (!selection.requested.contains("hardware_manufacturing")
                || hardware_manufacturing["complete"].as_bool() == Some(true))
            && (!selection.requested.contains("room_placement")
                || room_placement["complete"].as_bool() == Some(true))
            && (!selection.requested.contains("passage_clearance")
                || passage_clearance["complete"].as_bool() == Some(true))
            && (!selection.requested.contains("static_load")
                || static_load["complete"].as_bool() == Some(true));
        let total_issue_count = issue_count
            + gravity_issue_count
            + shelf_issue_count
            + tipping_issue_count
            + anchoring_issue_count
            + hardware_manufacturing_issue_count
            + room_placement_issue_count
            + passage_clearance_issue_count
            + static_load_issue_count;
        let mut all_issues = issues.clone();
        all_issues.extend(gravity_issues.iter().cloned());
        for report in [
            &shelf_deflection,
            &tipping,
            &anchoring,
            &hardware_manufacturing,
            &room_placement,
            &passage_clearance,
            &static_load,
        ] {
            all_issues.extend(report["issues"].as_array().into_iter().flatten().cloned());
        }
        all_issues.truncate(MAX_ASSISTANT_VALIDATION_ISSUES);
        serde_json::json!({
            "schema": "ketchup.assistant-validation-context.v1",
            "document_id": snapshot.document_id().0,
            "revision": snapshot.revision_id(),
            "canonical_digest": snapshot.canonical_digest(),
            "selection_mode": selection.mode,
            "requested": requested,
            "executed": requested,
            "skipped": skipped,
            "not_evaluated": not_evaluated,
            "selection_error": null,
            "state": state,
            "complete": complete,
            "visible_occurrence_count": visible_occurrences.len(),
            "checked_occurrence_count": participants.len(),
            "checked_pair_count": cases.len(),
            "issue_count": total_issue_count,
            "issues_complete": total_issue_count <= MAX_ASSISTANT_VALIDATION_ISSUES,
            "issues": all_issues,
            "collision": {
                "state": collision_state,
                "complete": selection.requested.contains("collision")
                    && coverage_complete
                    && issue_count <= MAX_ASSISTANT_VALIDATION_ISSUES,
                "checked_occurrence_count": if selection.requested.contains("collision") {
                    participants.len()
                } else {
                    0
                },
                "checked_pair_count": cases.len(),
                "issue_count": issue_count,
                "issues_complete": issue_count <= MAX_ASSISTANT_VALIDATION_ISSUES,
                "issues": issues,
            },
            "gravity_support": {
                "state": gravity_state,
                "complete": selection.requested.contains("gravity_support")
                    && coverage_complete
                    && gravity_issue_count <= MAX_ASSISTANT_VALIDATION_ISSUES,
                "gravity_axis": "-Z",
                "floor_z_mm": 0.0,
                "checked_occurrence_count": if selection.requested.contains("gravity_support") {
                    gravity_participants.len()
                } else {
                    0
                },
                "unsupported_count": gravity_issue_count,
                "issues_complete": gravity_issue_count <= MAX_ASSISTANT_VALIDATION_ISSUES,
                "issues": gravity_issues,
                "assumptions": gravity_assumptions,
            },
            "shelf_deflection": shelf_deflection,
            "tipping": tipping,
            "anchoring": anchoring,
            "hardware_manufacturing": hardware_manufacturing,
            "room_placement": room_placement,
            "passage_clearance": passage_clearance,
            "static_load": static_load,
            "unavailable_occurrences": unavailable,
        })
    }

    /// World bounds of every visible body, whatever answers for its geometry.
    ///
    /// The assistant reasons about extents, not about which painter owns a
    /// body, so this deliberately does not go through the render proxies: a
    /// cut or revolved body has no box proxy yet still has bounds, and
    /// describing it as absent would make the model plan around a void.
    fn assistant_body_bounds(
        &self,
        snapshot: &Snapshot,
    ) -> BTreeMap<OccurrenceId, (DefinitionId, [Vec3; 2])> {
        self.refresh_interaction_projection_cache(snapshot);
        let cache = self.interaction_projection_cache.borrow();
        cache
            .as_ref()
            .expect("interaction cache was built")
            .canonical
            .occurrences()
            .iter()
            .filter(|occurrence| occurrence.visible)
            .filter_map(|occurrence| {
                let [minimum, maximum] = self.definition_local_bounds(
                    snapshot,
                    occurrence.body.definition_id,
                    occurrence.local_box,
                )?;
                let size = maximum - minimum;
                let bounds = bounds_of(box_corners(size.x, size.y, size.z).into_iter().map(
                    |corner| {
                        transform_model_point(
                            occurrence.canonical_world_transform,
                            corner + minimum,
                        )
                    },
                ))?;
                Some((
                    occurrence.instance_path.root_occurrence(),
                    (occurrence.body.definition_id, bounds),
                ))
            })
            .collect()
    }

    fn assistant_context_for(&self, query: &str) -> serde_json::Value {
        let snapshot = self.document.current();
        let semantic_state = encode_semantic_state(&snapshot);
        let state_view = bounded_assistant_state_view(&semantic_state.agent_v1());
        let project_memory = self.assistant_memory.retrieval_context(query);
        let validation_selection = AssistantValidationSelection::parse(query);
        let validation = self.assistant_validation_context(
            &snapshot,
            &self.exact_results,
            &validation_selection,
        );
        let body_bounds = self.assistant_body_bounds(&snapshot);
        let box_bounds = body_bounds
            .iter()
            .map(|(occurrence_id, (_, bounds))| (*occurrence_id, *bounds))
            .collect::<BTreeMap<_, _>>();
        let scene_occurrences = snapshot.scene_query();
        let occurrence_count = scene_occurrences.len();
        let occurrences = scene_occurrences
            .into_iter()
            .take(100)
            .map(|occurrence| {
                let bounds = box_bounds
                    .get(&occurrence.occurrence_id)
                    .copied()
                    .or_else(|| assistant_mesh_body_bounds(&snapshot, &occurrence));
                serde_json::json!({
                    "occurrence_id": occurrence.occurrence_id.0,
                    "definition_id": occurrence.definition_id.0,
                    "name": occurrence.occurrence_name,
                    "visible": occurrence.visible,
                    "copyable": occurrence.instance_path.is_root(),
                    "bounds_mm": bounds.map(|[minimum, maximum]| serde_json::json!({
                        "min": [minimum.x, minimum.y, minimum.z],
                        "max": [maximum.x, maximum.y, maximum.z],
                    })),
                })
            })
            .collect::<Vec<_>>();
        let conversation = self
            .assistant_messages
            .iter()
            .rev()
            .take(20)
            .rev()
            .map(|message| {
                serde_json::json!({
                    "role": match message.role {
                        AssistantMessageRole::User => "user",
                        AssistantMessageRole::Assistant => "assistant",
                        AssistantMessageRole::Error => "error",
                    },
                    "text": message.text,
                    "diagnostic": message.diagnostic,
                })
            })
            .collect::<Vec<_>>();
        let selected_occurrence_ids = self
            .selected_occurrence_ids()
            .into_iter()
            .map(|id| id.0)
            .collect::<Vec<_>>();
        let selected_profile_translation_target = self.assistant_profile_translation_target().map(
            |(definition_id, body_id, profile_id, name)| {
                serde_json::json!({
                    "definition_id": definition_id.0,
                    "body_id": body_id.0,
                    "profile_id": profile_id.0,
                    "name": name,
                })
            },
        );
        let selected_parameter_edit_target = self.assistant_parameter_edit_target().map(
            |(definition_id, body_id, target, name, current_value_mm)| {
                let (feature_id, constraint_id) = match target {
                    ketchup_core::feature_history::ExactParameterEditTarget::FeatureDimension(
                        feature_id,
                    ) => (feature_id, None),
                    ketchup_core::feature_history::ExactParameterEditTarget::SketchConstraintDimension {
                        sketch_id,
                        constraint_id,
                    } => (sketch_id, Some(constraint_id.0)),
                };
                serde_json::json!({
                    "definition_id": definition_id.0,
                    "body_id": body_id.0,
                    "feature_id": feature_id.0,
                    "constraint_id": constraint_id,
                    "name": name,
                    "current_value_mm": current_value_mm,
                })
            },
        );
        let mut topology_face_references =
            assistant_topology_face_references(&snapshot, &self.topology_results);
        let topology_face_references_complete = topology_face_references.len() <= 64;
        topology_face_references.truncate(64);
        let topology_face_references = topology_face_references
            .into_iter()
            .map(|reference| {
                serde_json::json!({
                    "definition_id": reference.definition_id.0,
                    "target_feature_id": reference.producer_feature_id.0,
                    "reference_id": reference.lineage_digest,
                })
            })
            .collect::<Vec<_>>();
        let boxes = body_bounds
            .into_iter()
            .take(100)
            .map(|(occurrence_id, (definition_id, [minimum, maximum]))| {
                let size = maximum - minimum;
                serde_json::json!({
                    "occurrence_id": occurrence_id.0,
                    "definition_id": definition_id.0,
                    "origin_mm": [minimum.x, minimum.y, minimum.z],
                    "size_mm": [size.x, size.y, size.z],
                })
            })
            .collect::<Vec<_>>();
        serde_json::json!({
            "document_id": snapshot.document_id().0,
            "revision": snapshot.revision_id(),
            "canonical_digest": snapshot.canonical_digest(),
            "state_view": state_view,
            "project_memory": project_memory,
            "validation": validation,
            "selected_occurrence_ids": selected_occurrence_ids,
            "selected_group_id": self.selection.selected_group.map(|id| id.0),
            "selected_profile_translation_target": selected_profile_translation_target,
            "selected_parameter_edit_target": selected_parameter_edit_target,
            "topology_face_references_complete": topology_face_references_complete,
            "topology_face_references": topology_face_references,
            "occurrence_count": occurrence_count,
            "occurrences_complete": occurrence_count <= 100,
            "occurrences": occurrences,
            "boxes": boxes,
            "conversation": conversation,
        })
    }

    fn localized_assistant_rejection(
        &self,
        diagnostic: &AssistantRejectionDiagnostic,
        replan_will_run: bool,
    ) -> String {
        let mut text = self.catalog.format(
            "assistant-rejection-detail",
            &BTreeMap::from([
                (
                    "phase",
                    self.catalog
                        .text(assistant_rejection_phase_key(diagnostic.phase)),
                ),
                ("code", diagnostic.code.clone()),
                ("operation", diagnostic.operation.clone()),
                ("target", diagnostic.target.clone()),
                ("invariant", diagnostic.failed_invariant.clone()),
                ("repair", diagnostic.repair_hint.clone()),
                (
                    "retryable",
                    self.catalog.text(if diagnostic.retryable {
                        "assistant-value-true"
                    } else {
                        "assistant-value-false"
                    }),
                ),
            ]),
        );
        if replan_will_run {
            text.push('\n');
            text.push_str(&self.catalog.text("assistant-rejection-replan-once"));
        }
        text
    }

    fn record_assistant_rejection(
        &mut self,
        diagnostic: AssistantRejectionDiagnostic,
        replan_will_run: bool,
    ) -> AssistantRejectionDiagnostic {
        self.assistant_proposal = None;
        self.digest = self.catalog.format(
            "assistant-digest-rejected",
            &BTreeMap::from([("reason", diagnostic.failed_invariant.clone())]),
        );
        self.assistant_messages.push(AssistantChatMessage {
            role: AssistantMessageRole::Error,
            text: self.localized_assistant_rejection(&diagnostic, replan_will_run),
            source: self.catalog.text("assistant-role-error"),
            diagnostic: Some(diagnostic.clone()),
        });
        diagnostic
    }

    fn assistant_replan_context(
        &self,
        message: &str,
        diagnostic: &AssistantRejectionDiagnostic,
    ) -> serde_json::Value {
        let mut context = self.assistant_context_for(message);
        context["assistant_replan"] = serde_json::json!({
            "attempt": 1,
            "max_attempts": 1,
            "diagnostic": diagnostic,
        });
        bounded_assistant_provider_context(context)
    }

    fn start_assistant_request(
        &mut self,
        context: &egui::Context,
        message: String,
        document_context: serde_json::Value,
        source: String,
        replan_attempted: bool,
    ) -> Result<(), String> {
        let handshake = self.assistant_handshake();
        handshake.validate().map_err(|error| error.to_string())?;
        let request_document_id = self.document.current().document_id();
        let request_revision_id = self.document.current().revision_id();
        let request_canonical_digest = self.document.current().canonical_digest();
        self.assistant_request_sequence = self.assistant_request_sequence.saturating_add(1);
        let request_id = format!("chat-{}", self.assistant_request_sequence);
        let task_request_id = request_id.clone();
        let task_message = message.clone();
        let transport = Arc::clone(&self.assistant_transport);
        let repaint = context.clone();
        let cancellation = AssistantCancellation::default();
        let worker_cancellation = cancellation.clone();
        let (sender, receiver) = mpsc::channel();
        std::thread::spawn(move || {
            let result = transport
                .chat_with_diagnostics(
                    handshake,
                    &request_id,
                    &message,
                    &document_context,
                    worker_cancellation,
                )
                .and_then(|response| {
                    response.result.validate()?;
                    if let Some(diagnostics) = response.diagnostics.as_ref() {
                        diagnostics.validate()?;
                    }
                    Ok(response)
                });
            if sender.send(result).is_ok() {
                repaint.request_repaint();
            }
        });
        self.assistant_chat_task = Some(AssistantChatTask {
            receiver,
            request_id: task_request_id,
            message: task_message,
            replan_attempted,
            started_at: Instant::now(),
            cancellation,
            document_id: request_document_id,
            revision_id: request_revision_id,
            canonical_digest: request_canonical_digest,
            selected_occurrence_ids: self
                .selected_occurrence_ids()
                .into_iter()
                .map(|id| id.0)
                .collect(),
            source,
        });
        Ok(())
    }

    fn send_assistant_message(&mut self, context: &egui::Context) {
        if self.assistant_chat_task.is_some() || self.assistant_pending_execution.is_some() {
            return;
        }
        let message = self.assistant_input.trim().to_owned();
        if message.is_empty() {
            return;
        }
        if assistant_query_requests_repair(&message) {
            self.assistant_input.clear();
            let source = self.assistant_source_label();
            self.assistant_messages.push(AssistantChatMessage {
                role: AssistantMessageRole::User,
                text: message.clone(),
                source: source.clone(),
                diagnostic: None,
            });
            let prepared = self.prepare_assistant_validation_repair(&message);
            self.assistant_messages.push(AssistantChatMessage {
                role: if prepared {
                    AssistantMessageRole::Assistant
                } else {
                    AssistantMessageRole::Error
                },
                text: self.catalog.text(if prepared {
                    "assistant-repair-preview-message"
                } else {
                    "assistant-repair-unavailable"
                }),
                source,
                diagnostic: None,
            });
            self.store_assistant_conversation();
            return;
        }
        self.assistant_input.clear();
        let document_context =
            bounded_assistant_provider_context(self.assistant_context_for(&message));
        let source = self.assistant_source_label();
        self.assistant_messages.push(AssistantChatMessage {
            role: AssistantMessageRole::User,
            text: message.clone(),
            source: source.clone(),
            diagnostic: None,
        });
        if let Err(error) =
            self.start_assistant_request(context, message, document_context, source.clone(), false)
        {
            self.assistant_messages.push(AssistantChatMessage {
                role: AssistantMessageRole::Error,
                text: error,
                source,
                diagnostic: None,
            });
            self.store_assistant_conversation();
        }
    }

    fn derive_assistant_model_proposal(
        &self,
        intent: &AssistantModelIntent,
    ) -> AssistantPlanningResult<Proposal> {
        let document_target = format!("document:{}", self.document.current().document_id().0);
        intent.validate().map_err(|error| {
            assistant_rejection(
                AssistantRejectionPhase::IntentValidation,
                "intent.model_invalid",
                "model_intent",
                &document_target,
                error,
                "Return a bounded model intent that satisfies the Assistant schema invariants.",
                true,
            )
        })?;
        #[cfg(not(feature = "named-product-fixtures"))]
        if !intent.bottles.is_empty() {
            return Err(assistant_planning_rejection(
                "planning.named_product_fixture_disabled",
                "model_intent",
                &document_target,
                "Named Bottle model intents are disabled in the default runtime.",
                "Use the generic CAD edit program with supported profile, revolve, shell, and edge-finish operations.",
            ));
        }
        if intent
            .bottles
            .iter()
            .any(|bottle| bottle.teapot.is_some() || bottle.ketchup_bottle.is_some())
            || !intent.balloon_texts.is_empty()
        {
            return Err(assistant_planning_rejection(
                "planning.editable_macro_required",
                "model_intent",
                &document_target,
                "The model intent would create a non-editable mesh instead of a bounded sketch, feature, and transform program.",
                "Use the generic create_part or CAD edit contract with supported universal sketch, feature, and transform operations.",
            ));
        }
        for translation in &intent.translations {
            let occurrence_id = OccurrenceId(translation.occurrence_id);
            if self.document.current().occurrence(occurrence_id).is_none() {
                return Err(assistant_canonical_rejection(
                    CanonicalError::OccurrenceNotFound(occurrence_id),
                    "translate_occurrence",
                    &format!("occurrence:{}", occurrence_id.0),
                ));
            }
        }
        if let [edit] = intent.parameter_edits.as_slice() {
            let target = match edit.constraint_id {
                Some(constraint_id) => ketchup_core::feature_history::ExactParameterEditTarget::SketchConstraintDimension {
                    sketch_id: FeatureId(edit.feature_id),
                    constraint_id: ketchup_core::sketch::SketchConstraintId(constraint_id),
                },
                None => ketchup_core::feature_history::ExactParameterEditTarget::FeatureDimension(
                    FeatureId(edit.feature_id),
                ),
            };
            let edit_target = format!("feature:{}", edit.feature_id);
            let (definition_id, body_id, selected_target, _, _) =
                self.assistant_parameter_edit_target().ok_or_else(|| {
                    assistant_planning_rejection(
                        "planning.parameter_target_unavailable",
                        "edit_parameter",
                        &edit_target,
                        "The requested parameter is not the active exact selection.",
                        "Select the exact editable feature or sketch constraint and retry.",
                    )
                })?;
            if definition_id.0 != edit.definition_id
                || body_id.0 != edit.body_id
                || selected_target != target
            {
                return Err(assistant_planning_rejection(
                    "planning.parameter_target_mismatch",
                    "edit_parameter",
                    &edit_target,
                    "The requested parameter does not match the active exact selection.",
                    "Refresh the selection context and retry against the selected parameter.",
                ));
            }
            let dimension =
                Dimension::new(edit.value_mm.to_string(), edit.value_mm).map_err(|error| {
                    assistant_canonical_rejection(error, "edit_parameter", &edit_target)
                })?;
            return ketchup_core::feature_history::prepare_body_parameter_edit(
                &self.document,
                ketchup_core::feature_history::BodyParameterEditRequest {
                    definition_id,
                    body_id,
                    edits: vec![ketchup_core::feature_history::ExactParameterEdit {
                        target,
                        dimension,
                    }],
                },
                ProposalPrincipal::LocalAssistant,
            )
            .map(|preview| preview.proposal)
            .map_err(|error| {
                assistant_feature_edit_rejection(error, "edit_parameter", &edit_target)
            });
        }
        if let [translation] = intent.profile_translations.as_slice() {
            let profile_target = format!("feature:{}", translation.profile_id);
            return ketchup_core::feature_history::prepare_body_profile_translation(
                &self.document,
                ketchup_core::feature_history::BodyProfileTranslationRequest {
                    definition_id: DefinitionId(translation.definition_id),
                    body_id: BodyId(translation.body_id),
                    profile_id: FeatureId(translation.profile_id),
                    delta_mm: translation.delta_mm,
                },
                ProposalPrincipal::LocalAssistant,
            )
            .map(|preview| preview.proposal)
            .map_err(|error| {
                assistant_feature_edit_rejection(error, "translate_profile", &profile_target)
            });
        }
        let batch = self.derive_assistant_model_batch(intent).ok_or_else(|| {
            assistant_planning_rejection(
                "planning.model_intent_unplannable",
                "model_intent",
                &document_target,
                "The validated model intent could not be converted into a canonical command batch.",
                "Refresh document context and request only targets and geometry that still exist.",
            )
        })?;
        self.document
            .prepare_proposal_with_context(batch, ProposalContext::local_assistant_model())
            .map_err(|error| {
                assistant_proposal_prepare_rejection(error, "model_intent", &document_target)
            })
    }

    fn resolve_assistant_cad_selector(
        &self,
        snapshot: &Snapshot,
        selector: &AssistantCadEntitySelector,
        operation: &str,
    ) -> AssistantPlanningResult<Vec<OccurrenceId>> {
        let ids = match selector {
            AssistantCadEntitySelector::CurrentSelection {} => self
                .selected_occurrence_ids()
                .into_iter()
                .collect::<Vec<_>>(),
            AssistantCadEntitySelector::Occurrences { occurrence_ids } => occurrence_ids
                .iter()
                .copied()
                .map(OccurrenceId)
                .collect::<Vec<_>>(),
        };
        selector
            .validate_resolved_target_count(ids.len())
            .map_err(|error| {
                assistant_planning_rejection(
                    "planning.cad_selector_invalid",
                    operation,
                    "occurrence_selection",
                    error,
                    "Select between one and 100 root occurrences that still exist, then retry.",
                )
            })?;
        if let Some(id) = ids.iter().find(|id| snapshot.occurrence(**id).is_none()) {
            return Err(assistant_canonical_rejection(
                CanonicalError::OccurrenceNotFound(*id),
                operation,
                &format!("occurrence:{}", id.0),
            ));
        }
        Ok(ids)
    }

    pub fn plan_assistant_cad_edit_program(
        &self,
        program: &AssistantCadEditProgram,
    ) -> Result<CommandBatch, Box<AssistantRejectionDiagnostic>> {
        let snapshot = self.document.current();
        let document_target = format!("document:{}", snapshot.document_id().0);
        program.validate().map_err(|error| {
            assistant_rejection(
                AssistantRejectionPhase::IntentValidation,
                "intent.cad_edit_program_invalid",
                "cad_edit_program",
                &document_target,
                error,
                "Return a bounded CAD edit program that satisfies the Assistant schema invariants.",
                true,
            )
        })?;

        let mut commands = Vec::new();
        let mut appended_exact_features = Vec::new();
        let mut working_transforms = snapshot
            .occurrences()
            .map(|occurrence| (occurrence.id(), occurrence.transform()))
            .collect::<BTreeMap<_, _>>();
        let mut collection_members = snapshot
            .collections()
            .map(|collection| {
                (
                    collection.id(),
                    collection.occurrence_ids().collect::<Vec<_>>(),
                )
            })
            .collect::<BTreeMap<_, _>>();
        let mut mate_endpoints = snapshot
            .assembly_mates()
            .map(|mate| {
                (
                    mate.id(),
                    (
                        mate.endpoint_a().occurrence_id(),
                        mate.endpoint_b().occurrence_id(),
                    ),
                )
            })
            .collect::<BTreeMap<_, _>>();
        let mut next_definition = snapshot
            .definitions()
            .map(|definition| definition.id().0)
            .max()
            .unwrap_or(0)
            .checked_add(1);
        let mut next_occurrence = snapshot
            .occurrences()
            .map(|occurrence| occurrence.id().0)
            .max()
            .unwrap_or(0)
            .checked_add(1);
        let mut next_feature = snapshot
            .features()
            .map(|feature| feature.id().0)
            .max()
            .unwrap_or(0)
            .checked_add(1);

        for operation in &program.operations {
            let operation_name = match operation {
                AssistantCadEditOperation::CreateSketch { .. } => "create_sketch",
                AssistantCadEditOperation::CreatePart { .. } => "create_part",
                AssistantCadEditOperation::AppendFeature { .. } => "append_feature",
                AssistantCadEditOperation::SetDimension { .. } => "set_dimension",
                AssistantCadEditOperation::Delete { .. } => "delete_occurrence",
                AssistantCadEditOperation::Transform { .. } => "transform_occurrence",
                AssistantCadEditOperation::Copy { .. } => "copy_occurrence",
                AssistantCadEditOperation::LinearPattern { .. } => "linear_pattern_occurrence",
                AssistantCadEditOperation::Mirror { .. } => "mirror_occurrence",
            };
            let selector = match operation {
                AssistantCadEditOperation::CreateSketch { .. }
                | AssistantCadEditOperation::CreatePart { .. }
                | AssistantCadEditOperation::AppendFeature { .. }
                | AssistantCadEditOperation::SetDimension { .. } => None,
                AssistantCadEditOperation::Delete { selector, .. }
                | AssistantCadEditOperation::Transform { selector, .. }
                | AssistantCadEditOperation::Copy { selector, .. }
                | AssistantCadEditOperation::LinearPattern { selector, .. }
                | AssistantCadEditOperation::Mirror { selector, .. } => Some(selector),
            };
            let targets = selector.map_or_else(
                || Ok(Vec::new()),
                |selector| self.resolve_assistant_cad_selector(&snapshot, selector, operation_name),
            )?;
            if let Some(id) = targets
                .iter()
                .find(|id| !working_transforms.contains_key(id))
            {
                return Err(assistant_planning_rejection(
                    "planning.cad_target_deleted",
                    operation_name,
                    &format!("occurrence:{}", id.0),
                    "An earlier operation in this CAD edit program already deleted the target.",
                    "Remove the later operation or target an occurrence that remains in the program.",
                ));
            }

            match operation {
                AssistantCadEditOperation::CreateSketch {
                    definition_id,
                    name,
                    workplane,
                    entities,
                    constraints,
                } => {
                    let definition_id = DefinitionId(*definition_id);
                    if snapshot.definition(definition_id).is_none() {
                        return Err(assistant_canonical_rejection(
                            CanonicalError::DefinitionNotFound(definition_id),
                            operation_name,
                            &format!("definition:{}", definition_id.0),
                        ));
                    }
                    let workplane_id = next_feature.map(FeatureId).ok_or_else(|| {
                        assistant_canonical_rejection(
                            CanonicalError::IdExhausted,
                            operation_name,
                            &document_target,
                        )
                    })?;
                    let sketch_id =
                        workplane_id
                            .0
                            .checked_add(1)
                            .map(FeatureId)
                            .ok_or_else(|| {
                                assistant_canonical_rejection(
                                    CanonicalError::IdExhausted,
                                    operation_name,
                                    &document_target,
                                )
                            })?;
                    next_feature = sketch_id.0.checked_add(1);
                    let workplane = match workplane {
                        AssistantWorkplaneSpec::Principal { plane } => {
                            WorkplaneSpec::principal(assistant_principal_plane(*plane))
                        }
                        AssistantWorkplaneSpec::Offset {
                            base_feature_id,
                            distance_mm,
                        } => {
                            let base = FeatureId(*base_feature_id);
                            let base_frame = snapshot
                                .feature(base)
                                .and_then(|feature| match feature.kind() {
                                    FeatureKind::Workplane(spec) => Some(spec.frame),
                                    _ => None,
                                })
                                .ok_or_else(|| {
                                    assistant_planning_rejection(
                                        "planning.workplane_base_unavailable",
                                        operation_name,
                                        &format!("feature:{}", base.0),
                                        "The requested offset base is not an existing workplane.",
                                        "Refresh document context and target an existing workplane.",
                                    )
                                })?;
                            let distance = Dimension::new(distance_mm.to_string(), *distance_mm)
                                .map_err(|error| {
                                    assistant_canonical_rejection(
                                        error,
                                        operation_name,
                                        &format!("feature:{}", base.0),
                                    )
                                })?;
                            WorkplaneSpec {
                                support: WorkplaneSupport::Offset { base, distance },
                                frame: base_frame.offset(*distance_mm),
                            }
                        }
                    };
                    let constraints = constraints
                        .iter()
                        .map(assistant_sketch_constraint)
                        .collect::<Result<Vec<_>, _>>()
                        .map_err(|error| {
                            assistant_canonical_rejection(
                                error,
                                operation_name,
                                &format!("feature:{}", sketch_id.0),
                            )
                        })?;
                    commands.extend([
                        CanonicalCommand::CreateFeature {
                            id: workplane_id,
                            definition_id,
                            name: format!("{name} workplane"),
                            kind: FeatureKind::Workplane(workplane),
                        },
                        CanonicalCommand::CreateFeature {
                            id: sketch_id,
                            definition_id,
                            name: name.clone(),
                            kind: FeatureKind::Sketch(SketchSpec {
                                workplane: workplane_id,
                                entities: entities.iter().map(assistant_sketch_entity).collect(),
                                constraints,
                            }),
                        },
                    ]);
                }
                AssistantCadEditOperation::CreatePart {
                    name,
                    workplane,
                    entities,
                    constraints,
                    feature,
                    translation_mm,
                    rotation,
                } => {
                    let definition_id = next_definition.map(DefinitionId).ok_or_else(|| {
                        assistant_canonical_rejection(
                            CanonicalError::IdExhausted,
                            operation_name,
                            &document_target,
                        )
                    })?;
                    next_definition = definition_id.0.checked_add(1);
                    let workplane_id = next_feature.map(FeatureId).ok_or_else(|| {
                        assistant_canonical_rejection(
                            CanonicalError::IdExhausted,
                            operation_name,
                            &document_target,
                        )
                    })?;
                    let sketch_id =
                        workplane_id
                            .0
                            .checked_add(1)
                            .map(FeatureId)
                            .ok_or_else(|| {
                                assistant_canonical_rejection(
                                    CanonicalError::IdExhausted,
                                    operation_name,
                                    &document_target,
                                )
                            })?;
                    let body_id = sketch_id.0.checked_add(1).map(FeatureId).ok_or_else(|| {
                        assistant_canonical_rejection(
                            CanonicalError::IdExhausted,
                            operation_name,
                            &document_target,
                        )
                    })?;
                    next_feature = body_id.0.checked_add(1);
                    let occurrence_id = next_occurrence.map(OccurrenceId).ok_or_else(|| {
                        assistant_canonical_rejection(
                            CanonicalError::IdExhausted,
                            operation_name,
                            &document_target,
                        )
                    })?;
                    next_occurrence = occurrence_id.0.checked_add(1);
                    let workplane = match workplane {
                        AssistantWorkplaneSpec::Principal { plane } => {
                            WorkplaneSpec::principal(assistant_principal_plane(*plane))
                        }
                        AssistantWorkplaneSpec::Offset {
                            base_feature_id,
                            distance_mm,
                        } => {
                            let base = FeatureId(*base_feature_id);
                            let base_frame = snapshot
                                .feature(base)
                                .and_then(|feature| match feature.kind() {
                                    FeatureKind::Workplane(spec) => Some(spec.frame),
                                    _ => None,
                                })
                                .ok_or_else(|| {
                                    assistant_planning_rejection(
                                        "planning.workplane_base_unavailable",
                                        operation_name,
                                        &format!("feature:{}", base.0),
                                        "The requested offset base is not an existing workplane.",
                                        "Refresh document context and target an existing workplane.",
                                    )
                                })?;
                            let distance = Dimension::new(distance_mm.to_string(), *distance_mm)
                                .map_err(|error| {
                                    assistant_canonical_rejection(
                                        error,
                                        operation_name,
                                        &format!("feature:{}", base.0),
                                    )
                                })?;
                            WorkplaneSpec {
                                support: WorkplaneSupport::Offset { base, distance },
                                frame: base_frame.offset(*distance_mm),
                            }
                        }
                    };
                    let constraints = constraints
                        .iter()
                        .map(assistant_sketch_constraint)
                        .collect::<Result<Vec<_>, _>>()
                        .map_err(|error| {
                            assistant_canonical_rejection(
                                error,
                                operation_name,
                                &format!("feature:{}", sketch_id.0),
                            )
                        })?;
                    let sketch = SketchSpec {
                        workplane: workplane_id,
                        entities: entities.iter().map(assistant_sketch_entity).collect(),
                        constraints,
                    };
                    let regions = sketch.solved_regions().map_err(|error| {
                        assistant_canonical_rejection(
                            CanonicalError::Sketch(error),
                            operation_name,
                            &format!("feature:{}", sketch_id.0),
                        )
                    })?;
                    let [region] = regions.as_slice() else {
                        return Err(assistant_planning_rejection(
                            "planning.cad_part_region_ambiguous",
                            operation_name,
                            &format!("feature:{}", sketch_id.0),
                            "The part sketch must resolve to exactly one closed region.",
                            "Return one closed, fully constrained sketch region for this part.",
                        ));
                    };
                    let body_kind = match feature {
                        AssistantCadPartFeature::Extrusion { distance_mm } => {
                            let height = Dimension::new(distance_mm.to_string(), *distance_mm)
                                .map_err(|error| {
                                    assistant_canonical_rejection(
                                        error,
                                        operation_name,
                                        &format!("feature:{}", body_id.0),
                                    )
                                })?;
                            FeatureKind::Pad(PadSpec {
                                sketch: sketch_id,
                                region: region.id,
                                direction: FeatureDirection::AlongNormal,
                                extent: FeatureExtent::Blind(height),
                            })
                        }
                        AssistantCadPartFeature::Revolve {
                            axis_start_mm,
                            axis_end_mm,
                            angle_degrees,
                        } => FeatureKind::Revolve {
                            profile: sketch_id,
                            axis_start_mm: *axis_start_mm,
                            axis_end_mm: *axis_end_mm,
                            angle_degrees: *angle_degrees,
                        },
                    };
                    let translated = translated_transform(
                        Transform::identity(),
                        Vec3::new(translation_mm[0], translation_mm[1], translation_mm[2]),
                    )
                    .map_err(|()| {
                        assistant_planning_rejection(
                            "planning.cad_part_placement_invalid",
                            operation_name,
                            &format!("occurrence:{}", occurrence_id.0),
                            "The requested part translation could not be represented.",
                            "Use a finite bounded translation.",
                        )
                    })?;
                    let transform = if let Some(rotation) = rotation {
                        let world_rotation = world_axis_rotation_transform(
                            Vec3::new(
                                rotation.pivot_mm[0],
                                rotation.pivot_mm[1],
                                rotation.pivot_mm[2],
                            ),
                            Vec3::new(rotation.axis[0], rotation.axis[1], rotation.axis[2]),
                            rotation.angle_degrees,
                        )
                        .map_err(|()| {
                            assistant_planning_rejection(
                                "planning.cad_part_placement_invalid",
                                operation_name,
                                &format!("occurrence:{}", occurrence_id.0),
                                "The requested part rotation could not be represented.",
                                "Use a finite pivot and non-zero finite rotation axis.",
                            )
                        })?;
                        rotation_in_parent_space(
                            world_rotation,
                            Transform::identity(),
                            translated,
                        )
                        .ok_or_else(|| {
                            assistant_planning_rejection(
                                "planning.cad_part_placement_invalid",
                                operation_name,
                                &format!("occurrence:{}", occurrence_id.0),
                                "The requested part placement is not a representable rigid transform.",
                                "Use a finite rigid translation and rotation.",
                            )
                        })?
                    } else {
                        translated
                    };
                    commands.extend([
                        CanonicalCommand::CreateDefinition {
                            id: definition_id,
                            name: name.clone(),
                        },
                        CanonicalCommand::CreateFeature {
                            id: workplane_id,
                            definition_id,
                            name: format!("{name} workplane"),
                            kind: FeatureKind::Workplane(workplane),
                        },
                        CanonicalCommand::CreateFeature {
                            id: sketch_id,
                            definition_id,
                            name: format!("{name} sketch"),
                            kind: FeatureKind::Sketch(sketch),
                        },
                        CanonicalCommand::CreateFeature {
                            id: body_id,
                            definition_id,
                            name: format!("{name} feature"),
                            kind: body_kind,
                        },
                        CanonicalCommand::CreateOccurrence {
                            id: occurrence_id,
                            definition_id,
                            name: name.clone(),
                            transform,
                            parent: None,
                            tag: None,
                            visible: true,
                        },
                    ]);
                }
                AssistantCadEditOperation::AppendFeature {
                    definition_id,
                    name,
                    feature,
                } => {
                    let definition_id = DefinitionId(*definition_id);
                    if snapshot.definition(definition_id).is_none() {
                        return Err(assistant_canonical_rejection(
                            CanonicalError::DefinitionNotFound(definition_id),
                            operation_name,
                            &format!("definition:{}", definition_id.0),
                        ));
                    }
                    let kind = match feature {
                        AssistantCadBodyFeature::Boolean {
                            operation,
                            target_feature_id,
                            tool_feature_id,
                        } => {
                            let target = FeatureId(*target_feature_id);
                            let tool = FeatureId(*tool_feature_id);
                            let mut input_bounds = [None, None];
                            for (index, input) in [target, tool].into_iter().enumerate() {
                                let existing = snapshot.feature(input).ok_or_else(|| {
                                    assistant_canonical_rejection(
                                        CanonicalError::FeatureNotFound(input),
                                        operation_name,
                                        &format!("feature:{}", input.0),
                                    )
                                })?;
                                if existing.definition_id() != definition_id {
                                    return Err(assistant_planning_rejection(
                                        "planning.cad_feature_input_ownership_invalid",
                                        operation_name,
                                        &format!("feature:{}", input.0),
                                        "The requested body feature belongs to a different definition.",
                                        "Target two supported exact body features in the requested definition.",
                                    ));
                                }
                                let graph = ExactBRepGraph::from_snapshot(
                                    &snapshot,
                                    definition_id,
                                    input,
                                )
                                .map_err(|error| {
                                    assistant_planning_rejection(
                                        "planning.cad_feature_input_unsupported",
                                        operation_name,
                                        &format!("feature:{}", input.0),
                                        error.to_string(),
                                        "Target two supported exact body-producing features in the same definition.",
                                    )
                                })?;
                                input_bounds[index] =
                                    graph.producer_bounds_mm().map_err(|error| {
                                        assistant_planning_rejection(
                                            "planning.cad_feature_input_unsupported",
                                            operation_name,
                                            &format!("feature:{}", input.0),
                                            error.to_string(),
                                            "Target two supported exact body-producing features in the same definition.",
                                        )
                                    })?;
                            }
                            if matches!(operation, AssistantCadBooleanOperation::Intersect)
                                && let [Some(target_bounds), Some(tool_bounds)] = input_bounds
                                && (0..3).any(|axis| {
                                    target_bounds[0][axis].max(tool_bounds[0][axis])
                                        >= target_bounds[1][axis].min(tool_bounds[1][axis])
                                })
                            {
                                return Err(assistant_planning_rejection(
                                    "planning.cad_feature_result_empty",
                                    operation_name,
                                    "feature_inputs",
                                    "The bounded Boolean operands do not have a positive-volume intersection.",
                                    "Choose two overlapping exact body features for Intersect.",
                                ));
                            }
                            FeatureKind::Boolean {
                                operation: match operation {
                                    AssistantCadBooleanOperation::Cut => BooleanOperation::Cut,
                                    AssistantCadBooleanOperation::Union => BooleanOperation::Union,
                                    AssistantCadBooleanOperation::Intersect => {
                                        BooleanOperation::Intersect
                                    }
                                },
                                target,
                                tool,
                            }
                        }
                        AssistantCadBodyFeature::Pocket {
                            target_feature_id,
                            profile_feature_id,
                            depth_mm,
                        } => FeatureKind::Pocket {
                            target: FeatureId(*target_feature_id),
                            profile: FeatureId(*profile_feature_id),
                            depth: Dimension::new(depth_mm.to_string(), *depth_mm).map_err(
                                |error| {
                                    assistant_canonical_rejection(
                                        error,
                                        operation_name,
                                        "feature.depth_mm",
                                    )
                                },
                            )?,
                        },
                        AssistantCadBodyFeature::Sweep {
                            profile_feature_id,
                            path_feature_id,
                        } => {
                            let profile = FeatureId(*profile_feature_id);
                            let path = FeatureId(*path_feature_id);
                            let profile_source = snapshot.feature(profile).ok_or_else(|| {
                                assistant_canonical_rejection(
                                    CanonicalError::FeatureNotFound(profile),
                                    operation_name,
                                    &format!("feature:{}", profile.0),
                                )
                            })?;
                            let path_source = snapshot.feature(path).ok_or_else(|| {
                                assistant_canonical_rejection(
                                    CanonicalError::FeatureNotFound(path),
                                    operation_name,
                                    &format!("feature:{}", path.0),
                                )
                            })?;
                            if profile_source.definition_id() != definition_id
                                || path_source.definition_id() != definition_id
                            {
                                return Err(assistant_planning_rejection(
                                    "planning.cad_feature_input_ownership_invalid",
                                    operation_name,
                                    "feature_inputs",
                                    "The requested Sweep inputs belong to a different definition.",
                                    "Target a supported profile and path in the requested definition.",
                                ));
                            }
                            let valid_profile = matches!(
                                profile_source.kind(),
                                FeatureKind::Profile { points_mm } if points_mm.len() >= 3
                            ) || matches!(
                                profile_source.kind(),
                                FeatureKind::SegmentProfile {
                                    segments,
                                    closed: true,
                                } if line_arc_profile_bounds(segments, true).is_some()
                            );
                            let valid_path = matches!(
                                path_source.kind(),
                                FeatureKind::SegmentProfile {
                                    segments,
                                    closed: false,
                                } if matches!(
                                    segments.as_slice(),
                                    [ProfileSegment::Line { start_mm, end_mm }]
                                        if (0.01..=100_000.0).contains(
                                            &(end_mm[0] - start_mm[0])
                                                .hypot(end_mm[1] - start_mm[1])
                                        )
                                )
                            );
                            if !valid_profile || !valid_path {
                                return Err(assistant_planning_rejection(
                                    "planning.cad_feature_input_unsupported",
                                    operation_name,
                                    "feature_inputs",
                                    "The requested Sweep profile or path is not supported by exact evaluation.",
                                    "Use a closed polygon or line/arc profile and one open straight path in the same definition.",
                                ));
                            }
                            FeatureKind::Sweep { profile, path }
                        }
                        AssistantCadBodyFeature::Loft { sections } => {
                            let mut loft_sections = Vec::with_capacity(sections.len());
                            for section in sections {
                                let profile = FeatureId(section.profile_feature_id);
                                let source = snapshot.feature(profile).ok_or_else(|| {
                                    assistant_canonical_rejection(
                                        CanonicalError::FeatureNotFound(profile),
                                        operation_name,
                                        &format!("feature:{}", profile.0),
                                    )
                                })?;
                                if source.definition_id() != definition_id {
                                    return Err(assistant_planning_rejection(
                                        "planning.cad_feature_input_ownership_invalid",
                                        operation_name,
                                        &format!("feature:{}", profile.0),
                                        "The requested Loft profile belongs to a different definition.",
                                        "Target supported spline profiles in the requested definition.",
                                    ));
                                }
                                if snapshot.feature_is_suppressed(profile)
                                    || !matches!(
                                        source.kind(),
                                        FeatureKind::SplineProfile { control_points_mm }
                                            if (4..=64).contains(&control_points_mm.len())
                                    )
                                {
                                    return Err(assistant_planning_rejection(
                                        "planning.cad_feature_input_unsupported",
                                        operation_name,
                                        &format!("feature:{}", profile.0),
                                        "The requested Loft profile is not supported by exact evaluation.",
                                        "Use an unsuppressed spline profile with 4 to 64 control points.",
                                    ));
                                }
                                loft_sections.push(LoftSection {
                                    profile,
                                    elevation_mm: section.elevation_mm,
                                });
                            }
                            FeatureKind::Loft {
                                sections: loft_sections,
                            }
                        }
                        AssistantCadBodyFeature::TopologyShell {
                            target_feature_id,
                            removed_face_reference_ids,
                            thickness_mm,
                        } => {
                            let target = FeatureId(*target_feature_id);
                            let source = snapshot.feature(target).ok_or_else(|| {
                                assistant_canonical_rejection(
                                    CanonicalError::FeatureNotFound(target),
                                    operation_name,
                                    &format!("feature:{}", target.0),
                                )
                            })?;
                            if source.definition_id() != definition_id {
                                return Err(assistant_planning_rejection(
                                    "planning.cad_feature_input_ownership_invalid",
                                    operation_name,
                                    &format!("feature:{}", target.0),
                                    "The requested Shell target belongs to a different definition.",
                                    "Target a supported exact body feature in the requested definition.",
                                ));
                            }
                            if snapshot.feature_is_suppressed(target)
                                || ExactBRepGraph::from_snapshot(&snapshot, definition_id, target)
                                    .is_err()
                            {
                                return Err(assistant_planning_rejection(
                                    "planning.cad_feature_input_unsupported",
                                    operation_name,
                                    &format!("feature:{}", target.0),
                                    "The requested Shell target is not supported by exact evaluation.",
                                    "Target an unsuppressed supported exact body feature with current host-issued face references.",
                                ));
                            }
                            let available_faces = assistant_topology_face_references(
                                &snapshot,
                                &self.topology_results,
                            );
                            let mut removed_faces =
                                Vec::with_capacity(removed_face_reference_ids.len());
                            for reference_id in removed_face_reference_ids {
                                let matches = available_faces
                                    .iter()
                                    .copied()
                                    .filter(|reference| {
                                        reference.definition_id == definition_id
                                            && reference.producer_feature_id == target
                                            && reference.lineage_digest == *reference_id
                                    })
                                    .collect::<Vec<_>>();
                                let [reference] = matches.as_slice() else {
                                    return Err(assistant_planning_rejection(
                                        "planning.cad_topology_reference_unavailable",
                                        operation_name,
                                        &format!("feature:{}", target.0),
                                        "A requested Shell face reference is not a unique current host-issued reference for the target.",
                                        "Refresh the document context and use only listed topology_face_references for this target.",
                                    ));
                                };
                                removed_faces.push((*reference).clone());
                            }
                            removed_faces.sort_unstable();
                            FeatureKind::TopologyShell {
                                target,
                                removed_faces,
                                thickness: Dimension::new(thickness_mm.to_string(), *thickness_mm)
                                    .map_err(|error| {
                                        assistant_canonical_rejection(
                                            error,
                                            operation_name,
                                            "feature.thickness_mm",
                                        )
                                    })?,
                            }
                        }
                    };
                    let id = next_feature.map(FeatureId).ok_or_else(|| {
                        assistant_canonical_rejection(
                            CanonicalError::IdExhausted,
                            operation_name,
                            &document_target,
                        )
                    })?;
                    next_feature = id.0.checked_add(1);
                    commands.push(CanonicalCommand::CreateFeature {
                        id,
                        definition_id,
                        name: name.clone(),
                        kind,
                    });
                    appended_exact_features.push((definition_id, id));
                }
                AssistantCadEditOperation::SetDimension {
                    feature_id,
                    constraint_id,
                    value_mm,
                } => {
                    let feature_id = FeatureId(*feature_id);
                    let dimension =
                        Dimension::new(value_mm.to_string(), *value_mm).map_err(|error| {
                            assistant_canonical_rejection(
                                error,
                                operation_name,
                                &format!("feature:{}", feature_id.0),
                            )
                        })?;
                    commands.push(if let Some(constraint_id) = constraint_id {
                        CanonicalCommand::SetSketchConstraintDimension {
                            id: feature_id,
                            constraint_id: SketchConstraintId(*constraint_id),
                            dimension,
                        }
                    } else {
                        CanonicalCommand::SetFeatureDimension {
                            id: feature_id,
                            dimension,
                        }
                    });
                }
                AssistantCadEditOperation::Delete {
                    dependency_policy, ..
                } => {
                    let target_set = targets.iter().copied().collect::<BTreeSet<_>>();
                    let referenced_collections = collection_members
                        .iter()
                        .filter(|(_, members)| members.iter().any(|id| target_set.contains(id)))
                        .map(|(id, _)| *id)
                        .collect::<Vec<_>>();
                    let incident_mates = mate_endpoints
                        .iter()
                        .filter(|(_, (left, right))| {
                            target_set.contains(left) || target_set.contains(right)
                        })
                        .map(|(id, _)| *id)
                        .collect::<Vec<_>>();
                    if *dependency_policy == AssistantCadDeletePolicy::RejectIfReferenced
                        && (!referenced_collections.is_empty() || !incident_mates.is_empty())
                    {
                        let id = targets[0];
                        return Err(assistant_planning_rejection(
                            "planning.cad_delete_referenced",
                            operation_name,
                            &format!("occurrence:{}", id.0),
                            "The occurrence is referenced by a collection or assembly mate.",
                            "Use remove_references only when removing those dependencies is intended.",
                        ));
                    }
                    if *dependency_policy == AssistantCadDeletePolicy::RemoveReferences {
                        for collection_id in referenced_collections {
                            let members = collection_members
                                .get_mut(&collection_id)
                                .expect("referenced collection came from the working map");
                            members.retain(|id| !target_set.contains(id));
                            commands.push(CanonicalCommand::SetCollectionOccurrences {
                                id: collection_id,
                                occurrence_ids: members.clone(),
                            });
                        }
                        for mate_id in incident_mates {
                            mate_endpoints.remove(&mate_id);
                            commands.push(CanonicalCommand::DeleteAssemblyMate { id: mate_id });
                        }
                    }
                    for id in targets {
                        working_transforms.remove(&id);
                        commands.push(CanonicalCommand::DeleteOccurrence { id });
                    }
                }
                AssistantCadEditOperation::Transform {
                    translation_mm,
                    rotation,
                    ..
                } => {
                    let delta = Vec3::new(translation_mm[0], translation_mm[1], translation_mm[2]);
                    let world_rotation = rotation
                        .as_ref()
                        .map(|rotation| {
                            world_axis_rotation_transform(
                                Vec3::new(
                                    rotation.pivot_mm[0],
                                    rotation.pivot_mm[1],
                                    rotation.pivot_mm[2],
                                ),
                                Vec3::new(rotation.axis[0], rotation.axis[1], rotation.axis[2]),
                                rotation.angle_degrees,
                            )
                        })
                        .transpose()
                        .map_err(|()| {
                            assistant_planning_rejection(
                                "planning.cad_transform_invalid",
                                operation_name,
                                "occurrence_selection",
                                "The requested rigid transform could not be represented.",
                                "Use a finite translation and a non-zero finite rotation axis.",
                            )
                        })?;
                    for id in targets {
                        let current = working_transforms[&id];
                        let translated = translated_transform(current, delta).map_err(|()| {
                            assistant_planning_rejection(
                                "planning.cad_transform_invalid",
                                operation_name,
                                &format!("occurrence:{}", id.0),
                                "The requested translation could not be represented.",
                                "Use a finite bounded translation.",
                            )
                        })?;
                        let transform = if let Some(world_rotation) = world_rotation {
                            let occurrence = snapshot
                                .occurrence(id)
                                .expect("resolved CAD selector targets a snapshot occurrence");
                            let parent_transform = occurrence
                                .parent()
                                .map_or(Some(Transform::identity()), |parent| {
                                    snapshot.world_transform_for_group(parent)
                                })
                                .ok_or_else(|| {
                                    assistant_planning_rejection(
                                        "planning.cad_parent_transform_unavailable",
                                        operation_name,
                                        &format!("occurrence:{}", id.0),
                                        "The occurrence parent transform could not be resolved.",
                                        "Refresh the document context and retry the transform.",
                                    )
                                })?;
                            rotation_in_parent_space(
                                world_rotation,
                                parent_transform,
                                translated,
                            )
                            .ok_or_else(|| {
                                assistant_planning_rejection(
                                    "planning.cad_transform_invalid",
                                    operation_name,
                                    &format!("occurrence:{}", id.0),
                                    "The requested world-space rotation could not be represented in the occurrence parent.",
                                    "Use a finite rigid parent and rotation.",
                                )
                            })?
                        } else {
                            translated
                        };
                        working_transforms.insert(id, transform);
                        commands.push(CanonicalCommand::SetOccurrenceTransform { id, transform });
                    }
                }
                AssistantCadEditOperation::Copy { translation_mm, .. } => {
                    let delta = Vec3::new(translation_mm[0], translation_mm[1], translation_mm[2]);
                    for id in targets {
                        let source = snapshot
                            .occurrence(id)
                            .expect("resolved CAD selector targets a snapshot occurrence");
                        let transform = translated_transform(working_transforms[&id], delta)
                            .map_err(|()| {
                                assistant_planning_rejection(
                                    "planning.cad_copy_invalid",
                                    operation_name,
                                    &format!("occurrence:{}", id.0),
                                    "The requested copy transform could not be represented.",
                                    "Use a finite bounded translation.",
                                )
                            })?;
                        let occurrence_id = next_occurrence.map(OccurrenceId).ok_or_else(|| {
                            assistant_canonical_rejection(
                                CanonicalError::IdExhausted,
                                operation_name,
                                &document_target,
                            )
                        })?;
                        next_occurrence = occurrence_id.0.checked_add(1);
                        commands.push(CanonicalCommand::CreateOccurrence {
                            id: occurrence_id,
                            definition_id: source.definition_id(),
                            name: source.name().to_owned(),
                            transform,
                            parent: source.parent(),
                            tag: source.tag(),
                            visible: source.visible(),
                        });
                    }
                }
                AssistantCadEditOperation::LinearPattern {
                    instances, step_mm, ..
                } => {
                    let step = Vec3::new(step_mm[0], step_mm[1], step_mm[2]);
                    for instance in 1..*instances {
                        let delta = step * f64::from(instance);
                        for id in &targets {
                            let source = snapshot
                                .occurrence(*id)
                                .expect("resolved CAD selector targets a snapshot occurrence");
                            let transform = translated_transform(working_transforms[id], delta)
                                .map_err(|()| {
                                    assistant_planning_rejection(
                                        "planning.cad_pattern_invalid",
                                        operation_name,
                                        &format!("occurrence:{}", id.0),
                                        "The requested pattern transform could not be represented.",
                                        "Use a finite bounded pattern step and instance count.",
                                    )
                                })?;
                            let occurrence_id =
                                next_occurrence.map(OccurrenceId).ok_or_else(|| {
                                    assistant_canonical_rejection(
                                        CanonicalError::IdExhausted,
                                        operation_name,
                                        &document_target,
                                    )
                                })?;
                            next_occurrence = occurrence_id.0.checked_add(1);
                            commands.push(CanonicalCommand::CreateOccurrence {
                                id: occurrence_id,
                                definition_id: source.definition_id(),
                                name: source.name().to_owned(),
                                transform,
                                parent: source.parent(),
                                tag: source.tag(),
                                visible: source.visible(),
                            });
                        }
                    }
                }
                AssistantCadEditOperation::Mirror {
                    plane_origin_mm,
                    plane_normal,
                    ..
                } => {
                    let world_mirror = world_plane_mirror_transform(
                        Vec3::new(plane_origin_mm[0], plane_origin_mm[1], plane_origin_mm[2]),
                        Vec3::new(plane_normal[0], plane_normal[1], plane_normal[2]),
                    )
                    .map_err(|()| {
                        assistant_planning_rejection(
                            "planning.cad_mirror_invalid",
                            operation_name,
                            "occurrence_selection",
                            "The requested mirror plane could not be represented.",
                            "Use a finite plane origin and non-zero finite normal.",
                        )
                    })?;
                    for id in targets {
                        let source = snapshot
                            .occurrence(id)
                            .expect("resolved CAD selector targets a snapshot occurrence");
                        let parent_transform = source
                            .parent()
                            .map_or(Some(Transform::identity()), |parent| {
                                snapshot.world_transform_for_group(parent)
                            })
                            .ok_or_else(|| {
                                assistant_planning_rejection(
                                    "planning.cad_parent_transform_unavailable",
                                    operation_name,
                                    &format!("occurrence:{}", id.0),
                                    "The occurrence parent transform could not be resolved.",
                                    "Refresh the document context and retry the mirror.",
                                )
                            })?;
                        let transform = rotation_in_parent_space(
                            world_mirror,
                            parent_transform,
                            working_transforms[&id],
                        )
                        .ok_or_else(|| {
                            assistant_planning_rejection(
                                "planning.cad_mirror_invalid",
                                operation_name,
                                &format!("occurrence:{}", id.0),
                                "The requested mirror could not be represented in the occurrence parent.",
                                "Use a finite invertible parent transform and mirror plane.",
                            )
                        })?;
                        let occurrence_id = next_occurrence.map(OccurrenceId).ok_or_else(|| {
                            assistant_canonical_rejection(
                                CanonicalError::IdExhausted,
                                operation_name,
                                &document_target,
                            )
                        })?;
                        next_occurrence = occurrence_id.0.checked_add(1);
                        commands.push(CanonicalCommand::CreateOccurrence {
                            id: occurrence_id,
                            definition_id: source.definition_id(),
                            name: source.name().to_owned(),
                            transform,
                            parent: source.parent(),
                            tag: source.tag(),
                            visible: source.visible(),
                        });
                    }
                }
            }
        }
        let batch = CommandBatch::new(commands);
        if !appended_exact_features.is_empty() {
            let candidate = self.document.preview_batch(&batch).map_err(|error| {
                assistant_canonical_rejection(error, "append_feature", &document_target)
            })?;
            for (definition_id, feature_id) in appended_exact_features {
                ExactBRepGraph::from_snapshot(&candidate, definition_id, feature_id).map_err(
                    |error| {
                        assistant_planning_rejection(
                            "planning.cad_feature_result_unsupported",
                            "append_feature",
                            &format!("feature:{}", feature_id.0),
                            error.to_string(),
                            "Use operands and an operation that produce a supported exact body.",
                        )
                    },
                )?;
            }
        }
        Ok(batch)
    }

    fn derive_assistant_cad_edit_proposal(
        &self,
        program: &AssistantCadEditProgram,
    ) -> AssistantPlanningResult<Proposal> {
        let target = format!("document:{}", self.document.current().document_id().0);
        let batch = self.plan_assistant_cad_edit_program(program)?;
        self.document
            .prepare_proposal_with_context(batch, ProposalContext::local_assistant_model())
            .map_err(|error| {
                assistant_proposal_prepare_rejection(error, "cad_edit_program", &target)
            })
    }

    fn derive_assistant_model_batch(&self, intent: &AssistantModelIntent) -> Option<CommandBatch> {
        let snapshot = self.document.current();
        let mut commands = Vec::new();
        if intent.replace_scene {
            commands.extend(snapshot.collections().map(|collection| {
                CanonicalCommand::SetCollectionOccurrences {
                    id: collection.id(),
                    occurrence_ids: Vec::new(),
                }
            }));
            commands.extend(
                snapshot
                    .occurrences()
                    .map(|item| CanonicalCommand::DeleteOccurrence { id: item.id() }),
            );
            commands.extend(
                snapshot
                    .definitions()
                    .map(|item| CanonicalCommand::DeleteDefinition { id: item.id() }),
            );
        }
        let mut next_definition = snapshot
            .definitions()
            .map(|item| item.id().0)
            .max()
            .unwrap_or(0)
            .checked_add(1);
        let mut next_feature = snapshot
            .features()
            .map(|item| item.id().0)
            .max()
            .unwrap_or(0)
            .checked_add(1);
        let mut next_occurrence = snapshot
            .occurrences()
            .map(|item| item.id().0)
            .max()
            .unwrap_or(0)
            .checked_add(1);
        for translation in &intent.translations {
            let occurrence = snapshot.occurrence(OccurrenceId(translation.occurrence_id))?;
            let [x, y, z] = translation.delta_mm;
            let transform =
                translated_transform(occurrence.transform(), Vec3::new(x, y, z)).ok()?;
            commands.push(CanonicalCommand::SetOccurrenceTransform {
                id: OccurrenceId(translation.occurrence_id),
                transform,
            });
        }
        for rotation in &intent.rotations {
            let [pivot_x, pivot_y, pivot_z] = rotation.pivot_mm;
            let [axis_x, axis_y, axis_z] = rotation.axis;
            let world_rotation = world_axis_rotation_transform(
                Vec3::new(pivot_x, pivot_y, pivot_z),
                Vec3::new(axis_x, axis_y, axis_z),
                rotation.angle_degrees,
            )
            .ok()?;
            match (rotation.occurrence_id, rotation.group_id) {
                (Some(id), None) => {
                    let occurrence_id = OccurrenceId(id);
                    let occurrence = snapshot.occurrence(occurrence_id)?;
                    let parent_transform = occurrence
                        .parent()
                        .map_or(Some(Transform::identity()), |parent| {
                            snapshot.world_transform_for_group(parent)
                        })?;
                    commands.push(CanonicalCommand::SetOccurrenceTransform {
                        id: occurrence_id,
                        transform: rotation_in_parent_space(
                            world_rotation,
                            parent_transform,
                            occurrence.transform(),
                        )?,
                    });
                }
                (None, Some(id)) => {
                    let group_id = GroupId(id);
                    let group = snapshot.group(group_id)?;
                    let parent_transform = group
                        .parent()
                        .map_or(Some(Transform::identity()), |parent| {
                            snapshot.world_transform_for_group(parent)
                        })?;
                    commands.push(CanonicalCommand::SetGroupTransform {
                        id: group_id,
                        transform: rotation_in_parent_space(
                            world_rotation,
                            parent_transform,
                            group.transform(),
                        )?,
                    });
                }
                _ => return None,
            }
        }
        for array in &intent.linear_arrays {
            let sources = array
                .occurrence_ids
                .iter()
                .map(|id| snapshot.occurrence(OccurrenceId(*id)).cloned())
                .collect::<Option<Vec<_>>>()?;
            for instance in 1..array.instances {
                let [step_x, step_y, step_z] = array.step_mm;
                let delta = Vec3::new(
                    step_x * f64::from(instance),
                    step_y * f64::from(instance),
                    step_z * f64::from(instance),
                );
                for source in &sources {
                    let occurrence = next_occurrence.map(OccurrenceId)?;
                    let transform = translated_transform(source.transform(), delta).ok()?;
                    commands.push(CanonicalCommand::CreateOccurrence {
                        id: occurrence,
                        definition_id: source.definition_id(),
                        name: source.name().to_owned(),
                        transform,
                        parent: source.parent(),
                        tag: source.tag(),
                        visible: source.visible(),
                    });
                    next_occurrence = occurrence.0.checked_add(1);
                }
            }
        }
        #[cfg(feature = "named-product-fixtures")]
        for bottle in &intent.bottles {
            if bottle.teapot.is_some() {
                let body_definition = next_definition.map(DefinitionId)?;
                let lid_definition = body_definition.0.checked_add(1).map(DefinitionId)?;
                let body_feature = next_feature.map(FeatureId)?;
                let lid_feature = body_feature.0.checked_add(1).map(FeatureId)?;
                let body_occurrence = next_occurrence.map(OccurrenceId)?;
                let lid_occurrence = body_occurrence.0.checked_add(1).map(OccurrenceId)?;
                let [x, y, z] = bottle.origin_mm;
                let transform = Transform::from_translation(x, y, z).ok()?;
                commands.extend([
                    CanonicalCommand::CreateDefinition {
                        id: body_definition,
                        name: format!("{} body", bottle.name),
                    },
                    CanonicalCommand::CreateFeature {
                        id: body_feature,
                        definition_id: body_definition,
                        name: format!("{} smooth hollow body", bottle.name),
                        kind: FeatureKind::MeshBody(assistant_teapot_body_mesh(bottle)?),
                    },
                    CanonicalCommand::CreateOccurrence {
                        id: body_occurrence,
                        definition_id: body_definition,
                        name: format!("{} body occurrence", bottle.name),
                        transform,
                        parent: None,
                        tag: None,
                        visible: true,
                    },
                    CanonicalCommand::CreateDefinition {
                        id: lid_definition,
                        name: format!("{} lid", bottle.name),
                    },
                    CanonicalCommand::CreateFeature {
                        id: lid_feature,
                        definition_id: lid_definition,
                        name: format!("{} removable seated lid", bottle.name),
                        kind: FeatureKind::MeshBody(assistant_teapot_lid_mesh(bottle)?),
                    },
                    CanonicalCommand::CreateOccurrence {
                        id: lid_occurrence,
                        definition_id: lid_definition,
                        name: format!("{} lid occurrence", bottle.name),
                        transform,
                        parent: None,
                        tag: None,
                        visible: true,
                    },
                ]);
                next_definition = lid_definition.0.checked_add(1);
                next_feature = lid_feature.0.checked_add(1);
                next_occurrence = lid_occurrence.0.checked_add(1);
                continue;
            }
            if bottle.ketchup_bottle.is_some() {
                let body_definition = next_definition.map(DefinitionId)?;
                let cap_definition = body_definition.0.checked_add(1).map(DefinitionId)?;
                let body_feature = next_feature.map(FeatureId)?;
                let cap_feature = body_feature.0.checked_add(1).map(FeatureId)?;
                let body_occurrence = next_occurrence.map(OccurrenceId)?;
                let cap_occurrence = body_occurrence.0.checked_add(1).map(OccurrenceId)?;
                let [x, y, z] = bottle.origin_mm;
                let transform = Transform::from_translation(x, y, z).ok()?;
                commands.extend([
                    CanonicalCommand::CreateDefinition {
                        id: body_definition,
                        name: format!("{} body", bottle.name),
                    },
                    CanonicalCommand::CreateFeature {
                        id: body_feature,
                        definition_id: body_definition,
                        name: format!("{} clean threaded body", bottle.name),
                        kind: FeatureKind::MeshBody(assistant_ketchup_bottle_body_mesh(bottle)?),
                    },
                    CanonicalCommand::CreateOccurrence {
                        id: body_occurrence,
                        definition_id: body_definition,
                        name: format!("{} body occurrence", bottle.name),
                        transform,
                        parent: None,
                        tag: None,
                        visible: true,
                    },
                    CanonicalCommand::CreateDefinition {
                        id: cap_definition,
                        name: format!("{} cap", bottle.name),
                    },
                    CanonicalCommand::CreateFeature {
                        id: cap_feature,
                        definition_id: cap_definition,
                        name: format!("{} removable threaded cap", bottle.name),
                        kind: FeatureKind::MeshBody(assistant_ketchup_bottle_cap_mesh(bottle)?),
                    },
                    CanonicalCommand::CreateOccurrence {
                        id: cap_occurrence,
                        definition_id: cap_definition,
                        name: format!("{} cap occurrence", bottle.name),
                        transform,
                        parent: None,
                        tag: None,
                        visible: true,
                    },
                ]);
                next_definition = cap_definition.0.checked_add(1);
                next_feature = cap_feature.0.checked_add(1);
                next_occurrence = cap_occurrence.0.checked_add(1);
                continue;
            }
            let definition = next_definition.map(DefinitionId)?;
            let profile = next_feature.map(FeatureId)?;
            let control = profile.0.checked_add(1).map(FeatureId)?;
            let revolve = profile.0.checked_add(2).map(FeatureId)?;
            let shell = profile.0.checked_add(3).map(FeatureId)?;
            let finish = profile.0.checked_add(4).map(FeatureId)?;
            let occurrence = next_occurrence.map(OccurrenceId)?;
            let body_top = bottle.body_height_mm;
            let shoulder_top = body_top + bottle.shoulder_rise_mm;
            let bottle_top = shoulder_top + bottle.neck_height_mm;
            let body_radius =
                Dimension::new(bottle.body_radius_mm.to_string(), bottle.body_radius_mm).ok()?;
            let body_height =
                Dimension::new(bottle.body_height_mm.to_string(), bottle.body_height_mm).ok()?;
            let shoulder_rise =
                Dimension::new(bottle.shoulder_rise_mm.to_string(), bottle.shoulder_rise_mm)
                    .ok()?;
            let thickness = Dimension::new(
                bottle.wall_thickness_mm.to_string(),
                bottle.wall_thickness_mm,
            )
            .ok()?;
            let finish_amount =
                Dimension::new(bottle.finish_amount_mm.to_string(), bottle.finish_amount_mm)
                    .ok()?;
            let finish_kind = match bottle.finish_kind {
                AssistantBottleFinishKind::Fillet => BottleEdgeFinishKind::Fillet,
                AssistantBottleFinishKind::Chamfer => BottleEdgeFinishKind::Chamfer,
            };
            let [x, y, z] = bottle.origin_mm;
            let transform = Transform::from_translation(x, y, z).ok()?;
            commands.extend([
                CanonicalCommand::CreateDefinition {
                    id: definition,
                    name: bottle.name.clone(),
                },
                CanonicalCommand::CreateFeature {
                    id: profile,
                    definition_id: definition,
                    name: format!("{} profile", bottle.name),
                    kind: FeatureKind::Profile {
                        points_mm: vec![
                            [0.0, 0.0],
                            [bottle.body_radius_mm, 0.0],
                            [bottle.body_radius_mm, body_top],
                            [bottle.neck_radius_mm, shoulder_top],
                            [bottle.neck_radius_mm, bottle_top],
                            [0.0, bottle_top],
                        ],
                    },
                },
                CanonicalCommand::CreateFeature {
                    id: control,
                    definition_id: definition,
                    name: format!("{} controls", bottle.name),
                    kind: FeatureKind::BottleProfileControl {
                        profile,
                        body_radius,
                        body_height,
                        shoulder_rise,
                    },
                },
                CanonicalCommand::CreateFeature {
                    id: revolve,
                    definition_id: definition,
                    name: format!("{} revolve", bottle.name),
                    kind: FeatureKind::full_revolve(control),
                },
                CanonicalCommand::CreateFeature {
                    id: shell,
                    definition_id: definition,
                    name: format!("{} shell", bottle.name),
                    kind: FeatureKind::Shell {
                        target: revolve,
                        removed_faces: vec![
                            StableFaceRole::new(BOTTLE_SHELL_OPENING_FACE_ROLE).ok()?,
                        ],
                        thickness,
                    },
                },
                CanonicalCommand::CreateFeature {
                    id: finish,
                    definition_id: definition,
                    name: format!("{} shoulder finish", bottle.name),
                    kind: FeatureKind::BottleEdgeFinish {
                        target: shell,
                        edges: vec![StableEdgeRole::new(BOTTLE_SHOULDER_EDGE_ROLE).ok()?],
                        kind: finish_kind,
                        amount: finish_amount,
                    },
                },
                CanonicalCommand::CreateOccurrence {
                    id: occurrence,
                    definition_id: definition,
                    name: format!("{} occurrence", bottle.name),
                    transform,
                    parent: None,
                    tag: None,
                    visible: true,
                },
            ]);
            next_definition = definition.0.checked_add(1);
            next_feature = finish.0.checked_add(1);
            next_occurrence = occurrence.0.checked_add(1);
        }
        for text in &intent.balloon_texts {
            let definition = next_definition.map(DefinitionId)?;
            let feature = next_feature.map(FeatureId)?;
            let occurrence = next_occurrence.map(OccurrenceId)?;
            let [x, y, z] = text.origin_mm;
            commands.extend([
                CanonicalCommand::CreateDefinition {
                    id: definition,
                    name: text.name.clone(),
                },
                CanonicalCommand::CreateFeature {
                    id: feature,
                    definition_id: definition,
                    name: format!("{} inflated text", text.name),
                    kind: FeatureKind::MeshBody(assistant_balloon_text_mesh(text)?),
                },
                CanonicalCommand::CreateOccurrence {
                    id: occurrence,
                    definition_id: definition,
                    name: format!("{} occurrence", text.name),
                    transform: Transform::from_translation(x, y, z).ok()?,
                    parent: None,
                    tag: None,
                    visible: true,
                },
            ]);
            next_definition = definition.0.checked_add(1);
            next_feature = feature.0.checked_add(1);
            next_occurrence = occurrence.0.checked_add(1);
        }
        for roof in &intent.gable_roofs {
            let definition = next_definition.map(DefinitionId)?;
            let feature = next_feature.map(FeatureId)?;
            let occurrence = next_occurrence.map(OccurrenceId)?;
            commands.extend(assistant_prismatic_macro_commands(
                &roof.name,
                assistant_gable_roof_macro(roof)?,
                definition,
                feature,
                occurrence,
            )?);
            next_definition = definition.0.checked_add(1);
            next_feature = feature.0.checked_add(3);
            next_occurrence = occurrence.0.checked_add(1);
        }
        for stairs in &intent.staircases {
            let definition = next_definition.map(DefinitionId)?;
            let feature = next_feature.map(FeatureId)?;
            let occurrence = next_occurrence.map(OccurrenceId)?;
            commands.extend(assistant_prismatic_macro_commands(
                &stairs.name,
                assistant_staircase_macro(stairs)?,
                definition,
                feature,
                occurrence,
            )?);
            next_definition = definition.0.checked_add(1);
            next_feature = feature.0.checked_add(3);
            next_occurrence = occurrence.0.checked_add(1);
        }
        for beam in &intent.oriented_beams {
            let definition = next_definition.map(DefinitionId)?;
            let feature = next_feature.map(FeatureId)?;
            let occurrence = next_occurrence.map(OccurrenceId)?;
            commands.extend(assistant_prismatic_macro_commands(
                &beam.name,
                assistant_oriented_beam_macro(beam)?,
                definition,
                feature,
                occurrence,
            )?);
            next_definition = definition.0.checked_add(1);
            next_feature = feature.0.checked_add(3);
            next_occurrence = occurrence.0.checked_add(1);
        }
        for item in &intent.boxes {
            let feature_count;
            let definition = next_definition.map(DefinitionId)?;
            let feature = next_feature.map(FeatureId)?;
            let occurrence = next_occurrence.map(OccurrenceId)?;
            let [width, depth, height] = item.size_mm;
            let [x, y, z] = item.origin_mm;
            let transform = Transform::from_translation(x, y, z).ok()?;
            commands.push(CanonicalCommand::CreateDefinition {
                id: definition,
                name: item.name.clone(),
            });
            if item.subtract_boxes.is_empty() {
                feature_count = 2;
                let extrusion = feature.0.checked_add(1).map(FeatureId)?;
                let height_dimension = Dimension::new(height.to_string(), height).ok()?;
                commands.extend([
                    CanonicalCommand::CreateFeature {
                        id: feature,
                        definition_id: definition,
                        name: format!("{} profile", item.name),
                        kind: FeatureKind::Profile {
                            points_mm: vec![[0.0, 0.0], [width, 0.0], [width, depth], [0.0, depth]],
                        },
                    },
                    CanonicalCommand::CreateFeature {
                        id: extrusion,
                        definition_id: definition,
                        name: format!("{} extrusion", item.name),
                        kind: FeatureKind::Extrusion {
                            profile: feature,
                            height: height_dimension,
                        },
                    },
                ]);
            } else {
                let (feature_commands, count) =
                    assistant_subtracted_box_feature_commands(item, definition, feature)?;
                feature_count = count;
                commands.extend(feature_commands);
            }
            commands.push(CanonicalCommand::CreateOccurrence {
                id: occurrence,
                definition_id: definition,
                name: item.name.clone(),
                transform,
                parent: None,
                tag: None,
                visible: true,
            });
            next_definition = definition.0.checked_add(1);
            next_feature = feature.0.checked_add(feature_count);
            next_occurrence = occurrence.0.checked_add(1);
        }
        Some(CommandBatch::new(commands))
    }

    fn assistant_repair_participants(
        &self,
        snapshot: &Snapshot,
    ) -> BTreeMap<OccurrenceId, GeneralBodyParticipant> {
        let exact_results = ExactResultRegistry::carried_forward(snapshot, &self.exact_results);
        snapshot
            .scene_query()
            .into_iter()
            .filter(|occurrence| occurrence.visible)
            .take(MAX_ASSISTANT_VALIDATION_OCCURRENCES)
            .filter_map(|occurrence| {
                let occurrence_id = occurrence.instance_path.root_occurrence();
                GeneralBodyParticipant::accept(
                    snapshot,
                    &exact_results,
                    occurrence.instance_path,
                    TolerancePolicy::default(),
                )
                .ok()
                .map(|participant| (occurrence_id, participant))
            })
            .collect()
    }

    fn assistant_collision_repair_delta(
        participants: &BTreeMap<OccurrenceId, GeneralBodyParticipant>,
        left_id: OccurrenceId,
        right_id: OccurrenceId,
    ) -> Option<[f64; 3]> {
        let tolerance = TolerancePolicy::default();
        let narrow_phase = general_body_narrow_phase(
            participants.get(&left_id)?,
            participants.get(&right_id)?,
            tolerance,
        )
        .ok()?;
        if narrow_phase.relation != GeneralBodyNarrowPhaseRelation::Intersecting {
            return None;
        }
        let distance_mm = -narrow_phase.signed_separation_mm + tolerance.epsilon_mm();
        Some(
            narrow_phase
                .separation_axis_world
                .map(|component| component * distance_mm),
        )
    }

    fn assistant_body_projection_interval(
        body: &GeneralBodyParticipant,
        axis: [f64; 3],
    ) -> Option<[f64; 2]> {
        let geometry = body.geometry_evidence();
        let center = geometry.source_frame_center_world_mm();
        let center_projection = (0..3).map(|index| center[index] * axis[index]).sum::<f64>();
        let extents = geometry.source_frame_extents_mm();
        let mut radius = 0.0;
        for (source_axis, extent) in extents.into_iter().enumerate() {
            let direction = geometry.source_axis_world_direction(source_axis)?;
            let scale = geometry.source_axis_world_scale(source_axis)?;
            let alignment = (0..3)
                .map(|index| direction[index] * axis[index])
                .sum::<f64>()
                .abs();
            radius += extent * scale * alignment * 0.5;
        }
        Some([center_projection - radius, center_projection + radius])
    }

    fn assistant_validation_issue_total(validation: &serde_json::Value) -> Option<u64> {
        Some(
            validation["collision"]["issue_count"].as_u64()?
                + validation["gravity_support"]["unsupported_count"].as_u64()?,
        )
    }

    fn assistant_repair_issue_remains(
        validation: &serde_json::Value,
        operation: &AssistantRepairOperation,
    ) -> bool {
        let issues = validation[operation.validator()]["issues"]
            .as_array()
            .map(Vec::as_slice)
            .unwrap_or_default();
        match operation {
            AssistantRepairOperation::ResolveCollision {
                left_occurrence_id,
                moved_occurrence_id,
                ..
            } => issues.iter().any(|issue| {
                let found_left = issue["left_occurrence_id"].as_u64();
                let found_right = issue["right_occurrence_id"].as_u64();
                (found_left == Some(*left_occurrence_id)
                    && found_right == Some(*moved_occurrence_id))
                    || (found_left == Some(*moved_occurrence_id)
                        && found_right == Some(*left_occurrence_id))
            }),
            AssistantRepairOperation::RestoreGravitySupport { occurrence_id, .. } => issues
                .iter()
                .any(|issue| issue["occurrence_id"].as_u64() == Some(*occurrence_id)),
        }
    }

    fn assistant_validation_repair_operations(
        &self,
        snapshot: &Snapshot,
        validation: &serde_json::Value,
    ) -> Vec<AssistantRepairOperation> {
        let participants = self.assistant_repair_participants(snapshot);
        let mut operations = Vec::new();
        for issue in validation["collision"]["issues"]
            .as_array()
            .map(Vec::as_slice)
            .unwrap_or_default()
        {
            let (Some(left_id), Some(right_id)) = (
                issue["left_occurrence_id"].as_u64(),
                issue["right_occurrence_id"].as_u64(),
            ) else {
                continue;
            };
            let (left_id, right_id) = (OccurrenceId(left_id), OccurrenceId(right_id));
            if let Some(delta_mm) =
                Self::assistant_collision_repair_delta(&participants, left_id, right_id)
            {
                operations.push(AssistantRepairOperation::ResolveCollision {
                    left_occurrence_id: left_id.0,
                    moved_occurrence_id: right_id.0,
                    delta_mm,
                });
            }
        }
        let Ok(roles) = ValidatorRoleIndex::from_snapshot(snapshot) else {
            return operations;
        };
        let Ok(gravity) = assistant_gravity_input(snapshot) else {
            return operations;
        };
        let support_direction = gravity.direction.map(|component| -component);
        for issue in validation["gravity_support"]["issues"]
            .as_array()
            .map(Vec::as_slice)
            .unwrap_or_default()
        {
            let Some(occurrence_id) = issue["occurrence_id"].as_u64().map(OccurrenceId) else {
                continue;
            };
            let Some(candidate) = participants.get(&occurrence_id) else {
                continue;
            };
            let Some(candidate_role) = roles
                .role(occurrence_id)
                .and_then(|role| assistant_physics_role(role.as_str()))
            else {
                continue;
            };
            let Some([candidate_min, _]) =
                Self::assistant_body_projection_interval(candidate, support_direction)
            else {
                continue;
            };
            for (support_occurrence_id, support) in &participants {
                let Some(support_role) = roles
                    .role(*support_occurrence_id)
                    .and_then(|role| assistant_physics_role(role.as_str()))
                else {
                    continue;
                };
                if *support_occurrence_id == occurrence_id
                    || support_role.group != candidate_role.group
                    || (support_role.kind != AssistantPhysicsRoleKind::GravityGround
                        && !snapshot.occurrence_is_grounded(*support_occurrence_id))
                {
                    continue;
                }
                let Some([_, support_max]) =
                    Self::assistant_body_projection_interval(support, support_direction)
                else {
                    continue;
                };
                let distance_mm = support_max - candidate_min;
                let delta_mm = support_direction.map(|component| component * distance_mm);
                let operation = AssistantRepairOperation::RestoreGravitySupport {
                    occurrence_id: occurrence_id.0,
                    support_occurrence_id: support_occurrence_id.0,
                    gravity_direction: gravity.direction,
                    delta_mm,
                };
                if operation.validate() {
                    operations.push(operation);
                }
            }
        }
        operations
    }

    fn derive_assistant_validation_repair_plan(
        &self,
        selection: &AssistantValidationSelection,
    ) -> AssistantPlanningResult<AssistantPreviewPlan> {
        let target = format!("document:{}", self.document.current().document_id().0);
        if !selection.is_valid() {
            return Err(assistant_rejection(
                AssistantRejectionPhase::DomainValidation,
                "validator.selection_invalid",
                "validation_repair",
                &target,
                "The requested validator selection is empty or contains unknown validators.",
                "Choose one or more known validators and retry.",
                true,
            ));
        }
        let snapshot = self.document.current();
        let validation_before =
            self.assistant_validation_context(&snapshot, &self.exact_results, selection);
        if validation_before["complete"].as_bool() != Some(true) {
            return Err(assistant_rejection(
                AssistantRejectionPhase::DomainValidation,
                "validator.evidence_incomplete",
                "validation_repair",
                &target,
                "The requested validator evidence is incomplete for the current snapshot.",
                "Resolve missing exact or validator evidence before requesting a repair.",
                true,
            ));
        }

        let mut candidate = snapshot;
        let mut validation_after = validation_before.clone();
        let mut issue_total = Self::assistant_validation_issue_total(&validation_after)
            .ok_or_else(|| {
                assistant_rejection(
                    AssistantRejectionPhase::DomainValidation,
                    "validator.result_invalid",
                    "validation_repair",
                    &target,
                    "The validator result does not contain a bounded issue count.",
                    "Re-run validation against the current canonical snapshot.",
                    true,
                )
            })?;
        let mut target_transforms = BTreeMap::new();
        let mut accepted_operations = Vec::new();
        let mut final_proposal = None;
        let mut last_rejection = None;
        for _ in 0..MAX_ASSISTANT_VALIDATION_ISSUES {
            let mut accepted = None;
            for operation in
                self.assistant_validation_repair_operations(&candidate, &validation_after)
            {
                if !operation.validate() {
                    continue;
                }
                let moved_occurrence = OccurrenceId(operation.moved_occurrence_id());
                let Some(occurrence) = candidate.occurrence(moved_occurrence) else {
                    continue;
                };
                let [x, y, z] = operation.delta_mm();
                let Ok(transform) =
                    translated_transform(occurrence.transform(), Vec3::new(x, y, z))
                else {
                    continue;
                };
                let mut trial_transforms = target_transforms.clone();
                trial_transforms.insert(moved_occurrence, transform);
                let commands = trial_transforms
                    .iter()
                    .map(|(id, transform)| CanonicalCommand::SetOccurrenceTransform {
                        id: *id,
                        transform: *transform,
                    })
                    .collect();
                let proposal = match self.document.prepare_proposal_with_context(
                    CommandBatch::new(commands),
                    ProposalContext::local_assistant_model(),
                ) {
                    Ok(proposal) => proposal,
                    Err(error) => {
                        last_rejection = Some(assistant_proposal_prepare_rejection(
                            error,
                            "validation_repair",
                            &target,
                        ));
                        continue;
                    }
                };
                let trial_candidate = match self.document.preview_batch(proposal.batch()) {
                    Ok(candidate) => candidate,
                    Err(error) => {
                        last_rejection = Some(assistant_canonical_rejection(
                            error,
                            "validation_repair",
                            &target,
                        ));
                        continue;
                    }
                };
                let trial_results =
                    ExactResultRegistry::carried_forward(&trial_candidate, &self.exact_results);
                let trial_validation =
                    self.assistant_validation_context(&trial_candidate, &trial_results, selection);
                let Some(trial_total) = Self::assistant_validation_issue_total(&trial_validation)
                else {
                    continue;
                };
                if trial_validation["complete"].as_bool() != Some(true)
                    || trial_validation["requested"] != validation_before["requested"]
                    || Self::assistant_repair_issue_remains(&trial_validation, &operation)
                    || trial_total >= issue_total
                {
                    continue;
                }
                accepted = Some((
                    operation,
                    trial_transforms,
                    proposal,
                    trial_candidate,
                    trial_validation,
                    trial_total,
                ));
                break;
            }
            let Some((
                operation,
                transforms,
                proposal,
                next_candidate,
                next_validation,
                next_total,
            )) = accepted
            else {
                break;
            };
            accepted_operations.push(operation);
            target_transforms = transforms;
            final_proposal = Some(proposal);
            candidate = next_candidate;
            validation_after = next_validation;
            issue_total = next_total;
            if issue_total == 0 {
                break;
            }
        }

        let proposal = final_proposal.ok_or_else(|| {
            last_rejection.unwrap_or_else(|| {
                assistant_rejection(
                    AssistantRejectionPhase::DomainValidation,
                    "validator.no_safe_repair",
                    "validation_repair",
                    &target,
                    "No bounded repair candidate reduced the requested validator issues.",
                    "Revise the model or request a narrower repair after reviewing the validator issues.",
                    true,
                )
            })
        })?;
        let program = AssistantRepairProgram {
            schema: ASSISTANT_REPAIR_PROGRAM_SCHEMA_V1.to_owned(),
            document_id: validation_before["document_id"]
                .as_u64()
                .expect("complete validator evidence carries a document ID"),
            revision_id: validation_before["revision"]
                .as_u64()
                .expect("complete validator evidence carries a revision"),
            canonical_digest: validation_before["canonical_digest"]
                .as_str()
                .expect("complete validator evidence carries a canonical digest")
                .to_owned(),
            max_operations: MAX_ASSISTANT_VALIDATION_ISSUES,
            operations: accepted_operations,
        };
        if !program.validate() {
            return Err(assistant_rejection(
                AssistantRejectionPhase::DomainValidation,
                "validator.repair_program_invalid",
                "validation_repair",
                &target,
                "The generated repair program violates its typed bounds or provenance contract.",
                "Re-run validation against the current canonical snapshot.",
                true,
            ));
        }
        Ok(AssistantPreviewPlan {
            source: AssistantPreviewSource::ValidationRepair(selection.clone()),
            proposal,
            repair: Some(AssistantRepairPreview {
                program,
                validation_before,
                validation_after,
            }),
        })
    }

    fn derive_assistant_preview_plan(
        &self,
        source: &AssistantPreviewSource,
    ) -> AssistantPlanningResult<AssistantPreviewPlan> {
        let proposal = match source {
            AssistantPreviewSource::Workflow(intent) => {
                self.derive_assistant_workflow_proposal(intent)?
            }
            AssistantPreviewSource::Assembly(source) => self
                .derive_assembly_preview_proposal(source)
                .map_err(|error| {
                    assistant_planning_rejection(
                        "planning.assembly_kinematics_invalid",
                        "assembly_kinematics",
                        "current_selection",
                        error,
                        "Restore the original two-occurrence selection and retry the preview.",
                    )
                })?,
            AssistantPreviewSource::Model(intent) => {
                self.derive_assistant_model_proposal(intent)?
            }
            AssistantPreviewSource::CadEdit(program) => {
                self.derive_assistant_cad_edit_proposal(program)?
            }
            AssistantPreviewSource::ValidationRepair(selection) => {
                return self.derive_assistant_validation_repair_plan(selection);
            }
        };
        Ok(AssistantPreviewPlan {
            source: source.clone(),
            proposal,
            repair: None,
        })
    }

    fn prepare_assistant_validation_repair(&mut self, query: &str) -> bool {
        let source =
            AssistantPreviewSource::ValidationRepair(AssistantValidationSelection::parse(query));
        let plan = match self.derive_assistant_preview_plan(&source) {
            Ok(plan) => plan,
            Err(error) => {
                self.assistant_proposal = None;
                self.digest = self.catalog.format(
                    "assistant-digest-rejected",
                    &BTreeMap::from([("reason", error.failed_invariant)]),
                );
                return false;
            }
        };
        self.digest = self.catalog.format(
            "assistant-digest-preview",
            &BTreeMap::from([
                ("reads", plan.authoritative_dependencies().len().to_string()),
                ("writes", plan.authoritative_writes().len().to_string()),
            ]),
        );
        self.status_key = "status-preview";
        self.assistant_verification = None;
        self.assistant_proposal = Some(plan);
        true
    }

    fn prepare_assistant_preview_source(
        &mut self,
        source: AssistantPreviewSource,
    ) -> AssistantPlanningResult<()> {
        let plan = self.derive_assistant_preview_plan(&source)?;
        self.digest = self.catalog.format(
            "assistant-digest-preview",
            &BTreeMap::from([
                ("reads", plan.authoritative_dependencies().len().to_string()),
                ("writes", plan.authoritative_writes().len().to_string()),
            ]),
        );
        self.status_key = "status-preview";
        self.assistant_verification = None;
        self.assistant_proposal = Some(plan);
        Ok(())
    }

    fn prepare_assistant_model_intent_result(
        &mut self,
        intent: AssistantModelIntent,
    ) -> AssistantPlanningResult<()> {
        self.prepare_assistant_preview_source(AssistantPreviewSource::Model(intent))
    }

    pub fn prepare_assistant_model_intent(&mut self, intent: AssistantModelIntent) -> bool {
        match self.prepare_assistant_model_intent_result(intent) {
            Ok(()) => true,
            Err(error) => {
                self.assistant_proposal = None;
                self.digest = self.catalog.format(
                    "assistant-digest-rejected",
                    &BTreeMap::from([("reason", error.failed_invariant)]),
                );
                false
            }
        }
    }

    pub fn apply_assistant_model_intent(&mut self, intent: AssistantModelIntent) -> bool {
        self.prepare_assistant_model_intent(intent)
            && self
                .assistant_proposal
                .as_ref()
                .is_some_and(|plan| Self::assistant_proposal_is_low_risk(&plan.proposal))
            && self.confirm_assistant_proposal()
    }

    fn poll_assistant_chat(&mut self, context: &egui::Context) {
        if let Some(mut pending) = self.assistant_pending_execution.take() {
            let snapshot = self.document.current();
            if snapshot.document_id() != pending.document_id
                || snapshot.revision_id() != pending.revision_id
                || snapshot.canonical_digest() != pending.canonical_digest
            {
                self.assistant_messages.push(AssistantChatMessage {
                    role: AssistantMessageRole::Error,
                    text: self.catalog.text("assistant-error-stale-response"),
                    source: self.catalog.text("assistant-role-error"),
                    diagnostic: None,
                });
            } else {
                let source = if let Some(program) = pending.cad_edit_program.take() {
                    AssistantPreviewSource::CadEdit(program)
                } else {
                    AssistantPreviewSource::Model(
                        pending
                            .result
                            .model_intent
                            .take()
                            .expect("pending execution always carries one mutation program"),
                    )
                };
                match self.prepare_assistant_preview_source(source) {
                    Ok(()) => {
                        let answer = pending.result.message;
                        self.remember_latest_assistant_exchange(&answer);
                        self.assistant_messages.push(AssistantChatMessage {
                            role: AssistantMessageRole::Assistant,
                            text: answer,
                            source: pending.source,
                            diagnostic: None,
                        });
                    }
                    Err(rejection) => {
                        let replan_will_run = rejection.retryable && !pending.replan_attempted;
                        let diagnostic =
                            self.record_assistant_rejection(*rejection, replan_will_run);
                        if replan_will_run {
                            let document_context =
                                self.assistant_replan_context(&pending.message, &diagnostic);
                            if let Err(text) = self.start_assistant_request(
                                context,
                                pending.message,
                                document_context,
                                pending.source.clone(),
                                true,
                            ) {
                                self.assistant_messages.push(AssistantChatMessage {
                                    role: AssistantMessageRole::Error,
                                    text,
                                    source: pending.source,
                                    diagnostic: None,
                                });
                            }
                        }
                    }
                }
            }
            self.store_assistant_conversation();
            return;
        }

        let Some(task) = self.assistant_chat_task.as_ref() else {
            return;
        };
        let source = task.source.clone();
        let request_id = task.request_id.clone();
        let request_message = task.message.clone();
        let replan_attempted = task.replan_attempted;
        let request_document_id = task.document_id;
        let request_revision_id = task.revision_id;
        let request_canonical_digest = task.canonical_digest.clone();
        let request_selected_occurrence_ids = task.selected_occurrence_ids.clone();
        match task.receiver.try_recv() {
            Ok(response) => {
                self.assistant_chat_task = None;
                let result = response.map(|response| {
                    if let Some(diagnostics) = response.diagnostics {
                        self.assistant_api_logs.push(AssistantApiLogEntry {
                            request_id,
                            diagnostics,
                        });
                        if self.assistant_api_logs.len() > 100 {
                            self.assistant_api_logs
                                .drain(..self.assistant_api_logs.len() - 100);
                        }
                        self.assistant_selected_api_log =
                            self.assistant_api_logs.len().checked_sub(1);
                    }
                    let mut cad_edit_program = response.cad_edit_program;
                    if let Some(program) = cad_edit_program.as_mut() {
                        bind_assistant_cad_current_selection(
                            program,
                            &request_selected_occurrence_ids,
                        );
                    }
                    (response.result, cad_edit_program)
                });
                match result {
                    Ok((result, cad_edit_program))
                        if result.model_intent.is_some() || cad_edit_program.is_some() =>
                    {
                        self.assistant_pending_execution = Some(AssistantPendingExecution {
                            result,
                            cad_edit_program,
                            message: request_message,
                            replan_attempted,
                            document_id: request_document_id,
                            revision_id: request_revision_id,
                            canonical_digest: request_canonical_digest,
                            source,
                        });
                        context.request_repaint();
                        return;
                    }
                    Ok((result, _)) => {
                        self.remember_latest_assistant_exchange(&result.message);
                        self.assistant_messages.push(AssistantChatMessage {
                            role: AssistantMessageRole::Assistant,
                            text: result.message,
                            source,
                            diagnostic: None,
                        });
                    }
                    Err(text) => self.assistant_messages.push(AssistantChatMessage {
                        role: AssistantMessageRole::Error,
                        text,
                        source,
                        diagnostic: None,
                    }),
                }
                self.store_assistant_conversation();
            }
            Err(TryRecvError::Empty) => {}
            Err(TryRecvError::Disconnected) => {
                self.assistant_chat_task = None;
                self.assistant_messages.push(AssistantChatMessage {
                    role: AssistantMessageRole::Error,
                    text: self.catalog.text("assistant-error-disconnected"),
                    source,
                    diagnostic: None,
                });
                self.store_assistant_conversation();
            }
        }
    }

    #[must_use]
    pub const fn assistant_verification(&self) -> Option<&AssistantVerification> {
        self.assistant_verification.as_ref()
    }

    #[must_use]
    pub fn assistant_change_can_undo(&self) -> bool {
        self.assistant_verification
            .as_ref()
            .is_some_and(|verification| {
                let snapshot = self.document.current();
                snapshot.revision_id() == verification.revision_id
                    && snapshot.canonical_digest() == verification.canonical_digest
                    && self.can_undo()
            })
    }

    fn assistant_selection_summary(&self) -> String {
        let selected = self.selected_occurrence_ids();
        match selected.len() {
            0 => self.catalog.text("assistant-selection-none"),
            1 => {
                let id = selected
                    .first()
                    .expect("one selected occurrence must have a first item");
                let name = self
                    .document
                    .current()
                    .scene_query()
                    .into_iter()
                    .find(|occurrence| {
                        occurrence.instance_path.is_root() && occurrence.occurrence_id == *id
                    })
                    .map_or_else(
                        || format!("#{}", id.0),
                        |occurrence| occurrence.occurrence_name,
                    );
                self.catalog
                    .format("assistant-selection-one", &BTreeMap::from([("name", name)]))
            }
            count => self.catalog.format(
                "assistant-selection-many",
                &BTreeMap::from([("count", count.to_string())]),
            ),
        }
    }

    /// The localization catalog the shell paints with.
    ///
    /// Acceptance tests resolve expected labels through this catalog instead of
    /// hard-coding English, so a translation change cannot break them.
    #[must_use]
    pub fn catalog(&self) -> &LocaleCatalog {
        &self.catalog
    }

    /// The visible label of `command` in the active locale.
    #[must_use]
    pub fn command_label(&self, command: AppCommand) -> String {
        self.catalog.text(CommandRegistry::spec(command).label_key)
    }

    /// Whether the command can mutate the current selection/state.
    #[must_use]
    pub fn command_is_enabled(&self, command: AppCommand) -> bool {
        self.command_enabled(command)
    }

    #[must_use]
    pub fn document_height_mm(&self) -> f64 {
        self.box_height_mm(INITIAL_BOX_DEFINITION)
            .expect("the initial box definition exists")
    }

    fn box_height_mm(&self, definition_id: DefinitionId) -> Option<f64> {
        self.active_boxes()
            .into_iter()
            .find(|item| item.definition_id == definition_id)
            .map(|item| item.size_mm.z)
    }

    /// Carry the exact products of the previous revision over to `snapshot`.
    ///
    /// A viewport drag commits its revision in the same frame that paints it,
    /// so products still bound to the revision before it would leave that one
    /// frame with nothing to draw and nothing to pick. Rebinding here, before
    /// the frame reads them, keeps the frame whole. Nothing is loosened:
    /// carrying forward re-checks every product against `snapshot` and drops
    /// whatever it no longer carries the evidence for.
    fn rebind_exact_results(&mut self, snapshot: &Snapshot) {
        if !self.exact_results.is_bound_to(snapshot) {
            self.exact_results =
                ExactResultRegistry::carried_forward(snapshot, &self.exact_results);
        }
        if !self.topology_results.is_bound_to(snapshot) {
            self.topology_results =
                ExactResultRegistry::carried_forward(snapshot, &self.topology_results);
        }
    }

    fn refresh_exact_products(&mut self, context: &egui::Context) {
        let snapshot = self.document.current();
        let source = (
            snapshot.document_id(),
            snapshot.revision_id(),
            snapshot.canonical_digest(),
        );
        if self
            .exact_source
            .as_ref()
            .is_some_and(|known| known != &source)
        {
            self.exact_source = None;
        }
        self.rebind_exact_results(&snapshot);
        if self
            .exact_task
            .as_ref()
            .is_some_and(|task| task.source != source)
            && let Some(task) = self.exact_task.take()
        {
            task.cancelled.store(true, Ordering::Release);
        }
        if let Some(task) = self.exact_task.as_ref() {
            match task.receiver.try_recv() {
                Ok(result) => {
                    let task = self.exact_task.take().expect("the completed task exists");
                    if task.source == source && !task.cancelled.load(Ordering::Acquire) {
                        match result.and_then(|products| {
                            let mut results = self.exact_results.clone();
                            for package in products.render_packages {
                                results
                                    .insert_current(&snapshot, package)
                                    .map_err(|error| error.to_string())?;
                            }
                            let mut topology_results = self.topology_results.clone();
                            for package in products.topology_packages {
                                topology_results
                                    .insert_current(&snapshot, package)
                                    .map_err(|error| error.to_string())?;
                            }
                            Ok((results, topology_results))
                        }) {
                            Ok((results, topology_results)) => {
                                let references = results
                                    .values()
                                    .flat_map(|package| package.references())
                                    .cloned()
                                    .collect::<Vec<_>>();
                                if references.into_iter().all(|reference| {
                                    self.document
                                        .register_exact_reference_evidence(reference)
                                        .is_ok()
                                }) && self
                                    .document
                                    .register_exact_reference_evidence(&results)
                                    .is_ok()
                                {
                                    self.exact_results = results;
                                    self.topology_results = topology_results;
                                    self.render_plan =
                                        Some(Arc::new(InstancedRenderPlan::from_snapshot(
                                            &snapshot,
                                            &self.exact_results,
                                            &mut self.render_cache,
                                        )));
                                    self.interaction_projection_cache.get_mut().take();
                                    self.exact_source = None;
                                    self.exact_retry_at = None;
                                    return;
                                }
                            }
                            Err(error) => {
                                eprintln!("exact evaluation rejected: {error}");
                                self.exact_retry_at = Some(Instant::now() + Duration::from_secs(1));
                            }
                        }
                    }
                }
                Err(TryRecvError::Empty) => return,
                Err(TryRecvError::Disconnected) => {
                    self.exact_task = None;
                    self.exact_retry_at = Some(Instant::now() + Duration::from_secs(1));
                }
            }
        }
        if self.exact_source.as_ref() == Some(&source)
            || self
                .exact_retry_at
                .is_some_and(|retry_at| retry_at > Instant::now())
        {
            return;
        }
        if !self.exact_worker_attempted {
            self.exact_worker_attempted = true;
            self.exact_worker_path = exact_worker_candidates()
                .into_iter()
                .find(|path| path.is_file());
        }
        let Some(executable) = self.exact_worker_path.clone() else {
            return;
        };
        let feature_graph = match snapshot.feature_dependency_graph() {
            Ok(graph) => graph,
            Err(_) => {
                self.exact_results.clear();
                self.topology_results.clear();
                self.exact_source = None;
                return;
            }
        };
        let referenced_producers = snapshot
            .features()
            .filter_map(|feature| match feature.kind() {
                FeatureKind::Workplane(WorkplaneSpec {
                    support: WorkplaneSupport::PlanarFace { reference, .. },
                    ..
                }) => Some(reference.producer_feature_id),
                _ => None,
            })
            .collect::<BTreeSet<_>>();
        let requests = snapshot
            .scene_query()
            .into_iter()
            .map(|occurrence| occurrence.definition_id)
            .collect::<BTreeSet<_>>()
            .into_iter()
            .flat_map(|definition_id| {
                let Some(definition) = snapshot.definition(definition_id) else {
                    return Vec::new();
                };
                definition
                    .feature_ids()
                    .iter()
                    .copied()
                    .filter(|feature_id| {
                        snapshot.feature(*feature_id).is_some_and(|feature| {
                            if !feature.kind().produces_body() {
                                return false;
                            }
                            if referenced_producers.contains(feature_id) {
                                return true;
                            }
                            let Some(body_id) = definition
                                .feature_body_ownership(*feature_id)
                                .and_then(|ownership| ownership.output_body_id())
                            else {
                                return false;
                            };
                            let suppressed =
                                snapshot.suppressed_feature_ids(definition_id, body_id);
                            if suppressed.is_some_and(|ids| ids.contains(feature_id)) {
                                return false;
                            }
                            feature_graph
                                .dependents(*feature_id)
                                .is_some_and(|dependents| {
                                    dependents.iter().all(|dependent| {
                                        suppressed.is_some_and(|ids| ids.contains(dependent))
                                            || snapshot.feature(*dependent).is_none_or(|feature| {
                                                !feature.kind().produces_body()
                                                    || definition
                                                        .feature_body_ownership(*dependent)
                                                        .and_then(|ownership| {
                                                            ownership.output_body_id()
                                                        })
                                                        != Some(body_id)
                                            })
                                    })
                                })
                        })
                    })
                    .map(move |feature_id| (definition_id, feature_id))
                    .collect::<Vec<_>>()
            })
            .map(|(definition_id, feature_id)| {
                if self.exact_results.values().any(|package| {
                    package.definition_id() == definition_id
                        && package.producer_feature_id() == feature_id
                        && package.is_current(&snapshot)
                }) {
                    return Ok(None);
                }
                if let Ok(request) = ExactFeatureChainRequest::from_snapshot_for_producer(
                    &snapshot,
                    definition_id,
                    feature_id,
                ) {
                    let topology = snapshot
                        .feature(feature_id)
                        .filter(|feature| {
                            matches!(
                                feature.kind(),
                                FeatureKind::Extrusion { .. } | FeatureKind::Pad(_)
                            )
                        })
                        .and_then(|_| {
                            ExactBRepGraph::from_snapshot(&snapshot, definition_id, feature_id).ok()
                        })
                        .map(Box::new);
                    return Ok(Some((
                        definition_id,
                        ExactEvaluationRequest::Rectangle {
                            request: Box::new(request),
                            topology,
                        },
                    )));
                }
                if let Ok(request) = ExactRevolveRequest::from_snapshot(&snapshot, definition_id)
                    && request.producer_feature_id() == feature_id
                {
                    return Ok(Some((
                        definition_id,
                        ExactEvaluationRequest::Revolve(Box::new(request)),
                    )));
                }
                let graph = if snapshot.feature(feature_id).is_some_and(|feature| {
                    !matches!(feature.kind(), FeatureKind::ImportedExactBody(_))
                }) {
                    match ExactBRepGraph::from_snapshot(&snapshot, definition_id, feature_id) {
                        Ok(graph) => Some(graph),
                        Err(
                            ExactBRepGraphError::UnsupportedFeature(_)
                            | ExactBRepGraphError::UnsupportedProfile(_),
                        ) => None,
                        Err(error) => {
                            eprintln!(
                                "exact B-Rep graph compilation rejected producer {}: {error}",
                                feature_id.0
                            );
                            return Ok(None);
                        }
                    }
                } else {
                    None
                };
                if let Some(graph) = graph {
                    let mut imported_sources = Vec::new();
                    let mut imported_hashes = Vec::new();
                    let mut imported_source_bytes = 0_u64;
                    for node in &graph.nodes {
                        let ExactBRepOperation::ImportedExact {
                            source_sha256,
                            source_byte_len,
                            ..
                        } = &node.operation
                        else {
                            continue;
                        };
                        if imported_hashes.contains(source_sha256) {
                            continue;
                        }
                        let Some(next_source_bytes) =
                            imported_source_bytes.checked_add(*source_byte_len)
                        else {
                            eprintln!(
                                "exact B-Rep graph producer {} exceeds the imported source byte envelope",
                                feature_id.0
                            );
                            return Ok(None);
                        };
                        if imported_hashes.len() >= MAX_EXACT_BREP_GRAPH_IMPORTED_SOURCES
                            || next_source_bytes > MAX_EXACT_BREP_GRAPH_IMPORTED_SOURCE_BYTES
                        {
                            eprintln!(
                                "exact B-Rep graph producer {} exceeds the imported source envelope",
                                feature_id.0
                            );
                            return Ok(None);
                        }
                        imported_source_bytes = next_source_bytes;
                        let hash = source_sha256
                            .iter()
                            .map(|byte| format!("{byte:02x}"))
                            .collect::<String>();
                        let Some(source) = self.container_data.blobs().get(&hash).cloned() else {
                            eprintln!(
                                "exact B-Rep graph producer {} is missing an imported source blob",
                                feature_id.0
                            );
                            return Ok(None);
                        };
                        if source.len() as u64 != *source_byte_len
                            || sha256_bytes(&source) != *source_sha256
                        {
                            eprintln!(
                                "exact B-Rep graph producer {} has a mismatched imported source blob",
                                feature_id.0
                            );
                            return Ok(None);
                        }
                        imported_hashes.push(*source_sha256);
                        imported_sources.push(source);
                    }
                    return Ok(Some((
                        definition_id,
                        ExactEvaluationRequest::Graph {
                            graph: Box::new(graph),
                            imported_sources,
                        },
                    )));
                }
                let Some(feature) = snapshot.feature(feature_id) else {
                    return Ok(None);
                };
                let FeatureKind::ImportedExactBody(spec) = feature.kind() else {
                    return Ok(None);
                };
                let hash = spec
                    .source_sha256
                    .iter()
                    .map(|byte| format!("{byte:02x}"))
                    .collect::<String>();
                let source = self
                    .container_data
                    .blobs()
                    .get(&hash)
                    .cloned()
                    .ok_or_else(|| "imported STEP source blob is missing".to_owned())?;
                if source.len() as u64 != spec.source_byte_len
                    || sha256_bytes(&source) != spec.source_sha256
                {
                    return Err(
                        "imported STEP source blob does not match canonical identity".to_owned(),
                    );
                }
                Ok(Some((
                    definition_id,
                    ExactEvaluationRequest::Imported(definition_id, source),
                )))
            })
            .collect::<Result<Vec<_>, String>>()
            .map(|requests| requests.into_iter().flatten().collect::<Vec<_>>());
        let requests = match requests {
            Ok(requests) => requests,
            Err(_) => {
                self.exact_source = None;
                self.exact_retry_at = Some(Instant::now() + Duration::from_secs(1));
                return;
            }
        };
        if requests.is_empty() {
            self.exact_source = Some(source);
            return;
        }
        let cancelled = Arc::new(AtomicBool::new(false));
        let worker_cancelled = Arc::clone(&cancelled);
        let repaint = context.clone();
        let (sender, receiver) = mpsc::channel();
        std::thread::spawn(move || {
            let result = (|| {
                let mut worker =
                    ExactWorkerSupervisor::spawn_with_cancellation(executable, &worker_cancelled)
                        .map_err(|error| error.to_string())?;
                let mut render_packages = Vec::new();
                let mut topology_packages = Vec::new();
                for (definition_id, request) in requests {
                    if worker_cancelled.load(Ordering::Acquire) {
                        return Err("exact evaluation cancelled".to_owned());
                    }
                    let evaluated =
                        (|| -> Result<(ExactBodyPackage, Option<ExactBodyPackage>), String> {
                            Ok(match request {
                                ExactEvaluationRequest::Graph {
                                    graph,
                                    imported_sources,
                                } => {
                                    let imported_sources = imported_sources
                                        .iter()
                                        .map(Vec::as_slice)
                                        .collect::<Vec<_>>();
                                    let package = worker
                                        .evaluate_exact_brep_graph_with_imported_sources(
                                            &graph,
                                            &imported_sources,
                                        )
                                        .map(ExactBodyPackage::Graph)
                                        .map_err(|error| error.to_string())?;
                                    (package.clone(), Some(package))
                                }
                                ExactEvaluationRequest::Rectangle { request, topology } => {
                                    let package = worker
                                        .evaluate_rectangle_with_cancellation(
                                            &request,
                                            &worker_cancelled,
                                        )
                                        .map(ExactBodyPackage::from)
                                        .map_err(|error| error.to_string())?;
                                    let topology_package = topology.and_then(|graph| {
                                        match worker.evaluate_exact_brep_graph(&graph) {
                                            Ok(package) => Some(ExactBodyPackage::Graph(package)),
                                            Err(error) => {
                                                eprintln!(
                                                    "exact topology evaluation rejected definition {}: {error}",
                                                    definition_id.0
                                                );
                                                None
                                            }
                                        }
                                    });
                                    (package, topology_package)
                                }
                                ExactEvaluationRequest::Revolve(request) => (
                                    worker
                                        .evaluate_revolve_with_cancellation(
                                            &request,
                                            &worker_cancelled,
                                        )
                                        .map(ExactBodyPackage::from)
                                        .map_err(|error| error.to_string())?,
                                    None,
                                ),
                                ExactEvaluationRequest::Imported(definition_id, source) => {
                                    let definition =
                                        snapshot.definition(definition_id).ok_or_else(|| {
                                            "imported STEP definition is unavailable".to_owned()
                                        })?;
                                    let [feature_id] = definition.feature_ids() else {
                                        return Err(
                                            "imported STEP definition is not singular".to_owned()
                                        );
                                    };
                                    let feature =
                                        snapshot.feature(*feature_id).ok_or_else(|| {
                                            "imported STEP feature is unavailable".to_owned()
                                        })?;
                                    let FeatureKind::ImportedExactBody(spec) = feature.kind()
                                    else {
                                        return Err(
                                            "imported STEP canonical specification is unavailable"
                                                .to_owned(),
                                        );
                                    };
                                    let receipt =
                                        snapshot.import_receipt(spec.import_id).ok_or_else(
                                            || "imported STEP receipt is unavailable".to_owned(),
                                        )?;
                                    if receipt.format() != ImportFormat::Step
                                        || receipt.units().authority()
                                            != ImportUnitAuthority::FileDeclared
                                        || receipt.parser_id() != STEP_PARSER_ID
                                        || receipt.parser_version() != STEP_PARSER_VERSION
                                    {
                                        return Err(
                                            "imported STEP receipt provenance is not authoritative"
                                                .to_owned(),
                                        );
                                    }
                                    let source_unit = receipt.units().source_unit();
                                    let mut expected = StepImportEvidence {
                                        source_unit,
                                        result_fingerprint: spec.result_fingerprint.clone(),
                                        solid_count: spec.solid_count,
                                        topology_counts: spec.topology_counts.unwrap_or([0; 5]),
                                        volume_mm3: spec.volume_mm3,
                                        bounds_mm: spec.bounds_mm,
                                        backend: spec.backend.clone(),
                                        tolerance: spec.tolerance.clone(),
                                    };
                                    let mut temporary = tempfile::Builder::new()
                                        .prefix("ketchup-imported-step-")
                                        .suffix(".step")
                                        .tempfile()
                                        .map_err(|error| error.to_string())?;
                                    temporary
                                        .write_all(&source)
                                        .and_then(|_| temporary.flush())
                                        .map_err(|error| error.to_string())?;
                                    let source_sha256 = ketchup_core::graph::sha256_hex(&source);
                                    let actual = worker
                                        .inspect_step_import_with_cancellation(
                                            temporary.path(),
                                            &source_sha256,
                                            &worker_cancelled,
                                        )
                                        .map_err(|error| error.to_string())?;
                                    if spec.topology_counts.is_none() {
                                        expected.topology_counts = actual.topology_counts;
                                    }
                                    if actual != expected {
                                        return Err(format!(
                                            "imported STEP worker evidence does not match canonical specification: expected={expected:?}, actual={actual:?}"
                                        ));
                                    }
                                    let mesh_target = tempfile::Builder::new()
                                        .prefix("ketchup-imported-step-mesh-")
                                        .suffix(".bin")
                                        .tempfile()
                                        .map_err(|error| error.to_string())?;
                                    let mesh = worker
                                        .tessellate_step_import_with_cancellation(
                                            temporary.path(),
                                            &source_sha256,
                                            &spec.result_fingerprint,
                                            mesh_target.path(),
                                            &worker_cancelled,
                                        )
                                        .map_err(|error| error.to_string())?;
                                    let package = ImportedExactPackage::from_snapshot(
                                        &snapshot,
                                        definition_id,
                                        source,
                                        &mesh,
                                    )
                                    .map(ExactBodyPackage::Imported)
                                    .map_err(|error| error.to_string())?;
                                    (package.clone(), Some(package))
                                }
                            })
                        })();
                    let (package, topology_package) = match evaluated {
                        Ok(products) => products,
                        Err(error) => {
                            eprintln!(
                                "exact evaluation rejected definition {}: {error}",
                                definition_id.0
                            );
                            continue;
                        }
                    };
                    render_packages.push(Arc::new(package));
                    if let Some(package) = topology_package {
                        topology_packages.push(Arc::new(package));
                    }
                }
                Ok(ExactEvaluationProducts {
                    render_packages,
                    topology_packages,
                })
            })();
            if !worker_cancelled.load(Ordering::Acquire) && sender.send(result).is_ok() {
                repaint.request_repaint();
            }
        });
        self.exact_task = Some(ExactEvaluationTask {
            source,
            cancelled,
            receiver,
        });
    }

    #[cfg(debug_assertions)]
    #[doc(hidden)]
    pub fn headless_force_exact_worker_path(&mut self, executable: impl AsRef<Path>) {
        self.exact_worker_path = Some(executable.as_ref().to_owned());
        self.exact_worker_attempted = true;
    }

    #[cfg(debug_assertions)]
    #[doc(hidden)]
    pub fn headless_install_exact_package(&mut self, package: ExactBodyPackage) -> bool {
        if let Some(task) = self.exact_task.take() {
            task.cancelled.store(true, Ordering::Release);
        }
        let snapshot = self.document.current();
        let source = (
            snapshot.document_id(),
            snapshot.revision_id(),
            snapshot.canonical_digest(),
        );
        let package = Arc::new(package);
        let mut exact_results = ExactResultRegistry::default();
        let mut topology_results = ExactResultRegistry::default();
        let inserted = exact_results
            .insert_current(&snapshot, Arc::clone(&package))
            .is_ok()
            && (package.topological_references().is_empty()
                || topology_results.insert_current(&snapshot, package).is_ok());
        if inserted {
            self.exact_results = exact_results;
            self.topology_results = topology_results;
            self.exact_source = Some(source);
            self.exact_retry_at = None;
        }
        inserted
    }

    pub fn connect_exact_worker(&mut self, executable: impl AsRef<Path>) -> Result<(), String> {
        let executable = executable.as_ref();
        if !executable.is_file() {
            return Err("exact worker executable was not found".to_owned());
        }
        if let Some(task) = self.exact_task.take() {
            task.cancelled.store(true, Ordering::Release);
        }
        #[cfg(feature = "named-product-fixtures")]
        if let Some(task) = self.beam_m5_task.take() {
            task.cancelled.store(true, Ordering::Release);
        }
        self.exact_worker_path = Some(executable.to_owned());
        self.exact_worker_attempted = true;
        self.exact_results.clear();
        self.topology_results.clear();
        self.exact_source = None;
        self.exact_retry_at = None;
        #[cfg(feature = "named-product-fixtures")]
        {
            self.beam_m5_products = None;
            self.beam_exact_results.clear();
            self.beam_m5_source = None;
            self.beam_m5_retry_at = None;
        }
        Ok(())
    }

    #[doc(hidden)]
    pub fn enable_headless_instanced_scene(&mut self) {
        self.wgpu_target_format = Some(eframe::wgpu::TextureFormat::Bgra8UnormSrgb);
    }

    fn visible_exact_packages<'a>(
        &'a self,
        snapshot: &'a Snapshot,
    ) -> Vec<&'a Arc<ExactBodyPackage>> {
        let visible_definitions = snapshot
            .scene_query()
            .into_iter()
            .filter(|occurrence| occurrence.visible)
            .map(|occurrence| occurrence.definition_id)
            .collect::<BTreeSet<_>>();
        self.exact_results
            .render_values(snapshot)
            .filter(|package| visible_definitions.contains(&package.definition_id()))
            .collect()
    }

    #[must_use]
    pub fn exact_render_body_count(&self) -> usize {
        let snapshot = self.document.current();
        self.visible_exact_packages(&snapshot).len()
    }

    #[doc(hidden)]
    #[must_use]
    pub fn exact_current_producer_ids(&self) -> Vec<FeatureId> {
        let snapshot = self.document.current();
        self.visible_exact_packages(&snapshot)
            .into_iter()
            .map(|package| package.producer_feature_id())
            .collect()
    }

    #[must_use]
    pub fn exact_render_bounds(&self) -> Vec<[[f64; 3]; 2]> {
        let snapshot = self.document.current();
        self.visible_exact_packages(&snapshot)
            .into_iter()
            .map(|package| package.bounds_mm())
            .collect()
    }

    /// How many triangles the current exact render products actually carry.
    ///
    /// An exact body with no triangles is invisible and unpickable, which is
    /// indistinguishable from a failed import, so tests assert on this.
    #[must_use]
    pub fn exact_render_triangle_count(&self) -> usize {
        let snapshot = self.document.current();
        self.visible_exact_packages(&snapshot)
            .into_iter()
            .map(|package| package.triangles().len())
            .sum()
    }

    /// How many triangles the instanced scene would actually paint.
    ///
    /// This reads the plan the last painted frame used, so a body that exists
    /// as an exact product but never reached the scene reports zero here.
    #[must_use]
    pub fn instanced_scene_triangle_count(&self) -> usize {
        self.render_plan.as_ref().map_or(0, |plan| {
            plan.batches()
                .iter()
                .map(|batch| batch.geometry.index_count() / 3 * batch.instances.len())
                .sum()
        })
    }

    #[must_use]
    pub fn exact_stable_reference_count(&self) -> usize {
        let snapshot = self.document.current();
        self.visible_exact_packages(&snapshot)
            .into_iter()
            .map(|package| package.references().len())
            .sum()
    }

    fn exact_projection(&self, snapshot: &Snapshot) -> ExactInteractionProjection {
        ExactInteractionProjection::from_snapshot(snapshot, &self.exact_results)
    }

    fn topology_projection(&self, snapshot: &Snapshot) -> ExactInteractionProjection {
        ExactInteractionProjection::from_snapshot(snapshot, &self.topology_results)
    }

    /// The cached feature edges of `definition_id`, rebuilt only when
    /// `identity` changes.
    ///
    /// Deriving them costs seconds on an imported mesh, so recomputing them
    /// every frame freezes the viewport while a body is hovered or selected.
    fn overlay_feature_edges<G: Copy + Ord>(
        &self,
        definition_id: DefinitionId,
        identity: &str,
        build: impl FnOnce() -> (Vec<[f32; 3]>, Vec<[u32; 3]>, Vec<Option<G>>),
    ) -> Arc<Vec<([u32; 2], Vec<u32>)>> {
        let mut cache = self.overlay_edge_cache.borrow_mut();
        if let Some(cached) = cache.get(&definition_id)
            && cached.identity == identity
        {
            return Arc::clone(&cached.edges);
        }
        let (positions, triangles, face_groups) = build();
        let edges = Arc::new(renderer::feature_edge_triangles(
            &positions,
            &triangles,
            &face_groups,
        ));
        cache.insert(
            definition_id,
            OverlayEdges {
                identity: identity.to_owned(),
                edges: Arc::clone(&edges),
            },
        );
        edges
    }

    fn refresh_interaction_projection_cache(&self, snapshot: &Snapshot) {
        let Ok(cache) = self.interaction_projection_cache.try_borrow() else {
            return;
        };
        let rebuild = cache.as_ref().is_none_or(|cache| {
            cache.document_id != snapshot.document_id()
                || cache.revision_id != snapshot.revision_id()
                || cache.edit_context != self.selection.edit_context
                || cache.exact_results_stamp != self.exact_results.contents_stamp()
        });
        drop(cache);
        if rebuild {
            let active_context_paths = self
                .active_scene_query()
                .into_iter()
                .map(|occurrence| occurrence.instance_path)
                .collect::<BTreeSet<_>>();
            let canonical = CanonicalInteractionProjection::from_snapshot(snapshot);
            let exact = ExactInteractionProjection::from_snapshot_where(
                snapshot,
                &self.exact_results,
                |path| active_context_paths.contains(path),
            );
            let mesh = MeshInteractionProjection::from_snapshot_where(snapshot, |path| {
                active_context_paths.contains(path) && !exact.contains_occurrence(path)
            });
            let boxes = canonical
                .scene_where(|occurrence| {
                    active_context_paths.contains(&occurrence.instance_path)
                        && !exact.contains_occurrence(&occurrence.instance_path)
                        && !mesh.contains_occurrence(&occurrence.instance_path)
                        && occurrence.local_box.is_some()
                })
                .expect("canonical visible box projections are valid");
            let proxies = canonical
                .scene_where(|occurrence| {
                    active_context_paths.contains(&occurrence.instance_path)
                        && occurrence.local_box.is_some()
                })
                .expect("canonical visible proxy projections are valid");
            if let Ok(mut cache) = self.interaction_projection_cache.try_borrow_mut() {
                *cache = Some(InteractionProjectionCache {
                    document_id: snapshot.document_id(),
                    revision_id: snapshot.revision_id(),
                    edit_context: self.selection.edit_context.clone(),
                    exact_results_stamp: self.exact_results.contents_stamp(),
                    canonical,
                    exact,
                    mesh,
                    boxes,
                    proxies,
                });
            }
        }
    }

    #[must_use]
    pub fn exact_pick_durable(&self, ray: Ray) -> Option<AssemblySelectionTarget> {
        let snapshot = self.document.current();
        self.exact_projection(&snapshot)
            .exact_pick(ray)
            .map(|hit| hit.target)
    }

    fn hidden_ghost_corners(
        &self,
        snapshot: &Snapshot,
        projection: &InteractionProjection,
    ) -> Vec<[Vec3; 8]> {
        projection
            .occurrences()
            .iter()
            .filter(|occurrence| !occurrence.visible)
            .filter_map(|occurrence| {
                let [minimum, maximum] = self.definition_local_bounds(
                    snapshot,
                    occurrence.body.definition_id,
                    occurrence.local_box,
                )?;
                let size = maximum - minimum;
                Some(box_corners(size.x, size.y, size.z).map(|corner| {
                    transform_model_point(occurrence.canonical_world_transform, corner + minimum)
                }))
            })
            .collect()
    }

    fn active_frame_bounds(&self) -> Vec<(Vec3, Vec3)> {
        let mut bounds = self
            .active_boxes()
            .into_iter()
            .map(|item| (item.origin_mm, item.size_mm))
            .collect::<Vec<_>>();
        let snapshot = self.document.current();
        for occurrence in self.active_scene_query() {
            let Some(definition) = snapshot.definition(occurrence.definition_id) else {
                continue;
            };
            let matrix = occurrence.transform.matrix();
            let mut mesh_vertices = definition
                .feature_ids()
                .iter()
                .filter_map(|feature_id| snapshot.feature(*feature_id))
                .filter_map(|feature| match feature.kind() {
                    FeatureKind::MeshBody(mesh) => Some(mesh.vertices_mm.iter()),
                    _ => None,
                })
                .flatten()
                .map(|vertex| {
                    Vec3::new(
                        matrix[0] * vertex[0]
                            + matrix[1] * vertex[1]
                            + matrix[2] * vertex[2]
                            + matrix[3],
                        matrix[4] * vertex[0]
                            + matrix[5] * vertex[1]
                            + matrix[6] * vertex[2]
                            + matrix[7],
                        matrix[8] * vertex[0]
                            + matrix[9] * vertex[1]
                            + matrix[10] * vertex[2]
                            + matrix[11],
                    )
                });
            let Some(first) = mesh_vertices.next() else {
                continue;
            };
            let (minimum, maximum) =
                mesh_vertices.fold((first, first), |(minimum, maximum), point| {
                    (
                        Vec3::new(
                            minimum.x.min(point.x),
                            minimum.y.min(point.y),
                            minimum.z.min(point.z),
                        ),
                        Vec3::new(
                            maximum.x.max(point.x),
                            maximum.y.max(point.y),
                            maximum.z.max(point.z),
                        ),
                    )
                });
            bounds.push((minimum, maximum - minimum));
        }
        bounds
    }

    fn active_boxes(&self) -> Vec<RenderBox> {
        let snapshot = self.document.current();
        self.refresh_interaction_projection_cache(&snapshot);
        let cache = self.interaction_projection_cache.borrow();
        self.render_boxes_from_projection(
            &cache
                .as_ref()
                .expect("interaction cache was built")
                .canonical,
            true,
        )
    }

    fn active_boxes_for_snapshot(&self, snapshot: &Snapshot) -> Vec<RenderBox> {
        let current = self.document.current();
        if snapshot.revision_id() == current.revision_id()
            && snapshot.canonical_digest() == current.canonical_digest()
        {
            return self.active_boxes();
        }
        self.render_boxes_from_projection(
            &CanonicalInteractionProjection::from_snapshot(snapshot),
            false,
        )
    }

    fn render_boxes_from_projection(
        &self,
        projection: &InteractionProjection,
        use_exact_bounds: bool,
    ) -> Vec<RenderBox> {
        let snapshot = self.document.current();
        let exact_packages =
            use_exact_bounds.then(|| self.exact_results.render_by_definition(&snapshot));
        let mut exact_solid_tool_features = BTreeMap::new();
        projection
            .occurrences()
            .iter()
            .filter(|occurrence| occurrence.visible)
            .filter_map(|occurrence| {
                if occurrence.box_proxy.is_none() {
                    if definition_requires_evaluated_geometry(
                        &snapshot,
                        occurrence.body.definition_id,
                    ) && exact_packages
                        .as_ref()
                        .and_then(|packages| packages.get(&occurrence.body.definition_id))
                        .is_none()
                    {
                        return None;
                    }
                    let [minimum, maximum] = self.definition_local_bounds(
                        &snapshot,
                        occurrence.body.definition_id,
                        occurrence.local_box,
                    )?;
                    let size = maximum - minimum;
                    let [world_minimum, world_maximum] = bounds_of(
                        box_corners(size.x, size.y, size.z)
                            .into_iter()
                            .map(|corner| {
                                transform_model_point(
                                    occurrence.canonical_world_transform,
                                    corner + minimum,
                                )
                            }),
                    )?;
                    let profile_feature_id = occurrence
                        .body
                        .profile_feature_id
                        .or_else(|| {
                            *exact_solid_tool_features
                                .entry(occurrence.body.definition_id)
                                .or_insert_with(|| {
                                    exact_solid_tool_feature_id(
                                        &snapshot,
                                        occurrence.body.definition_id,
                                    )
                                })
                        })
                        .or_else(|| {
                            snapshot
                                .definition(occurrence.body.definition_id)?
                                .feature_ids()
                                .iter()
                                .find_map(|feature_id| {
                                    matches!(
                                        snapshot.feature(*feature_id)?.kind(),
                                        FeatureKind::Profile { .. }
                                            | FeatureKind::SegmentProfile { .. }
                                            | FeatureKind::SplineProfile { .. }
                                            | FeatureKind::Sketch(_)
                                    )
                                    .then_some(*feature_id)
                                })
                        })?;
                    return Some(RenderBox {
                        definition_id: occurrence.body.definition_id,
                        profile_feature_id,
                        extrusion_feature_id: occurrence.body.extrusion_feature_id,
                        instance_path: occurrence.instance_path.clone(),
                        origin_mm: world_minimum,
                        size_mm: world_maximum - world_minimum,
                    });
                }
                let box_proxy = occurrence.box_proxy?;
                let exact_bounds =
                    exact_packages
                        .as_ref()
                        .and_then(|packages| packages.get(&occurrence.body.definition_id))
                        .and_then(|package| {
                            let [minimum, maximum] = package.bounds_mm();
                            let minimum = Vec3::new(minimum[0], minimum[1], minimum[2]);
                            let maximum = Vec3::new(maximum[0], maximum[1], maximum[2]);
                            let size = maximum - minimum;
                            bounds_of(box_corners(size.x, size.y, size.z).into_iter().map(
                                |corner| {
                                    transform_model_point(
                                        occurrence.canonical_world_transform,
                                        corner + minimum,
                                    )
                                },
                            ))
                        })
                        .map(|[minimum, maximum]| (minimum, maximum - minimum));
                let (origin_mm, size_mm) =
                    exact_bounds.unwrap_or((box_proxy.origin_mm, box_proxy.size_mm));
                Some(RenderBox {
                    definition_id: occurrence.body.definition_id,
                    profile_feature_id: occurrence.body.profile_feature_id?,
                    extrusion_feature_id: occurrence.body.extrusion_feature_id,
                    instance_path: occurrence.instance_path.clone(),
                    origin_mm,
                    size_mm,
                })
            })
            .collect()
    }

    #[must_use]
    pub fn active_box_count(&self) -> usize {
        self.document.current().scene_query().len()
    }

    /// Canonical definition referenced by an occurrence.
    #[must_use]
    pub fn occurrence_definition_id(&self, occurrence_id: OccurrenceId) -> Option<DefinitionId> {
        self.document
            .current()
            .occurrence(occurrence_id)
            .map(|occurrence| occurrence.definition_id())
    }

    /// Derived box origin and size for an occurrence in model millimetres.
    #[must_use]
    pub fn occurrence_box_geometry(&self, occurrence_id: u64) -> Option<(Vec3, Vec3)> {
        self.active_boxes()
            .into_iter()
            .find(|item| item.instance_path == InstancePath::root(OccurrenceId(occurrence_id)))
            .map(|item| (item.origin_mm, item.size_mm))
    }

    /// Where a world point currently lands inside the viewport.
    ///
    /// Callers that need to aim at real geometry must ask the camera instead of
    /// assuming a screen offset: under a converging projection the pixels per
    /// millimetre depend on how far the point is from the eye.
    #[must_use]
    pub fn project_to_screen(&self, point: Vec3, rect: Rect) -> Pos2 {
        self.project(point, rect)
    }

