    fn selected_definition_id(&self) -> Option<DefinitionId> {
        let selected = self.selected_instance_paths();
        let definitions = self
            .active_scene_query()
            .into_iter()
            .filter(|item| selected.contains(&item.instance_path))
            .map(|item| item.definition_id)
            .collect::<BTreeSet<_>>();
        (definitions.len() == 1).then(|| *definitions.first().expect("one definition exists"))
    }

    fn select_all_instances_source_plan(&self) -> Option<SelectAllInstancesSourcePlan> {
        if self.selection.selected_group.is_some() {
            return None;
        }
        let source_instance_paths = self.selected_instance_paths();
        let source_count = source_instance_paths.len();
        let source_instance_path = (source_count == 1).then(|| {
            source_instance_paths
                .first()
                .expect("one selected instance exists")
                .clone()
        })?;
        let scene = self.active_scene_query();
        let source = scene
            .iter()
            .find(|item| item.instance_path == source_instance_path)?;
        let definition_id = source.definition_id;
        let definition_name = source.definition_name.clone();
        let target_instance_paths = scene
            .into_iter()
            .filter(|item| item.definition_id == definition_id)
            .map(|item| item.instance_path)
            .collect::<BTreeSet<_>>();
        let target_count = target_instance_paths.len();
        (target_count > 1).then_some(SelectAllInstancesSourcePlan {
            source_revision: self.document_revision(),
            source_instance_paths,
            source_count,
            source_primary: self.selection.primary.clone(),
            source_selected_group: self.selection.selected_group,
            edit_context: self.selection.edit_context.clone(),
            source_instance_path,
            definition_id,
            definition_name,
            target_instance_paths,
            target_count,
        })
    }

    fn selection_count(&self) -> usize {
        self.selected_instance_paths().len()
    }

    fn active_scene_query(&self) -> Vec<SceneOccurrence> {
        self.active_scene_query_for_snapshot(&self.document.current())
    }

    fn active_scene_query_for_snapshot(&self, snapshot: &Snapshot) -> Vec<SceneOccurrence> {
        let Some(context) = self.selection.edit_context.last() else {
            return snapshot
                .scene_query()
                .into_iter()
                .filter(|occurrence| occurrence.visible && occurrence.instance_path.is_root())
                .collect();
        };
        let context = match context {
            EditContext::Group(group_id) => SceneQueryContext::Group(*group_id),
            EditContext::Definition {
                definition_id,
                instance_path,
            } => SceneQueryContext::Definition {
                definition_id: *definition_id,
                instance_path: instance_path.clone(),
            },
        };
        snapshot
            .bind_scene_query(context)
            .and_then(|query| snapshot.scene_query_in(&query))
            .unwrap_or_default()
    }

    fn occurrence_in_active_context(&self, instance_path: &InstancePath) -> bool {
        self.active_scene_query()
            .into_iter()
            .any(|occurrence| occurrence.instance_path == *instance_path)
    }

    fn select_group(&mut self, group_id: GroupId) -> bool {
        let snapshot = self.document.current();
        let Some(group) = snapshot.group(group_id) else {
            return false;
        };
        let ids = self
            .active_scene_query()
            .into_iter()
            .filter(|occurrence| {
                occurrence.instance_path.is_root() && occurrence.parent == Some(group_id)
            })
            .map(|occurrence| occurrence.instance_path)
            .collect::<BTreeSet<_>>();
        if ids.is_empty() {
            return false;
        }
        let name = group.name().to_owned();
        self.selection.clear();
        self.selection.occurrences = ids;
        self.selection.selected_group = Some(group_id);
        self.digest = self.catalog.format(
            "digest-selected-group",
            &BTreeMap::from([
                ("name", name),
                ("count", self.selection_count().to_string()),
            ]),
        );
        true
    }

    fn enter_group_context(&mut self, group_id: GroupId) -> bool {
        if self.document.current().group(group_id).is_none() {
            return false;
        }
        self.selection
            .edit_context
            .push(EditContext::Group(group_id));
        self.invalidate_pending_import_reviews();
        self.selection.clear();
        self.digest = self.catalog.text("digest-entered-group-context");
        true
    }

    fn enter_occurrence_context(&mut self, instance_path: InstancePath) -> bool {
        let snapshot = self.document.current();
        let Ok(resolved) = snapshot.resolve_instance_path(&instance_path) else {
            return false;
        };
        if !self.occurrence_in_active_context(&instance_path) {
            return false;
        }
        let root = snapshot.occurrence(instance_path.root_occurrence());
        let context = match (self.selection.edit_context.last(), root) {
            (None, Some(occurrence))
                if instance_path.is_root() && occurrence.parent().is_some() =>
            {
                EditContext::Group(occurrence.parent().unwrap())
            }
            _ => EditContext::Definition {
                definition_id: resolved.definition_id,
                instance_path,
            },
        };
        self.selection.edit_context.push(context.clone());
        self.invalidate_pending_import_reviews();
        self.selection.clear();
        self.digest = self.catalog.text(match context {
            EditContext::Group(_) => "digest-entered-group-context",
            EditContext::Definition { .. } => "digest-entered-component-context",
        });
        true
    }

    fn exit_edit_context(&mut self) -> bool {
        if self.selection.edit_context.pop().is_none() {
            return false;
        }
        self.invalidate_pending_import_reviews();
        self.selection.clear();
        self.digest = self.catalog.text("digest-exited-edit-context");
        true
    }

    fn deselect_source_plan(&self) -> Option<DeselectSourcePlan> {
        (!self.selection.occurrences.is_empty()
            || self.selection.primary.is_some()
            || self.selection.selected_group.is_some())
        .then(|| DeselectSourcePlan {
            source_revision: self.document_revision(),
            occurrence_paths: self.selection.occurrences.clone(),
            occurrence_count: self.selection.occurrences.len(),
            primary: self.selection.primary.clone(),
            selected_group: self.selection.selected_group,
            edit_context: self.selection.edit_context.clone(),
        })
    }

    fn apply_deselect_source_plan(&mut self, plan: DeselectSourcePlan) -> bool {
        if plan.occurrence_count != plan.occurrence_paths.len()
            || self.deselect_source_plan().as_ref() != Some(&plan)
        {
            return false;
        }
        self.selection.clear();
        self.digest = self.catalog.text("digest-selection-cleared");
        true
    }

    fn clear_selection(&mut self) -> bool {
        let Some(plan) = self.deselect_source_plan() else {
            return false;
        };
        self.apply_deselect_source_plan(plan)
    }

    fn bind_topological_selection(
        &self,
        locator: &TopologicalPickLocator,
    ) -> Option<SnapshotBoundTopologicalSelection> {
        let snapshot = self.document.current();
        self.topology_projection(&snapshot)
            .topological_pick_current(&snapshot, &self.topology_results, locator)
            .ok()
    }

    fn topological_push_pull_box(
        &self,
        snapshot: &Snapshot,
        target: &SelectionId,
        reference: &TopologicalElementRef,
    ) -> Option<RenderBox> {
        let package = self
            .topology_results
            .get_render(snapshot, reference.definition_id)?;
        if reference.kind != TopologicalElementKind::Face
            || reference.definition_id != target.definition_id
            || reference.producer_feature_id != package.producer_feature_id()
        {
            return None;
        }
        let occurrence = snapshot
            .scene_query()
            .into_iter()
            .find(|occurrence| occurrence.instance_path == target.instance_path)?;
        let matrix = occurrence.transform.matrix();
        if matrix[0] != 1.0
            || matrix[1] != 0.0
            || matrix[2] != 0.0
            || matrix[4] != 0.0
            || matrix[5] != 1.0
            || matrix[6] != 0.0
            || matrix[8] != 0.0
            || matrix[9] != 0.0
            || matrix[10] != 1.0
            || matrix[12] != 0.0
            || matrix[13] != 0.0
            || matrix[14] != 0.0
            || matrix[15] != 1.0
        {
            return None;
        }
        let [minimum, maximum] = package.bounds_mm();
        Some(RenderBox {
            definition_id: target.definition_id,
            profile_feature_id: reference.producer_feature_id,
            extrusion_feature_id: None,
            instance_path: target.instance_path.clone(),
            origin_mm: Vec3::new(
                minimum[0] + matrix[3],
                minimum[1] + matrix[7],
                minimum[2] + matrix[11],
            ),
            size_mm: Vec3::new(
                maximum[0] - minimum[0],
                maximum[1] - minimum[1],
                maximum[2] - minimum[2],
            ),
        })
    }

    fn topological_push_pull_face_element(
        &self,
        snapshot: &Snapshot,
        reference: &TopologicalElementRef,
    ) -> Option<ElementId> {
        if reference.kind != TopologicalElementKind::Face {
            return None;
        }
        let package = self
            .topology_results
            .get_render(snapshot, reference.definition_id)?;
        if package.producer_feature_id() != reference.producer_feature_id {
            return None;
        }
        axis_aligned_topological_face_element(package.as_ref(), reference)
    }

    #[doc(hidden)]
    pub fn select_topological_locator(&mut self, locator: TopologicalPickLocator) -> bool {
        let Some(topological) = self.bind_topological_selection(&locator) else {
            return false;
        };
        let target = topological.target();
        let element = match locator.kind {
            TopologicalElementKind::Face => self
                .topological_push_pull_face_element(&self.document.current(), &target.reference)
                .unwrap_or(ElementId::Face {
                    axis: Axis::Z,
                    side: Side::Maximum,
                }),
            TopologicalElementKind::Edge => {
                let Ok(ordinal) = u8::try_from(locator.ordinal) else {
                    return false;
                };
                ElementId::Edge(ordinal)
            }
            TopologicalElementKind::Vertex => {
                let Ok(ordinal) = u8::try_from(locator.ordinal) else {
                    return false;
                };
                ElementId::Endpoint(ordinal)
            }
        };
        self.selection.select_topological(
            SelectionId {
                definition_id: target.reference.definition_id,
                instance_path: target.instance_path.clone(),
                element,
            },
            topological,
        );
        true
    }

    fn select_from_viewport(&mut self, target: Option<SelectionId>, additive: bool) {
        let Some(target) = target else {
            if !additive {
                self.clear_selection();
            }
            return;
        };
        let occurrence_id = target.instance_path.root_occurrence();
        if !self.occurrence_in_active_context(&target.instance_path) {
            return;
        }
        let snapshot = self.document.current();
        if self.selection.edit_context.is_empty()
            && target.instance_path.is_root()
            && let Some(group_id) = snapshot
                .occurrence(occurrence_id)
                .and_then(|occurrence| occurrence.parent())
        {
            self.select_group(group_id);
            return;
        }
        self.selection.select_exact(target.clone(), additive);
        if let Some(item) = snapshot
            .scene_query()
            .into_iter()
            .find(|item| item.instance_path == target.instance_path)
        {
            self.digest = self.catalog.format(
                "digest-selected-viewport",
                &BTreeMap::from([
                    ("name", item.definition_name),
                    ("count", item.shared_occurrence_count.to_string()),
                ]),
            );
        }
    }

    fn select_from_outliner(&mut self, instance_path: InstancePath, additive: bool) {
        if !self.occurrence_in_active_context(&instance_path) {
            return;
        }
        let snapshot = self.document.current();
        let root_id = instance_path.root_occurrence();
        if self.selection.edit_context.is_empty()
            && instance_path.is_root()
            && let Some(group_id) = snapshot
                .occurrence(root_id)
                .and_then(|occurrence| occurrence.parent())
        {
            self.select_group(group_id);
            return;
        }
        self.selection.select_path(instance_path.clone(), additive);
        if let Some(item) = snapshot
            .scene_query()
            .into_iter()
            .find(|item| item.instance_path == instance_path)
        {
            self.digest = self.catalog.format(
                "digest-selected-outliner",
                &BTreeMap::from([("name", item.occurrence_name)]),
            );
        }
    }

    fn select_definition(&mut self, definition_id: DefinitionId, additive: bool) {
        let snapshot = self.document.current();
        let Some(definition) = snapshot.definition(definition_id) else {
            return;
        };
        let ids = self
            .active_scene_query()
            .into_iter()
            .filter(|item| item.definition_id == definition_id)
            .map(|item| item.instance_path)
            .collect::<Vec<_>>();
        let name = definition.name().to_owned();
        if !additive {
            self.selection.clear();
        }
        self.selection.occurrences.extend(ids.iter().cloned());
        self.digest = self.catalog.format(
            "digest-selected-definition",
            &BTreeMap::from([("name", name), ("count", ids.len().to_string())]),
        );
    }

    fn apply_select_all_instances_source_plan(
        &mut self,
        plan: SelectAllInstancesSourcePlan,
    ) -> bool {
        if plan.source_revision != self.document_revision()
            || plan.source_count != plan.source_instance_paths.len()
            || plan.target_count != plan.target_instance_paths.len()
            || !plan
                .target_instance_paths
                .contains(&plan.source_instance_path)
            || self.select_all_instances_source_plan().as_ref() != Some(&plan)
        {
            return false;
        }
        self.selection.clear();
        self.selection.occurrences = plan.target_instance_paths;
        self.digest = self.catalog.format(
            "digest-selected-definition",
            &BTreeMap::from([
                ("name", plan.definition_name),
                ("count", plan.target_count.to_string()),
            ]),
        );
        true
    }

    fn select_all_instances(&mut self) -> bool {
        let Some(plan) = self.select_all_instances_source_plan() else {
            return false;
        };
        self.apply_select_all_instances_source_plan(plan)
    }

    fn select_all_source_plan(&self) -> Option<SelectAllSourcePlan> {
        let target_instance_paths = self
            .active_scene_query()
            .into_iter()
            .map(|item| item.instance_path)
            .collect::<BTreeSet<_>>();
        let target_count = target_instance_paths.len();
        (target_count > 0
            && (self.selection.primary.is_some()
                || self.selection.selected_group.is_some()
                || self.selection.occurrences != target_instance_paths))
            .then_some(SelectAllSourcePlan {
                source_revision: self.document_revision(),
                source_occurrence_paths: self.selection.occurrences.clone(),
                source_primary: self.selection.primary.clone(),
                source_selected_group: self.selection.selected_group,
                edit_context: self.selection.edit_context.clone(),
                target_instance_paths,
                target_count,
            })
    }

    fn apply_select_all_source_plan(&mut self, plan: SelectAllSourcePlan) -> bool {
        if plan.target_count != plan.target_instance_paths.len()
            || self.select_all_source_plan().as_ref() != Some(&plan)
        {
            return false;
        }
        self.selection.clear();
        self.selection.occurrences = plan.target_instance_paths;
        self.digest = self.catalog.format(
            "digest-selected-all",
            &BTreeMap::from([("count", plan.target_count.to_string())]),
        );
        true
    }

    fn select_all(&mut self) -> bool {
        let Some(plan) = self.select_all_source_plan() else {
            return false;
        };
        self.apply_select_all_source_plan(plan)
    }

    fn invert_selection_source_plan(&self) -> Option<InvertSelectionSourcePlan> {
        let active_instance_paths = self
            .active_scene_query()
            .into_iter()
            .filter(|item| item.visible)
            .map(|item| item.instance_path)
            .collect::<BTreeSet<_>>();
        if active_instance_paths.is_empty() {
            return None;
        }
        let selected_instance_paths = self.selected_instance_paths();
        let target_instance_paths = active_instance_paths
            .difference(&selected_instance_paths)
            .cloned()
            .collect::<BTreeSet<_>>();
        let target_count = target_instance_paths.len();
        Some(InvertSelectionSourcePlan {
            source_revision: self.document_revision(),
            source_occurrence_paths: self.selection.occurrences.clone(),
            source_primary: self.selection.primary.clone(),
            source_selected_group: self.selection.selected_group,
            edit_context: self.selection.edit_context.clone(),
            active_instance_paths,
            target_instance_paths,
            target_count,
        })
    }

    fn apply_invert_selection_source_plan(&mut self, plan: InvertSelectionSourcePlan) -> bool {
        if plan.target_count != plan.target_instance_paths.len()
            || self.invert_selection_source_plan().as_ref() != Some(&plan)
        {
            return false;
        }
        self.selection.clear();
        self.selection.occurrences = plan.target_instance_paths;
        self.digest = self.catalog.format(
            "digest-inverted-selection",
            &BTreeMap::from([("count", plan.target_count.to_string())]),
        );
        true
    }

    fn invert_selection(&mut self) -> bool {
        let Some(plan) = self.invert_selection_source_plan() else {
            return false;
        };
        self.apply_invert_selection_source_plan(plan)
    }

    fn outliner_query(&self) -> Vec<OutlinerDefinition> {
        let snapshot = self.document.current();
        let projection = CanonicalInteractionProjection::from_snapshot(&snapshot);
        let scoped = !self.selection.edit_context.is_empty();
        let scene = if scoped {
            self.active_scene_query()
        } else {
            snapshot.scene_query()
        };
        snapshot
            .definitions()
            .filter(|definition| {
                !scoped
                    || scene
                        .iter()
                        .any(|occurrence| occurrence.definition_id == definition.id())
            })
            .map(|definition| {
                let size = projection
                    .occurrences()
                    .iter()
                    .find(|occurrence| occurrence.body.definition_id == definition.id())
                    .and_then(|occurrence| occurrence.local_box.map(|local_box| local_box.size_mm))
                    .unwrap_or(Vec3::ZERO);
                let occurrences = scene
                    .iter()
                    .filter(|item| item.definition_id == definition.id())
                    .map(|item| {
                        #[cfg(test)]
                        let matrix = item.transform.matrix();
                        OutlinerOccurrence {
                            instance_path: item.instance_path.clone(),
                            name: item.occurrence_name.clone(),
                            #[cfg(test)]
                            position: format!(
                                "{},{}",
                                format_height(matrix[3]),
                                format_height(matrix[7])
                            ),
                            visible: item.visible,
                            parent: item.parent,
                        }
                    })
                    .collect();
                OutlinerDefinition {
                    id: definition.id(),
                    name: definition.name().to_owned(),
                    specification: format!(
                        "{} × {} × {}",
                        format_height(size.x),
                        format_height(size.y),
                        format_height(size.z)
                    ),
                    occurrences,
                }
            })
            .collect()
    }

    fn outliner_groups(&self) -> Vec<OutlinerGroup> {
        let snapshot = self.document.current();
        snapshot
            .groups()
            .map(|group| OutlinerGroup {
                id: group.id(),
                name: group.name().to_owned(),
                member_count: snapshot
                    .occurrences()
                    .filter(|occurrence| occurrence.parent() == Some(group.id()))
                    .count(),
            })
            .collect()
    }

    fn selected_group_id(&self) -> Option<GroupId> {
        if let Some(group_id) = self.selection.selected_group {
            return Some(group_id);
        }
        let snapshot = self.document.current();
        let mut ids = self.selected_occurrence_ids().into_iter();
        let first = snapshot.occurrence(ids.next()?)?.parent()?;
        ids.all(|id| {
            snapshot
                .occurrence(id)
                .is_some_and(|occurrence| occurrence.parent() == Some(first))
        })
        .then_some(first)
    }

    fn make_unique_source_plan(&self) -> Option<MakeUniqueSourcePlan> {
        let occurrence_paths = self.selected_instance_paths();
        let source_path = (occurrence_paths.len() == 1)
            .then(|| occurrence_paths.first().expect("one occurrence exists"))?;
        source_path.is_root().then_some(())?;
        let occurrence_id = source_path.root_occurrence();
        let snapshot = self.document.current();
        let source_definition_id = snapshot.occurrence(occurrence_id)?.definition_id();
        let source = snapshot.definition(source_definition_id)?;
        let source_definition_name = source.name().to_owned();
        let visible_peer_ids = self
            .active_scene_query()
            .into_iter()
            .filter(|item| item.definition_id == source_definition_id)
            .filter_map(|item| {
                item.instance_path
                    .is_root()
                    .then(|| item.instance_path.root_occurrence())
            })
            .collect::<BTreeSet<_>>();
        let visible_peer_count = visible_peer_ids.len();
        (visible_peer_count > 1 && visible_peer_ids.contains(&occurrence_id)).then_some(())?;
        let new_definition_id = DefinitionId(
            snapshot
                .definitions()
                .map(|definition| definition.id().0)
                .max()
                .unwrap_or(0)
                .checked_add(1)?,
        );
        let first_feature_id = snapshot
            .features()
            .map(|feature| feature.id().0)
            .max()
            .unwrap_or(0)
            .checked_add(1)?;
        let feature_id_map = source
            .feature_ids()
            .iter()
            .enumerate()
            .map(|(offset, source_id)| {
                first_feature_id
                    .checked_add(offset as u64)
                    .map(|new_id| (*source_id, FeatureId(new_id)))
            })
            .collect::<Option<Vec<_>>>()?;
        let new_definition_name = self.catalog.format(
            "model-unique-name",
            &BTreeMap::from([("name", source_definition_name.clone())]),
        );
        Some(MakeUniqueSourcePlan {
            source_revision: snapshot.revision_id(),
            occurrence_paths,
            occurrence_id,
            source_primary: self.selection.primary.clone(),
            source_selected_group: self.selection.selected_group,
            edit_context: self.selection.edit_context.clone(),
            source_definition_id,
            source_definition_name,
            visible_peer_ids,
            visible_peer_count,
            command: CloneDefinitionPlan::new(
                occurrence_id,
                source_definition_id,
                new_definition_id,
                new_definition_name,
                feature_id_map,
            ),
        })
    }

    fn through_cut_target(&self) -> Option<(SelectionId, RenderBox, Vec3)> {
        let selection = self.selection.primary.clone()?;
        if selection.element
            != (ElementId::Face {
                axis: Axis::Z,
                side: Side::Maximum,
            })
        {
            return None;
        }
        let item = self
            .active_boxes()
            .into_iter()
            .find(|item| item.instance_path == selection.instance_path)?;
        item.extrusion_feature_id?;
        let snapshot = self.document.current();
        ExactFeatureChainRequest::from_snapshot(&snapshot, selection.definition_id).ok()?;
        let resolved = snapshot
            .resolve_instance_path(&selection.instance_path)
            .ok()?;
        if resolved.definition_id != selection.definition_id {
            return None;
        }
        let matrix = resolved.world_transform.matrix();
        if matrix[0] != 1.0
            || matrix[1] != 0.0
            || matrix[2] != 0.0
            || matrix[4] != 0.0
            || matrix[5] != 1.0
            || matrix[6] != 0.0
            || matrix[8] != 0.0
            || matrix[9] != 0.0
            || matrix[10] != 1.0
        {
            return None;
        }
        let definition = snapshot.definition(selection.definition_id)?;
        if definition.feature_ids().iter().any(|id| {
            snapshot.feature(*id).is_some_and(|feature| {
                matches!(
                    feature.kind(),
                    FeatureKind::ThroughCut { .. }
                        | FeatureKind::Pocket { .. }
                        | FeatureKind::Boolean { .. }
                )
            })
        }) {
            return None;
        }
        Some((selection, item, Vec3::new(matrix[3], matrix[7], matrix[11])))
    }

    fn selected_revolve_profile(&self) -> Option<RevolveToolState> {
        let selection = self.selection.primary.as_ref()?;
        let item = self
            .active_boxes()
            .into_iter()
            .find(|item| item.instance_path == selection.instance_path)?;
        if item.extrusion_feature_id.is_some() || !item.instance_path.is_root() {
            return None;
        }
        let snapshot = self.document.current();
        let profile = snapshot.feature(item.profile_feature_id)?;
        let is_closed = match profile.kind() {
            FeatureKind::Profile { points_mm } => points_mm.len() >= 3,
            FeatureKind::SegmentProfile { closed, .. } => *closed,
            _ => false,
        };
        if !is_closed || profile.definition_id() != selection.definition_id {
            return None;
        }
        let resolved = snapshot.resolve_instance_path(&item.instance_path).ok()?;
        let world_transform = resolved.world_transform;
        let matrix = world_transform.matrix();
        if matrix[0] != 1.0
            || matrix[1] != 0.0
            || matrix[2] != 0.0
            || matrix[4] != 0.0
            || matrix[5] != 1.0
            || matrix[6] != 0.0
            || matrix[8] != 0.0
            || matrix[9] != 0.0
            || matrix[10] != 1.0
        {
            return None;
        }
        let translation_mm = Vec3::new(matrix[3], matrix[7], matrix[11]);
        Some(RevolveToolState {
            source: RevolveSourcePlan {
                source_document_id: snapshot.document_id(),
                source_revision: snapshot.revision_id(),
                source_digest: snapshot.canonical_digest(),
                source_primary: self.selection.primary.clone(),
                source_selected_group: self.selection.selected_group,
                edit_context: self.selection.edit_context.clone(),
                definition_id: selection.definition_id,
                profile_feature_id: item.profile_feature_id,
                profile_kind: profile.kind().clone(),
                world_transform,
                translation_mm,
                plane_z: translation_mm.z,
            },
            axis_start_mm: None,
            axis_end_mm: None,
        })
    }

    fn begin_revolve_tool(&mut self) -> bool {
        let Some(tool) = self.selected_revolve_profile() else {
            return false;
        };
        self.revolve_tool = Some(tool);
        self.revolve_preview = None;
        self.value_input = "360".to_owned();
        self.status_key = "status-revolve-axis-start";
        true
    }

    fn add_revolve_axis_point(&mut self, point_mm: Vec3) -> bool {
        let Some(mut tool) = self.revolve_tool.clone() else {
            return false;
        };
        let snapshot = self.document.current();
        if snapshot.document_id() != tool.source.source_document_id
            || snapshot.revision_id() != tool.source.source_revision
            || snapshot.canonical_digest() != tool.source.source_digest
        {
            self.revolve_tool = None;
            self.revolve_preview = None;
            self.status_key = "error-preview-stale";
            return false;
        }
        let local = [
            point_mm.x - tool.source.translation_mm.x,
            point_mm.y - tool.source.translation_mm.y,
        ];
        if let Some(start) = tool.axis_start_mm {
            if (local[0] - start[0]).hypot(local[1] - start[1]) <= 0.01 {
                return false;
            }
            tool.axis_end_mm = Some(local);
            self.status_key = "status-revolve-angle";
        } else {
            tool.axis_start_mm = Some(local);
            self.status_key = "status-revolve-axis-end";
        }
        self.revolve_tool = Some(tool);
        self.refresh_revolve_preview()
    }

    fn derive_revolve_preview_plan(
        &self,
        source: &RevolveSourcePlan,
        axis_start_mm: [f64; 2],
        axis_end_mm: [f64; 2],
        angle_degrees: f64,
    ) -> Option<(RevolvePreviewPlan, CommandBatch)> {
        if angle_degrees <= 0.0 || angle_degrees > 360.0 {
            return None;
        }
        let current = self.selected_revolve_profile()?;
        if &current.source != source {
            return None;
        }
        let snapshot = self.document.current();
        let generated_feature_id = snapshot
            .features()
            .map(|feature| feature.id().0)
            .max()
            .unwrap_or(0)
            .checked_add(1)
            .map(FeatureId)?;
        let command = CanonicalCommand::CreateFeature {
            id: generated_feature_id,
            definition_id: source.definition_id,
            name: self.catalog.text("model-revolve-feature"),
            kind: FeatureKind::Revolve {
                profile: source.profile_feature_id,
                axis_start_mm,
                axis_end_mm,
                angle_degrees,
            },
        };
        let batch = CommandBatch::new(vec![command.clone()]);
        let preview_snapshot = self.document.preview_batch(&batch).ok()?;
        let exact_request =
            ExactRevolveRequest::from_snapshot(&preview_snapshot, source.definition_id).ok()?;
        Some((
            RevolvePreviewPlan {
                source: source.clone(),
                generated_feature_id,
                axis_start_mm,
                axis_end_mm,
                angle_degrees_bits: angle_degrees.to_bits(),
                command,
                exact_request,
            },
            batch,
        ))
    }

    fn refresh_revolve_preview(&mut self) -> bool {
        self.revolve_preview = None;
        let Some(tool) = self.revolve_tool.as_ref() else {
            return false;
        };
        let Some(axis_start_mm) = tool.axis_start_mm else {
            return false;
        };
        let Some(axis_end_mm) = tool.axis_end_mm else {
            return false;
        };
        let Some(angle_degrees) =
            parse_distance_mm(&self.value_input).filter(|angle| *angle > 0.0 && *angle <= 360.0)
        else {
            self.digest = self.catalog.text("digest-revolve-invalid-angle");
            return false;
        };
        let Some((plan, batch)) = self.derive_revolve_preview_plan(
            &tool.source,
            axis_start_mm,
            axis_end_mm,
            angle_degrees,
        ) else {
            self.status_key = "error-preview-stale";
            return false;
        };
        self.revolve_preview = Some(RevolvePreview { plan, batch });
        self.status_key = "status-revolve-preview";
        self.digest = self.catalog.format(
            "digest-revolve-live",
            &BTreeMap::from([("angle", format_height(angle_degrees))]),
        );
        true
    }

    #[must_use]
    pub fn has_revolve_preview(&self) -> bool {
        let Some(preview) = self.revolve_preview.as_ref() else {
            return false;
        };
        let Some(tool) = self.revolve_tool.as_ref() else {
            return false;
        };
        let angle_degrees = f64::from_bits(preview.plan.angle_degrees_bits);
        tool.source == preview.plan.source
            && tool.axis_start_mm == Some(preview.plan.axis_start_mm)
            && tool.axis_end_mm == Some(preview.plan.axis_end_mm)
            && parse_distance_mm(&self.value_input).map(f64::to_bits)
                == Some(preview.plan.angle_degrees_bits)
            && self
                .derive_revolve_preview_plan(
                    &preview.plan.source,
                    preview.plan.axis_start_mm,
                    preview.plan.axis_end_mm,
                    angle_degrees,
                )
                .is_some_and(|(plan, batch)| plan == preview.plan && batch == preview.batch)
    }

    #[must_use]
    pub fn revolve_preview_parameters(&self) -> Option<([f64; 2], [f64; 2], f64)> {
        self.has_revolve_preview().then(|| {
            let preview = self
                .revolve_preview
                .as_ref()
                .expect("a current Revolve preview exists");
            (
                preview.plan.axis_start_mm,
                preview.plan.axis_end_mm,
                f64::from_bits(preview.plan.angle_degrees_bits),
            )
        })
    }

    #[must_use]
    pub fn latest_revolve_parameters(&self) -> Option<(FeatureId, [f64; 2], [f64; 2], f64)> {
        self.document
            .current()
            .features()
            .filter_map(|feature| {
                let FeatureKind::Revolve {
                    axis_start_mm,
                    axis_end_mm,
                    angle_degrees,
                    ..
                } = feature.kind()
                else {
                    return None;
                };
                Some((feature.id(), *axis_start_mm, *axis_end_mm, *angle_degrees))
            })
            .last()
    }

    fn confirm_revolve_preview(&mut self) -> bool {
        if !self.has_revolve_preview() {
            self.revolve_preview = None;
            self.status_key = "error-preview-stale";
            return false;
        }
        let Some(preview) = self.revolve_preview.take() else {
            return false;
        };
        if self.document.apply_batch(&preview.batch).is_err() {
            self.status_key = "error-preview-stale";
            return false;
        }
        self.clear_ephemeral_edit_state();
        self.value_input.clear();
        self.status_key = "status-ready";
        self.digest = self.catalog.format(
            "digest-revolve-committed",
            &BTreeMap::from([(
                "angle",
                format_height(f64::from_bits(preview.plan.angle_degrees_bits)),
            )]),
        );
        true
    }

    fn planar_offset_source_plan(&self) -> Option<PlanarOffsetSourcePlan> {
        let selection = self.selection.primary.as_ref()?;
        if selection.element
            != (ElementId::Face {
                axis: Axis::Z,
                side: Side::Maximum,
            })
            || !selection.instance_path.is_root()
        {
            return None;
        }
        let item = self
            .active_boxes()
            .into_iter()
            .find(|item| item.instance_path == selection.instance_path)?;
        if item.extrusion_feature_id.is_some() {
            return None;
        }
        let snapshot = self.document.current();
        let definition = snapshot.definition(selection.definition_id)?;
        if definition.feature_ids() != [item.profile_feature_id] {
            return None;
        }
        let profile = snapshot.feature(item.profile_feature_id)?;
        let FeatureKind::Profile { points_mm } = profile.kind() else {
            return None;
        };
        let [south_west, south_east, north_east, north_west] = points_mm.as_slice() else {
            return None;
        };
        if !(south_west[1] == south_east[1]
            && south_east[0] == north_east[0]
            && north_east[1] == north_west[1]
            && north_west[0] == south_west[0]
            && south_east[0] > south_west[0]
            && north_west[1] > south_west[1])
        {
            return None;
        }
        let world_transform = snapshot
            .resolve_instance_path(&selection.instance_path)
            .ok()?
            .world_transform;
        Some(PlanarOffsetSourcePlan {
            source_document_id: snapshot.document_id(),
            source_revision: snapshot.revision_id(),
            source_digest: snapshot.canonical_digest(),
            source_primary: self.selection.primary.clone(),
            source_selected_group: self.selection.selected_group,
            edit_context: self.selection.edit_context.clone(),
            definition_id: selection.definition_id,
            profile_feature_id: item.profile_feature_id,
            profile_kind: profile.kind().clone(),
            world_transform,
        })
    }

    fn selected_planar_offset_profile(&self) -> Option<(DefinitionId, FeatureId)> {
        self.planar_offset_source_plan()
            .map(|source| (source.definition_id, source.profile_feature_id))
    }

    fn derive_planar_offset_preview_plan(
        &self,
        source: &PlanarOffsetSourcePlan,
        distance_expression: &str,
        distance_mm: f64,
    ) -> Option<(PlanarOffsetPreviewPlan, CommandBatch)> {
        if distance_mm.abs() <= 1.0e-6 || self.planar_offset_source_plan().as_ref() != Some(source)
        {
            return None;
        }
        let distance = Dimension::new(distance_expression.to_owned(), distance_mm).ok()?;
        let snapshot = self.document.current();
        let generated_feature_id = snapshot
            .features()
            .map(|feature| feature.id().0)
            .max()
            .unwrap_or(0)
            .checked_add(1)
            .map(FeatureId)?;
        let command = CanonicalCommand::CreateFeature {
            id: generated_feature_id,
            definition_id: source.definition_id,
            name: self.catalog.text("model-planar-offset-feature"),
            kind: FeatureKind::PlanarOffset {
                profile: source.profile_feature_id,
                distance,
            },
        };
        let batch = CommandBatch::new(vec![command.clone()]);
        let preview_snapshot = self.document.preview_batch(&batch).ok()?;
        let exact_request =
            ExactPlanarOffsetRequest::from_snapshot(&preview_snapshot, source.definition_id)
                .ok()?;
        Some((
            PlanarOffsetPreviewPlan {
                source: source.clone(),
                generated_feature_id,
                distance_expression: distance_expression.to_owned(),
                distance_mm_bits: distance_mm.to_bits(),
                command,
                exact_request,
            },
            batch,
        ))
    }

    fn refresh_planar_offset_preview(&mut self) -> bool {
        self.planar_offset_preview = None;
        let Some(source) = self.planar_offset_source_plan() else {
            return false;
        };
        let Some(distance_mm) =
            parse_distance_mm(&self.value_input).filter(|distance| distance.abs() > 1.0e-6)
        else {
            self.digest = self.catalog.text("digest-planar-offset-invalid-distance");
            return false;
        };
        let Some((plan, batch)) =
            self.derive_planar_offset_preview_plan(&source, &self.value_input, distance_mm)
        else {
            self.digest = self.catalog.text("digest-planar-offset-invalid-distance");
            return false;
        };
        self.planar_offset_preview = Some(PlanarOffsetPreview { plan, batch });
        self.status_key = "status-planar-offset-preview";
        self.digest = self.catalog.format(
            "digest-planar-offset-live",
            &BTreeMap::from([("distance", format_height(distance_mm))]),
        );
        true
    }

    #[must_use]
    pub fn planar_offset_preview_parameters(&self) -> Option<(FeatureId, f64, [[f64; 3]; 2])> {
        let preview = self.planar_offset_preview.as_ref()?;
        self.planar_offset_preview_is_current().then_some((
            preview.plan.source.profile_feature_id,
            f64::from_bits(preview.plan.distance_mm_bits),
            preview.plan.exact_request.expected_bounds_mm(),
        ))
    }

    #[must_use]
    pub fn planar_offset_preview_exact_evaluator(&self) -> Option<&'static str> {
        let preview = self.planar_offset_preview.as_ref()?;
        self.planar_offset_preview_is_current()
            .then(|| preview.plan.exact_request.evaluator())
    }

    #[must_use]
    pub fn planar_offset_preview_is_current(&self) -> bool {
        let Some(preview) = self.planar_offset_preview.as_ref() else {
            return false;
        };
        self.value_input == preview.plan.distance_expression
            && parse_distance_mm(&self.value_input).map(f64::to_bits)
                == Some(preview.plan.distance_mm_bits)
            && self
                .derive_planar_offset_preview_plan(
                    &preview.plan.source,
                    &preview.plan.distance_expression,
                    f64::from_bits(preview.plan.distance_mm_bits),
                )
                .is_some_and(|(plan, batch)| plan == preview.plan && batch == preview.batch)
    }

    #[must_use]
    pub fn latest_planar_offset_parameters(&self) -> Option<(FeatureId, FeatureId, f64)> {
        self.document
            .current()
            .features()
            .filter_map(|feature| {
                let FeatureKind::PlanarOffset { profile, distance } = feature.kind() else {
                    return None;
                };
                Some((feature.id(), *profile, distance.millimetres()))
            })
            .last()
    }

    fn confirm_planar_offset_preview(&mut self) -> bool {
        if !self.planar_offset_preview_is_current() {
            self.planar_offset_preview = None;
            self.status_key = "error-preview-stale";
            return false;
        }
        let Some(preview) = self.planar_offset_preview.take() else {
            return false;
        };
        if self.document.apply_batch(&preview.batch).is_err() {
            self.status_key = "error-preview-stale";
            return false;
        }
        self.clear_ephemeral_edit_state();
        self.active_tool = ActiveTool::Select;
        self.value_input.clear();
        self.status_key = "status-ready";
        self.digest = self.catalog.format(
            "digest-planar-offset-committed",
            &BTreeMap::from([(
                "distance",
                format_height(f64::from_bits(preview.plan.distance_mm_bits)),
            )]),
        );
        true
    }

    fn sweep_source_plan(&self) -> Option<SweepSourcePlan> {
        let selection = self.selection.primary.as_ref()?;
        if selection.element
            != (ElementId::Face {
                axis: Axis::Z,
                side: Side::Maximum,
            })
            || !selection.instance_path.is_root()
        {
            return None;
        }
        let snapshot = self.document.current();
        let definition = snapshot.definition(selection.definition_id)?;
        let [profile_feature_id, path_feature_id] = definition.feature_ids() else {
            return None;
        };
        let profile = snapshot.feature(*profile_feature_id)?;
        let path = snapshot.feature(*path_feature_id)?;
        let world_transform = snapshot
            .resolve_instance_path(&selection.instance_path)
            .ok()?
            .world_transform;
        Some(SweepSourcePlan {
            source_document_id: snapshot.document_id(),
            source_revision: snapshot.revision_id(),
            source_digest: snapshot.canonical_digest(),
            source_primary: self.selection.primary.clone(),
            source_selected_group: self.selection.selected_group,
            edit_context: self.selection.edit_context.clone(),
            definition_id: selection.definition_id,
            profile_feature_id: *profile_feature_id,
            profile_kind: profile.kind().clone(),
            path_feature_id: *path_feature_id,
            path_kind: path.kind().clone(),
            world_transform,
        })
    }

