    fn tag_assignment_source_plan(&self) -> Option<TagAssignmentSourcePlan> {
        let occurrence_paths = self.selected_instance_paths();
        let occurrence_count = occurrence_paths.len();
        let occurrence_ids = self.selected_occurrence_ids();
        (occurrence_count > 0 && occurrence_count == occurrence_ids.len()).then_some(())?;
        let snapshot = self.document.current();
        let source_tags = occurrence_ids
            .iter()
            .copied()
            .map(|id| Some((id, snapshot.occurrence(id)?.tag())))
            .collect::<Option<BTreeMap<_, _>>>()?;
        let available_tags = self.tag_options().into_iter().collect::<BTreeMap<_, _>>();
        (!available_tags.is_empty()).then_some(())?;
        let initial_tag = source_tags
            .values()
            .next()
            .copied()
            .filter(|first| source_tags.values().all(|candidate| candidate == first))
            .flatten();
        Some(TagAssignmentSourcePlan {
            source_revision: snapshot.revision_id(),
            source_digest: snapshot.canonical_digest(),
            occurrence_paths,
            occurrence_count,
            source_primary: self.selection.primary.clone(),
            source_selected_group: self.selection.selected_group,
            edit_context: self.selection.edit_context.clone(),
            source_tags,
            available_tags,
            initial_tag,
        })
    }

    fn dialog_tag_assignment_plan(
        &self,
        pending: &PendingTagAssignment,
    ) -> Option<TagAssignmentPlan> {
        let source = self.tag_assignment_source_plan()?;
        (source == pending.source && source.occurrence_count == source.occurrence_paths.len())
            .then_some(())?;
        let target_tag_name = match pending.target_tag {
            Some(id) => source.available_tags.get(&id)?.clone(),
            None => self.catalog.text("dialog-assign-tag-untagged"),
        };
        let changed_occurrence_ids = source
            .source_tags
            .iter()
            .filter_map(|(id, tag)| (*tag != pending.target_tag).then_some(*id))
            .collect::<BTreeSet<_>>();
        let commands = changed_occurrence_ids
            .iter()
            .copied()
            .map(|id| CanonicalCommand::SetOccurrenceTag {
                id,
                tag: pending.target_tag,
            })
            .collect::<Vec<_>>();
        (!commands.is_empty()).then_some(TagAssignmentPlan {
            source,
            target_tag: pending.target_tag,
            target_tag_name,
            changed_occurrence_ids,
            commands,
        })
    }

    fn begin_tag_assignment(&mut self) {
        let Some(source) = self.tag_assignment_source_plan() else {
            return;
        };
        let target_tag = source.initial_tag;
        self.pending_tag_assignment = Some(PendingTagAssignment { source, target_tag });
    }

    #[must_use]
    pub fn tag_assignment_visible(&self) -> bool {
        self.pending_tag_assignment.is_some()
    }

    #[must_use]
    pub fn tag_assignment_input(&self) -> Option<Option<TagId>> {
        self.pending_tag_assignment
            .as_ref()
            .map(|pending| pending.target_tag)
    }

    #[must_use]
    pub fn occurrence_tag(&self, occurrence_id: OccurrenceId) -> Option<TagId> {
        self.document
            .current()
            .occurrence(occurrence_id)
            .and_then(|occurrence| occurrence.tag())
    }

    fn apply_tag_assignment_plan(&mut self, plan: TagAssignmentPlan) -> bool {
        let pending = PendingTagAssignment {
            source: plan.source.clone(),
            target_tag: plan.target_tag,
        };
        if plan.changed_occurrence_ids.len() != plan.commands.len()
            || self.dialog_tag_assignment_plan(&pending).as_ref() != Some(&plan)
        {
            return false;
        }
        let count = plan.commands.len();
        if self
            .document
            .apply_batch(&CommandBatch::new(plan.commands))
            .is_err()
        {
            return false;
        }
        self.pending_tag_assignment = None;
        self.digest = self.catalog.format(
            "digest-assigned-tag",
            &BTreeMap::from([("count", count.to_string()), ("tag", plan.target_tag_name)]),
        );
        true
    }

    pub fn confirm_tag_assignment(&mut self) -> bool {
        let Some(pending) = self.pending_tag_assignment.clone() else {
            return false;
        };
        let Some(plan) = self.dialog_tag_assignment_plan(&pending) else {
            return false;
        };
        self.apply_tag_assignment_plan(plan)
    }

    fn definition_rename_source_plan(&self) -> Option<DefinitionRenameSourcePlan> {
        let instance_paths = self.selected_instance_paths();
        let instance_count = instance_paths.len();
        (instance_count > 0).then_some(())?;
        let definition_id = self.selected_definition_id()?;
        let snapshot = self.document.current();
        let original_name = snapshot.definition(definition_id)?.name().to_owned();
        Some(DefinitionRenameSourcePlan {
            source_revision: snapshot.revision_id(),
            source_digest: snapshot.canonical_digest(),
            instance_paths,
            instance_count,
            source_primary: self.selection.primary.clone(),
            source_selected_group: self.selection.selected_group,
            edit_context: self.selection.edit_context.clone(),
            definition_id,
            original_name,
        })
    }

    fn definition_rename_plan(
        &self,
        pending: &PendingDefinitionRename,
    ) -> Option<DefinitionRenamePlan> {
        let source = self.definition_rename_source_plan()?;
        (source == pending.source && source.instance_count == source.instance_paths.len())
            .then_some(())?;
        let target_name = pending.name.trim();
        (!target_name.is_empty() && target_name != source.original_name).then_some(())?;
        Some(DefinitionRenamePlan {
            command: CanonicalCommand::RenameDefinition {
                id: source.definition_id,
                name: target_name.to_owned(),
            },
            source,
            target_name: target_name.to_owned(),
        })
    }

    fn begin_definition_rename(&mut self) {
        let Some(source) = self.definition_rename_source_plan() else {
            return;
        };
        self.pending_definition_rename = Some(PendingDefinitionRename {
            name: source.original_name.clone(),
            source,
        });
    }

    fn apply_definition_rename_plan(&mut self, plan: DefinitionRenamePlan) -> bool {
        let pending = PendingDefinitionRename {
            source: plan.source.clone(),
            name: plan.target_name.clone(),
        };
        if self.definition_rename_plan(&pending).as_ref() != Some(&plan)
            || self
                .document
                .apply_batch(&CommandBatch::new(vec![plan.command]))
                .is_err()
        {
            return false;
        }
        self.pending_definition_rename = None;
        self.digest = self.catalog.format(
            "digest-renamed-definition",
            &BTreeMap::from([("name", plan.target_name)]),
        );
        true
    }

    pub fn confirm_definition_rename(&mut self) -> bool {
        let Some(pending) = self.pending_definition_rename.clone() else {
            return false;
        };
        let Some(plan) = self.definition_rename_plan(&pending) else {
            return false;
        };
        self.apply_definition_rename_plan(plan)
    }

    fn purgeable_definition_ids(&self) -> BTreeSet<DefinitionId> {
        let snapshot = self.document.current();
        let referenced = snapshot
            .occurrences()
            .map(|occurrence| occurrence.definition_id())
            .chain(
                snapshot
                    .local_occurrences()
                    .map(|occurrence| occurrence.definition_id()),
            )
            .collect::<BTreeSet<_>>();
        snapshot
            .definitions()
            .filter(|definition| {
                !referenced.contains(&definition.id())
                    && definition.local_occurrence_ids().is_empty()
                    && definition.local_group_ids().is_empty()
            })
            .map(|definition| definition.id())
            .collect()
    }

    fn purge_unused_source_plan(&self) -> Option<PurgeUnusedSourcePlan> {
        let definition_ids = self.purgeable_definition_ids();
        let definition_count = definition_ids.len();
        (definition_count > 0).then_some(PurgeUnusedSourcePlan {
            definition_ids,
            definition_count,
        })
    }

    #[must_use]
    pub fn rename_definition_visible(&self) -> bool {
        self.pending_definition_rename.is_some()
    }

    #[must_use]
    pub fn rename_definition_input(&self) -> Option<&str> {
        self.pending_definition_rename
            .as_ref()
            .map(|pending| pending.name.as_str())
    }

    #[must_use]
    pub fn definition_name(&self, definition_id: DefinitionId) -> Option<String> {
        self.document
            .current()
            .definition(definition_id)
            .map(|definition| definition.name().to_owned())
    }

    /// Number of definitions the Model menu can safely purge right now.
    #[must_use]
    pub fn purgeable_definition_count(&self) -> usize {
        self.purge_unused_source_plan()
            .map_or(0, |plan| plan.definition_count)
    }

    fn apply_purge_unused_source_plan(&mut self, plan: PurgeUnusedSourcePlan) -> bool {
        if plan.definition_count != plan.definition_ids.len()
            || self.purge_unused_source_plan().as_ref() != Some(&plan)
            || self
                .document
                .apply_batch(&CommandBatch::new(
                    plan.definition_ids
                        .into_iter()
                        .map(|id| CanonicalCommand::DeleteDefinition { id })
                        .collect(),
                ))
                .is_err()
        {
            return false;
        }
        self.digest = self.catalog.format(
            "digest-purged-unused",
            &BTreeMap::from([("count", plan.definition_count.to_string())]),
        );
        true
    }

    /// Remove every unreferenced leaf definition as one canonical undo step.
    pub fn purge_unused_definitions(&mut self) -> bool {
        let Some(plan) = self.purge_unused_source_plan() else {
            return false;
        };
        self.apply_purge_unused_source_plan(plan)
    }

    fn grounded_occurrence_source_plan(
        &self,
        target_grounded: bool,
    ) -> Option<GroundedOccurrenceSourcePlan> {
        if self.selection.selected_group.is_some() || !self.selection.edit_context.is_empty() {
            return None;
        }
        let occurrence_paths = self.selected_instance_paths();
        let occurrence_count = occurrence_paths.len();
        let occurrence_path = (occurrence_count == 1)
            .then(|| occurrence_paths.first().expect("one occurrence exists"))?;
        if !occurrence_path.is_root() {
            return None;
        }
        let occurrence_id = occurrence_path.root_occurrence();
        let snapshot = self.document.current();
        snapshot.occurrence(occurrence_id)?;
        let source_grounded = snapshot.occurrence_is_grounded(occurrence_id);
        (source_grounded != target_grounded).then_some(GroundedOccurrenceSourcePlan {
            source_revision: snapshot.revision_id(),
            source_digest: snapshot.canonical_digest(),
            occurrence_paths,
            occurrence_count,
            source_primary: self.selection.primary.clone(),
            source_selected_group: self.selection.selected_group,
            edit_context: self.selection.edit_context.clone(),
            occurrence_id,
            source_grounded,
            target_grounded,
            command: CanonicalCommand::SetOccurrenceGrounded {
                id: occurrence_id,
                grounded: target_grounded,
            },
        })
    }

    fn apply_grounded_occurrence_source_plan(
        &mut self,
        plan: GroundedOccurrenceSourcePlan,
    ) -> bool {
        if plan.source_revision != self.document.current().revision_id()
            || plan.source_digest != self.document.current().canonical_digest()
            || plan.occurrence_count != plan.occurrence_paths.len()
            || self
                .grounded_occurrence_source_plan(plan.target_grounded)
                .as_ref()
                != Some(&plan)
            || self
                .document
                .apply_batch(&CommandBatch::new(vec![plan.command]))
                .is_err()
        {
            return false;
        }
        self.digest = self.catalog.text(if plan.target_grounded {
            "digest-grounded-occurrence"
        } else {
            "digest-ungrounded-occurrence"
        });
        true
    }

    /// Ground or unground the one selected root occurrence as one undo step.
    pub fn set_selected_occurrence_grounded(&mut self, grounded: bool) -> bool {
        let Some(plan) = self.grounded_occurrence_source_plan(grounded) else {
            return false;
        };
        self.apply_grounded_occurrence_source_plan(plan)
    }

    fn selection_visibility_source_plan(
        &self,
        target_visible: bool,
    ) -> Option<SelectionVisibilitySourcePlan> {
        let occurrence_paths = self.selected_instance_paths();
        let occurrence_count = occurrence_paths.len();
        let occurrence_ids = self.selected_occurrence_ids();
        if occurrence_count == 0 || occurrence_ids.len() != occurrence_count {
            return None;
        }
        let snapshot = self.document.current();
        let source_visibility = occurrence_ids
            .iter()
            .map(|id| Some((*id, snapshot.occurrence(*id)?.visible())))
            .collect::<Option<BTreeMap<_, _>>>()?;
        let changed_occurrence_ids = source_visibility
            .iter()
            .filter_map(|(id, visible)| (*visible != target_visible).then_some(*id))
            .collect::<BTreeSet<_>>();
        let commands = changed_occurrence_ids
            .iter()
            .map(|id| CanonicalCommand::SetOccurrenceVisibility {
                id: *id,
                visible: target_visible,
            })
            .collect::<Vec<_>>();
        (!changed_occurrence_ids.is_empty()).then_some(SelectionVisibilitySourcePlan {
            source_revision: snapshot.revision_id(),
            source_digest: snapshot.canonical_digest(),
            occurrence_paths,
            occurrence_count,
            source_primary: self.selection.primary.clone(),
            source_selected_group: self.selection.selected_group,
            edit_context: self.selection.edit_context.clone(),
            source_visibility,
            changed_occurrence_ids,
            target_visible,
            commands,
        })
    }

    fn apply_selection_visibility_source_plan(
        &mut self,
        plan: SelectionVisibilitySourcePlan,
    ) -> bool {
        if plan.source_revision != self.document.current().revision_id()
            || plan.source_digest != self.document.current().canonical_digest()
            || plan.occurrence_count != plan.occurrence_paths.len()
            || self
                .selection_visibility_source_plan(plan.target_visible)
                .as_ref()
                != Some(&plan)
        {
            return false;
        }
        let count = plan.changed_occurrence_ids.len();
        if self
            .document
            .apply_batch(&CommandBatch::new(plan.commands))
            .is_err()
        {
            return false;
        }
        self.digest = self.catalog.format(
            if plan.target_visible {
                "digest-unhidden"
            } else {
                "digest-hidden"
            },
            &BTreeMap::from([("count", count.to_string())]),
        );
        true
    }

    /// Commit the visibility of every selected occurrence as one undo step.
    pub fn set_selection_visibility(&mut self, visible: bool) -> bool {
        let Some(plan) = self.selection_visibility_source_plan(visible) else {
            return false;
        };
        self.apply_selection_visibility_source_plan(plan)
    }

    fn hide_others_source_plan(&self) -> Option<HideOthersSourcePlan> {
        self.selection.edit_context.is_empty().then_some(())?;
        let selected_occurrence_ids = self.selected_occurrence_ids();
        let selected_paths = self.selected_instance_paths();
        if selected_occurrence_ids.is_empty()
            || selected_occurrence_ids.len() != selected_paths.len()
            || selected_paths.iter().any(|path| !path.is_root())
        {
            return None;
        }
        let snapshot = self.document.current();
        let hidden_occurrence_ids = snapshot
            .occurrences()
            .filter(|occurrence| {
                occurrence.visible() && !selected_occurrence_ids.contains(&occurrence.id())
            })
            .map(|occurrence| occurrence.id())
            .collect::<BTreeSet<_>>();
        let occurrence_count = hidden_occurrence_ids.len();
        let commands = hidden_occurrence_ids
            .iter()
            .copied()
            .map(|id| CanonicalCommand::SetOccurrenceVisibility { id, visible: false })
            .collect::<Vec<_>>();
        (occurrence_count > 0).then_some(HideOthersSourcePlan {
            source_revision: snapshot.revision_id(),
            source_digest: snapshot.canonical_digest(),
            selected_occurrence_ids,
            edit_context: self.selection.edit_context.clone(),
            hidden_occurrence_ids,
            occurrence_count,
            commands,
        })
    }

    fn apply_hide_others_source_plan(&mut self, plan: HideOthersSourcePlan) -> bool {
        if plan.occurrence_count != plan.hidden_occurrence_ids.len()
            || plan.occurrence_count != plan.commands.len()
            || self.hide_others_source_plan().as_ref() != Some(&plan)
            || self
                .document
                .apply_batch(&CommandBatch::new(plan.commands))
                .is_err()
        {
            return false;
        }
        self.digest = self.catalog.format(
            "digest-hidden-others",
            &BTreeMap::from([("count", plan.occurrence_count.to_string())]),
        );
        true
    }

    /// Hide every visible unselected root occurrence as one canonical undo step.
    pub fn hide_others(&mut self) -> bool {
        let Some(plan) = self.hide_others_source_plan() else {
            return false;
        };
        self.apply_hide_others_source_plan(plan)
    }

    fn unhide_all_source_plan(&self) -> Option<UnhideAllSourcePlan> {
        self.selection.edit_context.is_empty().then_some(())?;
        let snapshot = self.document.current();
        let hidden_occurrence_ids = snapshot
            .occurrences()
            .filter(|occurrence| !occurrence.visible())
            .map(|occurrence| occurrence.id())
            .collect::<BTreeSet<_>>();
        let occurrence_count = hidden_occurrence_ids.len();
        let commands = hidden_occurrence_ids
            .iter()
            .copied()
            .map(|id| CanonicalCommand::SetOccurrenceVisibility { id, visible: true })
            .collect::<Vec<_>>();
        (occurrence_count > 0).then_some(UnhideAllSourcePlan {
            source_revision: snapshot.revision_id(),
            source_digest: snapshot.canonical_digest(),
            edit_context: self.selection.edit_context.clone(),
            hidden_occurrence_ids,
            occurrence_count,
            commands,
        })
    }

    fn apply_unhide_all_source_plan(&mut self, plan: UnhideAllSourcePlan) -> bool {
        if plan.occurrence_count != plan.hidden_occurrence_ids.len()
            || plan.occurrence_count != plan.commands.len()
            || self.unhide_all_source_plan().as_ref() != Some(&plan)
            || self
                .document
                .apply_batch(&CommandBatch::new(plan.commands))
                .is_err()
        {
            return false;
        }
        self.digest = self.catalog.format(
            "digest-unhidden-all",
            &BTreeMap::from([("count", plan.occurrence_count.to_string())]),
        );
        true
    }

    /// Restore every hidden root occurrence as one canonical undo step.
    pub fn unhide_all(&mut self) -> bool {
        let Some(plan) = self.unhide_all_source_plan() else {
            return false;
        };
        self.apply_unhide_all_source_plan(plan)
    }

