    fn create_box_at(&mut self, origin_mm: Vec3, size_mm: Vec3) -> bool {
        if !size_mm.x.is_finite()
            || !size_mm.y.is_finite()
            || !size_mm.z.is_finite()
            || size_mm.x <= 0.01
            || size_mm.y <= 0.01
            || size_mm.z <= 0.01
        {
            return false;
        }
        let snapshot = self.document.current();
        let definition_id = DefinitionId(
            snapshot
                .definitions()
                .map(|definition| definition.id().0)
                .max()
                .unwrap_or(0)
                + 1,
        );
        let first_feature_id = snapshot
            .features()
            .map(|feature| feature.id().0)
            .max()
            .unwrap_or(0)
            + 1;
        let profile_id = FeatureId(first_feature_id);
        let extrusion_id = FeatureId(first_feature_id + 1);
        let occurrence_id = OccurrenceId(
            snapshot
                .occurrences()
                .map(|occurrence| occurrence.id().0)
                .max()
                .unwrap_or(0)
                + 1,
        );
        let name = self.catalog.format(
            "model-default-box",
            &BTreeMap::from([("number", definition_id.0.to_string())]),
        );
        let occurrence_name = self.catalog.format(
            "model-default-occurrence",
            &BTreeMap::from([("name", name.clone())]),
        );
        if self
            .document
            .apply_batch(&create_box_batch(
                definition_id,
                [profile_id, extrusion_id],
                occurrence_id,
                [
                    &name,
                    &self.catalog.text("model-default-profile"),
                    &self.catalog.text("model-default-extrusion"),
                    &occurrence_name,
                ],
                origin_mm,
                size_mm,
            ))
            .is_err()
        {
            return false;
        }
        self.preview = None;
        self.preview_box = None;
        self.preview_definition_id = None;
        self.push_pull_distance_input.clear();
        self.selection.select_exact(
            SelectionId {
                definition_id,
                instance_path: InstancePath::root(occurrence_id),
                element: ElementId::Face {
                    axis: Axis::Z,
                    side: Side::Maximum,
                },
            },
            false,
        );
        self.status_key = "status-box-created";
        true
    }

    pub fn create_box(&mut self) -> bool {
        let offset = self.active_box_count() as f64 * 35.0;
        self.create_box_at(
            Vec3::new(offset, offset, 0.0),
            Vec3::new(BOX_WIDTH_MM, BOX_DEPTH_MM, 20.0),
        )
    }

    fn selected_move_reference(&self) -> Option<SelectionId> {
        if let Some(primary) = &self.selection.primary {
            return Some(primary.clone());
        }
        let instance_path = self.selection.occurrences.iter().next()?.clone();
        let snapshot = self.document.current();
        let occurrence = snapshot.occurrence(instance_path.root_occurrence())?;
        Some(SelectionId {
            definition_id: occurrence.definition_id(),
            instance_path,
            element: ElementId::Face {
                axis: Axis::Z,
                side: Side::Maximum,
            },
        })
    }

    fn translate_group(&mut self, group_id: GroupId, delta_mm: Vec3) -> bool {
        let distance_mm = vector_length(delta_mm);
        if !delta_mm.x.is_finite()
            || !delta_mm.y.is_finite()
            || !delta_mm.z.is_finite()
            || distance_mm <= 0.0
        {
            return false;
        }
        let snapshot = self.document.current();
        let Some(group) = snapshot.group(group_id) else {
            return false;
        };
        let Ok(transform) = translated_transform(group.transform(), delta_mm) else {
            return false;
        };
        if self
            .document
            .apply_batch(&CommandBatch::new(vec![
                CanonicalCommand::SetGroupTransform {
                    id: group_id,
                    transform,
                },
            ]))
            .is_err()
        {
            return false;
        }
        self.select_group(group_id);
        self.last_move = None;
        self.status_key = "status-object-moved";
        self.digest = self.catalog.format(
            "digest-move-committed",
            &BTreeMap::from([("distance", format_height(distance_mm))]),
        );
        true
    }

    fn commit_move_drag(&mut self, drag: &MoveDrag) -> bool {
        if let Some(target) = &drag.profile_target {
            let delta_mm = [
                dot(drag.delta_mm, target.world_x_axis),
                dot(drag.delta_mm, target.world_y_axis),
            ];
            let distance_mm = delta_mm[0].hypot(delta_mm[1]);
            if distance_mm < 0.01 {
                return false;
            }
            let Ok(preview) = ketchup_core::feature_history::prepare_body_profile_translation(
                &self.document,
                ketchup_core::feature_history::BodyProfileTranslationRequest {
                    definition_id: target.definition_id,
                    body_id: target.body_id,
                    profile_id: target.profile_id,
                    delta_mm,
                },
                ProposalPrincipal::ManualClient,
            ) else {
                return false;
            };
            if self.document.commit_proposal(&preview.proposal).is_err() {
                return false;
            }
            self.selection.select_exact(drag.selection.clone(), false);
            self.last_move = None;
            self.status_key = "status-object-moved";
            self.digest = self.catalog.format(
                "digest-move-committed",
                &BTreeMap::from([("distance", format_height(distance_mm))]),
            );
            true
        } else if let Some(group_id) = drag.group_id {
            self.translate_group(group_id, drag.delta_mm)
        } else {
            self.translate_occurrence(&drag.selection, drag.delta_mm, drag.copy)
        }
    }

    fn commit_rotate_drag(&mut self, drag: &RotateDrag) -> bool {
        if let Some(group_id) = drag.group_id {
            self.rotate_group(group_id, drag.centre_mm, drag.axis, drag.angle_degrees)
        } else {
            self.rotate_occurrence(
                &drag.selection,
                drag.centre_mm,
                drag.axis,
                drag.angle_degrees,
                drag.copy,
            )
        }
    }

    fn rotate_group(
        &mut self,
        group_id: GroupId,
        centre_mm: Vec3,
        axis: Axis,
        angle_degrees: f64,
    ) -> bool {
        if !rotation_is_meaningful(angle_degrees) {
            return false;
        }
        let snapshot = self.document.current();
        let Some(group) = snapshot.group(group_id) else {
            return false;
        };
        let Ok(rotation) = world_rotation_transform(centre_mm, axis, angle_degrees) else {
            return false;
        };
        let transform = rotation.compose(group.transform());
        if self
            .document
            .apply_batch(&CommandBatch::new(vec![
                CanonicalCommand::SetGroupTransform {
                    id: group_id,
                    transform,
                },
            ]))
            .is_err()
        {
            return false;
        }
        self.select_group(group_id);
        self.last_move = None;
        self.last_rotate = Some(LastRotate {
            target: RotateTarget::Group(group_id),
            centre_mm,
            axis,
            revision: self.document_revision(),
            canonical_digest: self.canonical_digest(),
        });
        self.status_key = "status-object-rotated";
        self.digest = self.catalog.format(
            "digest-rotate-committed",
            &BTreeMap::from([
                ("angle", format_angle(angle_degrees)),
                ("axis", self.catalog.text(axis_name_key(axis))),
            ]),
        );
        true
    }

    fn rotate_occurrence(
        &mut self,
        selection: &SelectionId,
        centre_mm: Vec3,
        axis: Axis,
        angle_degrees: f64,
        copy: bool,
    ) -> bool {
        if !rotation_is_meaningful(angle_degrees) {
            return false;
        }
        if matches!(
            self.selection.edit_context.last(),
            Some(EditContext::Definition { .. })
        ) || !self.occurrence_in_active_context(&selection.instance_path)
        {
            return false;
        }
        let snapshot = self.document.current();
        if !selection.instance_path.is_root() {
            return false;
        }
        let source_id = selection.instance_path.root_occurrence();
        let Some(source) = snapshot.occurrence(source_id) else {
            return false;
        };
        let definition_id = source.definition_id();
        if definition_id != selection.definition_id {
            return false;
        }
        let Ok(rotation) = world_rotation_transform(centre_mm, axis, angle_degrees) else {
            return false;
        };
        let transform = rotation.compose(source.transform());
        let target_id = if copy {
            OccurrenceId(
                snapshot
                    .occurrences()
                    .map(|occurrence| occurrence.id().0)
                    .max()
                    .unwrap_or(0)
                    + 1,
            )
        } else {
            source_id
        };
        let command = if copy {
            let Some(definition) = snapshot.definition(definition_id) else {
                return false;
            };
            let number = snapshot
                .scene_query()
                .into_iter()
                .filter(|item| item.definition_id == definition_id)
                .count()
                + 1;
            CanonicalCommand::CreateOccurrence {
                id: target_id,
                definition_id,
                name: self.catalog.format(
                    "model-copy-occurrence",
                    &BTreeMap::from([
                        ("name", definition.name().to_owned()),
                        ("number", number.to_string()),
                    ]),
                ),
                transform,
                parent: source.parent(),
                tag: source.tag(),
                visible: source.visible(),
            }
        } else {
            CanonicalCommand::SetOccurrenceTransform {
                id: target_id,
                transform,
            }
        };
        if self
            .document
            .apply_batch(&CommandBatch::new(vec![command]))
            .is_err()
        {
            return false;
        }
        self.selection.select_exact(
            SelectionId {
                definition_id,
                instance_path: InstancePath::root(target_id),
                element: selection.element.clone(),
            },
            false,
        );
        self.last_move = None;
        // A rotate-copy has no turn to correct: the typed angle would have to
        // choose between the original and the copy, so it starts a fresh one.
        self.last_rotate = (!copy).then(|| LastRotate {
            target: RotateTarget::Occurrence(target_id),
            centre_mm,
            axis,
            revision: self.document_revision(),
            canonical_digest: self.canonical_digest(),
        });
        self.status_key = "status-object-rotated";
        self.digest = self.catalog.format(
            "digest-rotate-committed",
            &BTreeMap::from([
                ("angle", format_angle(angle_degrees)),
                ("axis", self.catalog.text(axis_name_key(axis))),
            ]),
        );
        true
    }

    /// Turn the current selection by `angle_degrees` about the locked axis.
    ///
    /// This is the same commit the viewport gesture performs, exposed so a
    /// typed angle and the headless shell reach it without synthesising a drag.
    pub fn rotate_selected(&mut self, angle_degrees: f64) -> bool {
        let axis = self.rotate_axis_lock.unwrap_or(Axis::Z);
        if let Some(group_id) = self.selection.selected_group {
            let snapshot = self.document.current();
            let applies = move |path: &InstancePath| {
                Self::group_contains_occurrence(&snapshot, group_id, path.root_occurrence())
            };
            let Some(centre_mm) = self.rotation_centre_for(&applies) else {
                return false;
            };
            return self.rotate_group(group_id, centre_mm, axis, angle_degrees);
        }
        let Some(selection) = self.selected_move_reference() else {
            return false;
        };
        let target = selection.instance_path.clone();
        let applies = move |path: &InstancePath| *path == target;
        let Some(centre_mm) = self.rotation_centre_for(&applies) else {
            return false;
        };
        self.rotate_occurrence(&selection, centre_mm, axis, angle_degrees, false)
    }

    /// Whether the current selection is still the thing `target` turned.
    ///
    /// Without this a typed angle would silently correct the previous body
    /// after the user has already clicked a different one.
    fn selection_matches_rotate_target(&self, target: RotateTarget) -> bool {
        match target {
            RotateTarget::Group(group_id) => self.selection.selected_group == Some(group_id),
            RotateTarget::Occurrence(occurrence_id) => {
                self.selection.selected_group.is_none()
                    && self.selected_move_reference().is_some_and(|selection| {
                        selection.instance_path.is_root()
                            && selection.instance_path.root_occurrence() == occurrence_id
                    })
            }
        }
    }

    /// Re-turn the last rotation to `angle_degrees` instead of adding to it.
    ///
    /// The correction is planned against the guarded parent of the tip, so the
    /// body lands on exactly the angle typed — 45 followed by 40 ends at 40,
    /// not 85 — and the whole thing stays a single undo step. Zero is a
    /// legitimate correction back to where the body started.
    fn correct_last_rotation(&mut self, angle_degrees: f64) -> bool {
        let Some(previous) = self.last_rotate.clone() else {
            return false;
        };
        let current = self.document.current();
        // Picking a different axis means the user wants another turn, not a
        // different value for the one already made.
        if previous.axis != self.rotate_axis_lock.unwrap_or(Axis::Z)
            || previous.revision != current.revision_id()
            || previous.canonical_digest != current.canonical_digest()
            || !self.selection_matches_rotate_target(previous.target)
        {
            return false;
        }
        let Ok(parent) = self.document.tip_replacement_parent() else {
            return false;
        };
        let Ok(rotation) =
            world_rotation_transform(previous.centre_mm, previous.axis, angle_degrees)
        else {
            return false;
        };
        let base = parent.snapshot();
        let command = match previous.target {
            RotateTarget::Group(group_id) => {
                let Some(group) = base.group(group_id) else {
                    return false;
                };
                CanonicalCommand::SetGroupTransform {
                    id: group_id,
                    transform: rotation.compose(group.transform()),
                }
            }
            RotateTarget::Occurrence(occurrence_id) => {
                let Some(occurrence) = base.occurrence(occurrence_id) else {
                    return false;
                };
                CanonicalCommand::SetOccurrenceTransform {
                    id: occurrence_id,
                    transform: rotation.compose(occurrence.transform()),
                }
            }
        };
        let Ok(proposal) = self.document.prepare_tip_replacement_proposal(
            &parent,
            CommandBatch::new(vec![command]),
            ProposalContext::canonical_preview(),
        ) else {
            return false;
        };
        if self
            .document
            .commit_tip_replacement_proposal(&proposal)
            .is_err()
        {
            return false;
        }
        self.last_rotate = Some(LastRotate {
            revision: self.document_revision(),
            canonical_digest: self.canonical_digest(),
            ..previous
        });
        self.status_key = "status-object-rotated";
        self.digest = self.catalog.format(
            "digest-rotate-committed",
            &BTreeMap::from([
                ("angle", format_angle(angle_degrees)),
                ("axis", self.catalog.text(axis_name_key(previous.axis))),
            ]),
        );
        true
    }

    fn translate_occurrence(
        &mut self,
        selection: &SelectionId,
        delta_mm: Vec3,
        copy: bool,
    ) -> bool {
        let distance_mm = vector_length(delta_mm);
        if !delta_mm.x.is_finite()
            || !delta_mm.y.is_finite()
            || !delta_mm.z.is_finite()
            || distance_mm <= 0.0
        {
            return false;
        }
        if matches!(
            self.selection.edit_context.last(),
            Some(EditContext::Definition { .. })
        ) || !self.occurrence_in_active_context(&selection.instance_path)
        {
            return false;
        }
        let snapshot = self.document.current();
        if !selection.instance_path.is_root() {
            return false;
        }
        let source_id = selection.instance_path.root_occurrence();
        let Some(source) = snapshot.occurrence(source_id) else {
            return false;
        };
        let definition_id = source.definition_id();
        if definition_id != selection.definition_id {
            return false;
        }
        let Ok(transform) = translated_transform(source.transform(), delta_mm) else {
            return false;
        };
        let target_id = if copy {
            OccurrenceId(
                snapshot
                    .occurrences()
                    .map(|occurrence| occurrence.id().0)
                    .max()
                    .unwrap_or(0)
                    + 1,
            )
        } else {
            source_id
        };
        let command = if copy {
            let Some(definition) = snapshot.definition(definition_id) else {
                return false;
            };
            let number = snapshot
                .scene_query()
                .into_iter()
                .filter(|item| item.definition_id == definition_id)
                .count()
                + 1;
            CanonicalCommand::CreateOccurrence {
                id: target_id,
                definition_id,
                name: self.catalog.format(
                    "model-copy-occurrence",
                    &BTreeMap::from([
                        ("name", definition.name().to_owned()),
                        ("number", number.to_string()),
                    ]),
                ),
                transform,
                parent: source.parent(),
                tag: source.tag(),
                visible: source.visible(),
            }
        } else {
            CanonicalCommand::SetOccurrenceTransform {
                id: target_id,
                transform,
            }
        };
        if self
            .document
            .apply_batch(&CommandBatch::new(vec![command]))
            .is_err()
        {
            return false;
        }
        let target = SelectionId {
            definition_id,
            instance_path: InstancePath::root(target_id),
            element: selection.element.clone(),
        };
        self.selection.select_exact(target, false);
        self.last_move = Some(LastMove {
            occurrence_id: target_id,
            direction: delta_mm * (1.0 / distance_mm),
            applied_distance_mm: distance_mm,
        });
        self.status_key = if copy {
            "status-object-copied"
        } else {
            "status-object-moved"
        };
        self.digest = self.catalog.format(
            if copy {
                "digest-copy-committed"
            } else {
                "digest-move-committed"
            },
            &BTreeMap::from([("distance", format_height(distance_mm))]),
        );
        true
    }

    pub fn move_selected(&mut self, delta_mm: Vec3) -> bool {
        if let Some(group_id) = self.selection.selected_group {
            return self.translate_group(group_id, delta_mm);
        }
        let Some(selection) = self.selected_move_reference() else {
            return false;
        };
        self.translate_occurrence(&selection, delta_mm, false)
    }

    pub fn copy_selected(&mut self, delta_mm: Vec3) -> bool {
        let Some(selection) = self.selected_move_reference() else {
            return false;
        };
        self.translate_occurrence(&selection, delta_mm, true)
    }

    fn occurrence_alignment_plan(
        &self,
        source: &OccurrenceAlignmentSourcePlan,
        axis: Axis,
        mode: AlignMode,
    ) -> Option<OccurrenceAlignmentPlan> {
        if self
            .occurrence_alignment_source_plan_for_pair(source.moving_id, source.reference_id)
            .as_ref()
            != Some(source)
        {
            return None;
        }
        let moving_coordinate_mm = alignment_coordinate(&source.moving_box, axis, mode);
        let reference_coordinate_mm = alignment_coordinate(&source.reference_box, axis, mode);
        let offset_mm = reference_coordinate_mm - moving_coordinate_mm;
        if !offset_mm.is_finite() || offset_mm.abs() <= f64::EPSILON {
            return None;
        }
        let delta_mm = axis_vector(axis, offset_mm);
        let transform = translated_transform(source.moving_transform, delta_mm).ok()?;
        let command = CanonicalCommand::SetOccurrenceTransform {
            id: source.moving_id,
            transform,
        };
        let mut preview_box = source.moving_box.clone();
        preview_box.origin_mm = preview_box.origin_mm + delta_mm;
        Some(OccurrenceAlignmentPlan {
            source: source.clone(),
            axis,
            mode,
            moving_coordinate_mm,
            reference_coordinate_mm,
            offset_mm,
            command,
            preview_box,
        })
    }

    fn begin_occurrence_align(&mut self) {
        let Some(source) = self.occurrence_alignment_source_plan() else {
            return;
        };
        self.occurrence_operation_preview = None;
        self.pending_occurrence_align = Some(PendingOccurrenceAlign {
            source,
            axis: Axis::X,
            mode: AlignMode::Center,
            preview_plan: None,
        });
    }

    #[must_use]
    pub fn occurrence_align_visible(&self) -> bool {
        self.pending_occurrence_align.is_some()
    }

    #[must_use]
    pub fn occurrence_align_inputs(&self) -> Option<(OccurrenceId, OccurrenceId, Axis, AlignMode)> {
        self.pending_occurrence_align.as_ref().map(|pending| {
            (
                pending.source.moving_id,
                pending.source.reference_id,
                pending.axis,
                pending.mode,
            )
        })
    }

    fn occurrence_alignment_binding_is_current(&self, pending: &PendingOccurrenceAlign) -> bool {
        self.occurrence_alignment_source_plan().as_ref() == Some(&pending.source)
    }

    #[must_use]
    pub fn occurrence_align_preview_is_current(&self) -> bool {
        self.pending_occurrence_align
            .as_ref()
            .is_some_and(|pending| {
                let Some(plan) =
                    self.occurrence_alignment_plan(&pending.source, pending.axis, pending.mode)
                else {
                    return false;
                };
                self.occurrence_alignment_binding_is_current(pending)
                    && pending.preview_plan.as_ref() == Some(&plan)
                    && self
                        .occurrence_operation_preview
                        .as_ref()
                        .is_some_and(|preview| {
                            self.has_occurrence_operation_preview()
                                && preview.source_revision == plan.source.source_revision
                                && preview.batch.commands() == std::slice::from_ref(&plan.command)
                        })
            })
    }

    pub fn preview_pending_occurrence_align(&mut self) -> bool {
        let Some(pending) = self.pending_occurrence_align.clone() else {
            return false;
        };
        let Some(plan) =
            self.occurrence_alignment_plan(&pending.source, pending.axis, pending.mode)
        else {
            return false;
        };
        if let Some(current) = self.pending_occurrence_align.as_mut() {
            current.preview_plan = None;
        }
        if !self.preview_occurrence_alignment_plan(plan.clone()) {
            return false;
        }
        if let Some(current) = self.pending_occurrence_align.as_mut() {
            current.preview_plan = Some(plan);
        }
        true
    }

    pub fn confirm_occurrence_align(&mut self) -> bool {
        let Some(plan) = self
            .pending_occurrence_align
            .as_ref()
            .and_then(|pending| pending.preview_plan.clone())
        else {
            return false;
        };
        if !self.occurrence_align_preview_is_current()
            || self
                .occurrence_alignment_plan(&plan.source, plan.axis, plan.mode)
                .as_ref()
                != Some(&plan)
            || !self.confirm_occurrence_operation_preview()
        {
            return false;
        }
        self.pending_occurrence_align = None;
        true
    }

    pub fn preview_align_occurrences(
        &mut self,
        moving_id: OccurrenceId,
        reference_id: OccurrenceId,
        axis: Axis,
        mode: AlignMode,
    ) -> bool {
        self.occurrence_operation_preview = None;
        let Some(source) = self.occurrence_alignment_source_plan_for_pair(moving_id, reference_id)
        else {
            return false;
        };
        let Some(plan) = self.occurrence_alignment_plan(&source, axis, mode) else {
            return false;
        };
        self.preview_occurrence_alignment_plan(plan)
    }

    fn preview_occurrence_alignment_plan(&mut self, plan: OccurrenceAlignmentPlan) -> bool {
        self.occurrence_operation_preview = None;
        if self
            .occurrence_alignment_plan(&plan.source, plan.axis, plan.mode)
            .as_ref()
            != Some(&plan)
        {
            return false;
        }
        let batch = CommandBatch::new(vec![plan.command.clone()]);
        self.occurrence_operation_preview = Some(OccurrenceOperationPreview {
            source_revision: plan.source.source_revision,
            command_digest: batch.digest(),
            batch,
            boxes: BTreeMap::from([(plan.source.moving_id, plan.preview_box.clone())]),
            hidden_occurrences: BTreeSet::new(),
            selection_after: None,
            committed_digest_key: "digest-align-committed",
            canonical_plan: Some(OccurrenceCanonicalPreviewPlan::Alignment(Box::new(
                plan.clone(),
            ))),
            solid_tool_plan: None,
            smart_through_cut_plan: None,
            smart_profile_pocket_plan: None,
        });
        self.status_key = "status-preview";
        self.digest = self.catalog.format(
            "digest-align-live",
            &BTreeMap::from([
                ("axis", alignment_axis_label(plan.axis).to_owned()),
                ("mode", alignment_mode_label(plan.mode).to_owned()),
            ]),
        );
        true
    }

    fn occurrence_distribution_plan(
        &self,
        source: &OccurrenceDistributionSourcePlan,
        axis: Axis,
        mode: DistributionMode,
    ) -> Option<OccurrenceDistributionPlan> {
        let occurrence_ids = source.occurrences.keys().copied().collect();
        if self
            .occurrence_distribution_source_plan_for_ids(&occurrence_ids)
            .as_ref()
            != Some(source)
        {
            return None;
        }
        let align_mode = match mode {
            DistributionMode::Centers => AlignMode::Center,
            DistributionMode::EqualGaps => AlignMode::Minimum,
        };
        let mut items = source
            .occurrences
            .iter()
            .map(|(id, item)| {
                let coordinate = alignment_coordinate(&item.render_box, axis, align_mode);
                coordinate
                    .is_finite()
                    .then_some((*id, item.clone(), coordinate))
            })
            .collect::<Option<Vec<_>>>()?;
        items.sort_by(|left, right| {
            left.2
                .total_cmp(&right.2)
                .then_with(|| left.0.cmp(&right.0))
        });
        let first = items.first()?.2;
        let (spacing_mm, target_coordinates_mm) = match mode {
            DistributionMode::Centers => {
                let span = items.last()?.2 - first;
                if !span.is_finite() || span.abs() <= f64::EPSILON {
                    return None;
                }
                let spacing = span / (items.len() - 1) as f64;
                (
                    spacing,
                    (0..items.len())
                        .map(|index| first + spacing * index as f64)
                        .collect::<Vec<_>>(),
                )
            }
            DistributionMode::EqualGaps => {
                let last = &items.last()?.1.render_box;
                let span = alignment_coordinate(last, axis, AlignMode::Maximum) - first;
                let occupied = items
                    .iter()
                    .map(|(_, item, _)| {
                        alignment_coordinate(&item.render_box, axis, AlignMode::Maximum)
                            - alignment_coordinate(&item.render_box, axis, AlignMode::Minimum)
                    })
                    .sum::<f64>();
                let free = span - occupied;
                if !free.is_finite() || free < -f64::EPSILON {
                    return None;
                }
                let spacing = free.max(0.0) / (items.len() - 1) as f64;
                let mut target = first;
                let targets = items
                    .iter()
                    .map(|(_, item, _)| {
                        let current = target;
                        target += alignment_coordinate(&item.render_box, axis, AlignMode::Maximum)
                            - alignment_coordinate(&item.render_box, axis, AlignMode::Minimum)
                            + spacing;
                        current
                    })
                    .collect();
                (spacing, targets)
            }
        };
        if !spacing_mm.is_finite() {
            return None;
        }
        let ordered_occurrence_ids = items.iter().map(|(id, _, _)| *id).collect();
        let source_coordinates_mm = items.iter().map(|(_, _, coordinate)| *coordinate).collect();
        let mut commands = Vec::with_capacity(items.len() - 2);
        let mut preview_boxes = BTreeMap::new();
        let item_count = items.len();
        for (index, ((id, item, coordinate), target)) in items
            .into_iter()
            .zip(target_coordinates_mm.iter().copied())
            .enumerate()
        {
            if index == 0 || index + 1 == item_count {
                continue;
            }
            let offset_mm = target - coordinate;
            if offset_mm.abs() <= f64::EPSILON {
                continue;
            }
            let delta_mm = axis_vector(axis, offset_mm);
            let transform = translated_transform(item.transform, delta_mm).ok()?;
            commands.push(CanonicalCommand::SetOccurrenceTransform { id, transform });
            let mut preview_box = item.render_box;
            preview_box.origin_mm = preview_box.origin_mm + delta_mm;
            preview_boxes.insert(id, preview_box);
        }
        (!commands.is_empty()).then_some(OccurrenceDistributionPlan {
            source: source.clone(),
            axis,
            mode,
            ordered_occurrence_ids,
            source_coordinates_mm,
            target_coordinates_mm,
            spacing_mm,
            commands,
            preview_boxes,
        })
    }

    fn begin_occurrence_distribution(&mut self) {
        let Some(source) = self.occurrence_distribution_source_plan() else {
            return;
        };
        self.occurrence_operation_preview = None;
        self.pending_occurrence_distribution = Some(PendingOccurrenceDistribution {
            source,
            axis: Axis::X,
            mode: DistributionMode::Centers,
            preview_plan: None,
        });
    }

    #[must_use]
    pub fn occurrence_distribution_visible(&self) -> bool {
        self.pending_occurrence_distribution.is_some()
    }

    #[must_use]
    pub fn occurrence_distribution_axis(&self) -> Option<Axis> {
        self.pending_occurrence_distribution
            .as_ref()
            .map(|pending| pending.axis)
    }

    #[must_use]
    pub fn occurrence_distribution_mode(&self) -> Option<DistributionMode> {
        self.pending_occurrence_distribution
            .as_ref()
            .map(|pending| pending.mode)
    }

    fn occurrence_distribution_binding_is_current(
        &self,
        pending: &PendingOccurrenceDistribution,
    ) -> bool {
        self.occurrence_distribution_source_plan().as_ref() == Some(&pending.source)
    }

    #[must_use]
    pub fn occurrence_distribution_preview_is_current(&self) -> bool {
        self.pending_occurrence_distribution
            .as_ref()
            .is_some_and(|pending| {
                let Some(plan) =
                    self.occurrence_distribution_plan(&pending.source, pending.axis, pending.mode)
                else {
                    return false;
                };
                self.occurrence_distribution_binding_is_current(pending)
                    && pending.preview_plan.as_ref() == Some(&plan)
                    && self
                        .occurrence_operation_preview
                        .as_ref()
                        .is_some_and(|preview| {
                            self.has_occurrence_operation_preview()
                                && preview.source_revision == plan.source.source_revision
                                && preview.batch.commands() == plan.commands
                                && preview.boxes == plan.preview_boxes
                        })
            })
    }

    pub fn preview_pending_occurrence_distribution(&mut self) -> bool {
        let Some(pending) = self.pending_occurrence_distribution.clone() else {
            return false;
        };
        let Some(plan) =
            self.occurrence_distribution_plan(&pending.source, pending.axis, pending.mode)
        else {
            return false;
        };
        if let Some(current) = self.pending_occurrence_distribution.as_mut() {
            current.preview_plan = None;
        }
        if !self.preview_occurrence_distribution_plan(plan.clone()) {
            return false;
        }
        if let Some(current) = self.pending_occurrence_distribution.as_mut() {
            current.preview_plan = Some(plan);
        }
        true
    }

    pub fn confirm_occurrence_distribution(&mut self) -> bool {
        let Some(plan) = self
            .pending_occurrence_distribution
            .as_ref()
            .and_then(|pending| pending.preview_plan.clone())
        else {
            return false;
        };
        if !self.occurrence_distribution_preview_is_current()
            || self
                .occurrence_distribution_plan(&plan.source, plan.axis, plan.mode)
                .as_ref()
                != Some(&plan)
            || !self.confirm_occurrence_operation_preview()
        {
            return false;
        }
        self.pending_occurrence_distribution = None;
        true
    }

    pub fn preview_distribute_occurrences(
        &mut self,
        occurrence_ids: &BTreeSet<OccurrenceId>,
        axis: Axis,
        mode: DistributionMode,
    ) -> bool {
        self.occurrence_operation_preview = None;
        let Some(source) = self.occurrence_distribution_source_plan_for_ids(occurrence_ids) else {
            return false;
        };
        let Some(plan) = self.occurrence_distribution_plan(&source, axis, mode) else {
            return false;
        };
        self.preview_occurrence_distribution_plan(plan)
    }

    fn preview_occurrence_distribution_plan(&mut self, plan: OccurrenceDistributionPlan) -> bool {
        self.occurrence_operation_preview = None;
        if self
            .occurrence_distribution_plan(&plan.source, plan.axis, plan.mode)
            .as_ref()
            != Some(&plan)
        {
            return false;
        }
        let batch = CommandBatch::new(plan.commands.clone());
        self.occurrence_operation_preview = Some(OccurrenceOperationPreview {
            source_revision: plan.source.source_revision,
            command_digest: batch.digest(),
            batch,
            boxes: plan.preview_boxes.clone(),
            hidden_occurrences: BTreeSet::new(),
            selection_after: None,
            committed_digest_key: "digest-distribute-committed",
            canonical_plan: Some(OccurrenceCanonicalPreviewPlan::Distribution(plan.clone())),
            solid_tool_plan: None,
            smart_through_cut_plan: None,
            smart_profile_pocket_plan: None,
        });
        self.status_key = "status-preview";
        self.digest = self.catalog.format(
            match plan.mode {
                DistributionMode::Centers => "digest-distribute-live",
                DistributionMode::EqualGaps => "digest-distribute-gaps-live",
            },
            &BTreeMap::from([
                ("axis", alignment_axis_label(plan.axis).to_owned()),
                ("count", plan.source.occurrences.len().to_string()),
                ("spacing", format_height(plan.spacing_mm)),
            ]),
        );
        true
    }

    fn linear_pattern_plan(
        &self,
        source: &LinearPatternSourcePlan,
        axis: Axis,
        spacing_mm: f64,
        count: usize,
    ) -> Option<LinearPatternPlan> {
        if self
            .linear_pattern_source_plan_for_occurrence(source.occurrence_id)
            .as_ref()
            != Some(source)
            || !(2..=MAX_PATTERN_COUNT).contains(&count)
            || !spacing_mm.is_finite()
            || spacing_mm.abs() <= f64::EPSILON
        {
            return None;
        }
        let mut commands = Vec::with_capacity(count - 1);
        for index in 1..count {
            let id = OccurrenceId(
                source
                    .next_occurrence_id
                    .0
                    .checked_add((index - 1) as u64)?,
            );
            let offset_mm = spacing_mm * index as f64;
            if !offset_mm.is_finite() {
                return None;
            }
            let transform =
                translated_transform(source.source_transform, axis_vector(axis, offset_mm)).ok()?;
            commands.push(CanonicalCommand::CreateOccurrence {
                id,
                definition_id: source.definition_id,
                name: self.catalog.format(
                    "model-copy-occurrence",
                    &BTreeMap::from([
                        ("name", source.definition_name.clone()),
                        (
                            "number",
                            (source.existing_definition_occurrence_count + index).to_string(),
                        ),
                    ]),
                ),
                transform,
                parent: source.source_parent,
                tag: source.source_tag,
                visible: source.source_visible,
            });
        }
        Some(LinearPatternPlan {
            source: source.clone(),
            axis,
            spacing_mm,
            count,
            commands,
        })
    }

