    fn show_rectangular_pattern_window(&mut self, context: &egui::Context) {
        let Some(pending) = self.pending_rectangular_pattern.as_ref() else {
            return;
        };
        let binding_is_current = self.rectangular_pattern_binding_is_current(pending);
        let previous_primary_axis = pending.primary_axis;
        let previous_primary_spacing = pending.primary_spacing.clone();
        let previous_primary_count = pending.primary_count.clone();
        let previous_secondary_axis = pending.secondary_axis;
        let previous_secondary_spacing = pending.secondary_spacing.clone();
        let previous_secondary_count = pending.secondary_count.clone();
        let mut primary_axis = previous_primary_axis;
        let mut primary_spacing = previous_primary_spacing.clone();
        let mut primary_count = previous_primary_count.clone();
        let mut secondary_axis = previous_secondary_axis;
        let mut secondary_spacing = previous_secondary_spacing.clone();
        let mut secondary_count = previous_secondary_count.clone();
        let parse = |primary_axis: Axis,
                     primary_spacing: &str,
                     primary_count: &str,
                     secondary_axis: Axis,
                     secondary_spacing: &str,
                     secondary_count: &str| {
            let primary_spacing = primary_spacing.trim().parse::<f64>().ok()?;
            let primary_count = primary_count.trim().parse::<usize>().ok()?;
            let secondary_spacing = secondary_spacing.trim().parse::<f64>().ok()?;
            let secondary_count = secondary_count.trim().parse::<usize>().ok()?;
            let total_count = primary_count.checked_mul(secondary_count)?;
            (primary_axis != secondary_axis
                && primary_spacing.is_finite()
                && primary_spacing.abs() > f64::EPSILON
                && secondary_spacing.is_finite()
                && secondary_spacing.abs() > f64::EPSILON
                && (2..=MAX_PATTERN_COUNT).contains(&primary_count)
                && (2..=MAX_PATTERN_COUNT).contains(&secondary_count)
                && total_count <= MAX_PATTERN_COUNT)
                .then_some((
                    primary_axis,
                    primary_spacing,
                    primary_count,
                    secondary_axis,
                    secondary_spacing,
                    secondary_count,
                ))
        };
        let mut current = parse(
            primary_axis,
            &primary_spacing,
            &primary_count,
            secondary_axis,
            &secondary_spacing,
            &secondary_count,
        );
        let preview_is_current = self.rectangular_pattern_preview_is_current();
        let mut open = true;
        let mut preview = false;
        let mut confirm = false;
        let mut cancel = false;
        egui::Window::new(self.catalog.text("dialog-rectangular-pattern-title"))
            .id(egui::Id::new("rectangular-pattern"))
            .open(&mut open)
            .collapsible(false)
            .resizable(false)
            .show(context, |ui| {
                for (axis, label_key) in [
                    (&mut primary_axis, "dialog-rectangular-pattern-primary-axis"),
                    (
                        &mut secondary_axis,
                        "dialog-rectangular-pattern-secondary-axis",
                    ),
                ] {
                    ui.label(self.catalog.text(label_key));
                    ui.horizontal(|ui| {
                        for (candidate, key) in [
                            (Axis::X, "dialog-rectangular-pattern-axis-x"),
                            (Axis::Y, "dialog-rectangular-pattern-axis-y"),
                            (Axis::Z, "dialog-rectangular-pattern-axis-z"),
                        ] {
                            ui.selectable_value(axis, candidate, self.catalog.text(key));
                        }
                    });
                }
                for (value, key) in [
                    (
                        &mut primary_spacing,
                        "dialog-rectangular-pattern-primary-spacing",
                    ),
                    (
                        &mut primary_count,
                        "dialog-rectangular-pattern-primary-count",
                    ),
                    (
                        &mut secondary_spacing,
                        "dialog-rectangular-pattern-secondary-spacing",
                    ),
                    (
                        &mut secondary_count,
                        "dialog-rectangular-pattern-secondary-count",
                    ),
                ] {
                    let label = self.catalog.text(key);
                    ui.label(&label);
                    let input = ui.add(egui::TextEdit::singleline(value));
                    input.widget_info(|| {
                        egui::WidgetInfo::labeled(egui::WidgetType::TextEdit, true, &label)
                    });
                }
                current = parse(
                    primary_axis,
                    &primary_spacing,
                    &primary_count,
                    secondary_axis,
                    &secondary_spacing,
                    &secondary_count,
                );
                ui.separator();
                ui.horizontal(|ui| {
                    preview = ui
                        .add_enabled(
                            binding_is_current && current.is_some(),
                            egui::Button::new(
                                self.catalog.text("dialog-rectangular-pattern-preview"),
                            ),
                        )
                        .clicked();
                    confirm = ui
                        .add_enabled(
                            preview_is_current,
                            egui::Button::new(
                                self.catalog.text("dialog-rectangular-pattern-confirm"),
                            ),
                        )
                        .clicked();
                    cancel = ui
                        .button(self.catalog.text("dialog-rectangular-pattern-cancel"))
                        .clicked();
                });
            });
        let changed = primary_axis != previous_primary_axis
            || primary_spacing != previous_primary_spacing
            || primary_count != previous_primary_count
            || secondary_axis != previous_secondary_axis
            || secondary_spacing != previous_secondary_spacing
            || secondary_count != previous_secondary_count;
        if let Some(pending) = self.pending_rectangular_pattern.as_mut() {
            pending.primary_axis = primary_axis;
            pending.primary_spacing = primary_spacing;
            pending.primary_count = primary_count;
            pending.secondary_axis = secondary_axis;
            pending.secondary_spacing = secondary_spacing;
            pending.secondary_count = secondary_count;
            if changed {
                pending.preview_plan = None;
            }
        }
        if changed {
            self.occurrence_operation_preview = None;
        }
        if cancel || !open {
            self.pending_rectangular_pattern = None;
            self.occurrence_operation_preview = None;
            self.digest = self.catalog.text("digest-cancelled");
        } else if preview {
            self.preview_pending_rectangular_pattern();
        } else if confirm {
            self.confirm_rectangular_pattern();
        }
    }

    fn show_circular_pattern_window(&mut self, context: &egui::Context) {
        let Some(pending) = self.pending_circular_pattern.as_ref() else {
            return;
        };
        let binding_is_current = self.circular_pattern_binding_is_current(pending);
        let previous_axis = pending.axis;
        let previous_centre_x = pending.centre_x.clone();
        let previous_centre_y = pending.centre_y.clone();
        let previous_centre_z = pending.centre_z.clone();
        let previous_angle = pending.angle.clone();
        let previous_count = pending.count.clone();
        let mut axis = previous_axis;
        let mut centre_x = previous_centre_x.clone();
        let mut centre_y = previous_centre_y.clone();
        let mut centre_z = previous_centre_z.clone();
        let mut angle = previous_angle.clone();
        let mut count = previous_count.clone();
        let parse = |axis: Axis, x: &str, y: &str, z: &str, angle: &str, count: &str| {
            let centre = Vec3::new(
                x.trim().parse::<f64>().ok()?,
                y.trim().parse::<f64>().ok()?,
                z.trim().parse::<f64>().ok()?,
            );
            let angle = angle.trim().parse::<f64>().ok()?;
            let count = count.trim().parse::<usize>().ok()?;
            (centre.x.is_finite()
                && centre.y.is_finite()
                && centre.z.is_finite()
                && angle.is_finite()
                && (0.01..=360.0).contains(&angle.abs())
                && (2..=MAX_PATTERN_COUNT).contains(&count))
            .then_some((axis, centre, angle, count))
        };
        let mut current = parse(axis, &centre_x, &centre_y, &centre_z, &angle, &count);
        let preview_is_current = self.circular_pattern_preview_is_current();
        let mut open = true;
        let mut preview = false;
        let mut confirm = false;
        let mut cancel = false;
        egui::Window::new(self.catalog.text("dialog-circular-pattern-title"))
            .id(egui::Id::new("circular-pattern"))
            .open(&mut open)
            .collapsible(false)
            .resizable(false)
            .show(context, |ui| {
                ui.label(self.catalog.text("dialog-circular-pattern-axis"));
                ui.horizontal(|ui| {
                    for (candidate, key) in [
                        (Axis::X, "dialog-circular-pattern-axis-x"),
                        (Axis::Y, "dialog-circular-pattern-axis-y"),
                        (Axis::Z, "dialog-circular-pattern-axis-z"),
                    ] {
                        ui.selectable_value(&mut axis, candidate, self.catalog.text(key));
                    }
                });
                for (value, key) in [
                    (&mut centre_x, "dialog-circular-pattern-centre-x"),
                    (&mut centre_y, "dialog-circular-pattern-centre-y"),
                    (&mut centre_z, "dialog-circular-pattern-centre-z"),
                ] {
                    let label = self.catalog.text(key);
                    ui.label(&label);
                    let input = ui.add(egui::TextEdit::singleline(value));
                    input.widget_info(|| {
                        egui::WidgetInfo::labeled(egui::WidgetType::TextEdit, true, &label)
                    });
                }
                let angle_label = self.catalog.text("dialog-circular-pattern-angle");
                ui.label(&angle_label);
                let angle_input = ui.add(egui::TextEdit::singleline(&mut angle));
                angle_input.widget_info(|| {
                    egui::WidgetInfo::labeled(egui::WidgetType::TextEdit, true, &angle_label)
                });
                let count_label = self.catalog.text("dialog-circular-pattern-count");
                ui.label(&count_label);
                let count_input = ui.add(egui::TextEdit::singleline(&mut count));
                count_input.widget_info(|| {
                    egui::WidgetInfo::labeled(egui::WidgetType::TextEdit, true, &count_label)
                });
                current = parse(axis, &centre_x, &centre_y, &centre_z, &angle, &count);
                ui.separator();
                ui.horizontal(|ui| {
                    preview = ui
                        .add_enabled(
                            binding_is_current && current.is_some(),
                            egui::Button::new(self.catalog.text("dialog-circular-pattern-preview")),
                        )
                        .clicked();
                    confirm = ui
                        .add_enabled(
                            preview_is_current,
                            egui::Button::new(self.catalog.text("dialog-circular-pattern-confirm")),
                        )
                        .clicked();
                    cancel = ui
                        .button(self.catalog.text("dialog-circular-pattern-cancel"))
                        .clicked();
                });
            });
        let changed = axis != previous_axis
            || centre_x != previous_centre_x
            || centre_y != previous_centre_y
            || centre_z != previous_centre_z
            || angle != previous_angle
            || count != previous_count;
        if let Some(pending) = self.pending_circular_pattern.as_mut() {
            pending.axis = axis;
            pending.centre_x = centre_x;
            pending.centre_y = centre_y;
            pending.centre_z = centre_z;
            pending.angle = angle;
            pending.count = count;
            if changed {
                pending.preview_plan = None;
            }
        }
        if changed {
            self.occurrence_operation_preview = None;
        }
        if cancel || !open {
            self.pending_circular_pattern = None;
            self.occurrence_operation_preview = None;
            self.digest = self.catalog.text("digest-cancelled");
        } else if preview {
            self.preview_pending_circular_pattern();
        } else if confirm {
            self.confirm_circular_pattern();
        }
    }

    fn show_stl_import_window(&mut self, context: &egui::Context) {
        let Some(pending) = self.pending_stl_import.as_ref() else {
            return;
        };
        let path = pending.plan.source.path.clone();
        let mut unit = pending.plan.source.unit;
        let mut import = false;
        let mut cancel = false;
        egui::Window::new(self.catalog.text("dialog-import-stl-title"))
            .id(egui::Id::new("stl-import-units"))
            .collapsible(false)
            .resizable(false)
            .show(context, |ui| {
                ui.label(self.catalog.format(
                    "dialog-import-stl-source",
                    &BTreeMap::from([("path", path.display().to_string())]),
                ));
                ui.label(self.catalog.text("dialog-import-stl-units"));
                for (candidate, key) in [
                    (ImportLengthUnit::Millimetre, "unit-millimetre"),
                    (ImportLengthUnit::Centimetre, "unit-centimetre"),
                    (ImportLengthUnit::Metre, "unit-metre"),
                    (ImportLengthUnit::Inch, "unit-inch"),
                    (ImportLengthUnit::Foot, "unit-foot"),
                ] {
                    ui.radio_value(&mut unit, candidate, self.catalog.text(key));
                }
                ui.separator();
                ui.horizontal(|ui| {
                    import = ui
                        .button(self.catalog.text("dialog-import-stl-confirm"))
                        .clicked();
                    cancel = ui
                        .button(self.catalog.text("dialog-import-stl-cancel"))
                        .clicked();
                });
            });
        let updated_source = self.pending_stl_import.as_ref().and_then(|pending| {
            (pending.plan.source.unit != unit).then(|| {
                let mut source = pending.plan.source.clone();
                source.unit = unit;
                source
            })
        });
        if let Some(source) = updated_source {
            let result = self.prepare_stl_import_preview_plan(source);
            let pending = self
                .pending_stl_import
                .as_mut()
                .expect("the STL review window still has a pending import");
            match result {
                Ok(plan) => {
                    pending.plan = plan;
                    pending.review_error = None;
                }
                Err(error) => pending.review_error = Some(error),
            }
        }
        if cancel {
            self.pending_stl_import = None;
            self.digest = self.catalog.text("digest-cancelled");
        } else if import {
            let pending = self
                .pending_stl_import
                .take()
                .expect("the STL review window has a pending import");
            self.import_stl_from(&pending);
        }
    }

    fn show_dxf_import_window(&mut self, context: &egui::Context) {
        let Some(pending) = self.pending_dxf_import.as_ref() else {
            return;
        };
        let path = pending.plan.source.path.clone();
        let review = pending.plan.review.clone();
        let review_error = pending.review_error.clone();
        let mut unit = pending.plan.source.unit;
        let mut unit_confirmed = pending.unit_confirmed;
        let mut import = false;
        let mut cancel = false;
        egui::Window::new(self.catalog.text("dialog-import-dxf-title"))
            .id(egui::Id::new("dxf-import-review"))
            .collapsible(false)
            .resizable(true)
            .show(context, |ui| {
                ui.label(self.catalog.format(
                    "dialog-import-dxf-source",
                    &BTreeMap::from([("path", path.display().to_string())]),
                ));
                ui.label(self.catalog.format(
                    "dialog-import-dxf-summary",
                    &BTreeMap::from([
                        ("profiles", review.profiles().len().to_string()),
                        ("layers", review.layers().len().to_string()),
                    ]),
                ));
                ui.label(self.catalog.text("dialog-import-dxf-origin"));
                ui.label(self.catalog.format(
                    "dialog-import-dxf-layers",
                    &BTreeMap::from([("layers", review.layers().join(", "))]),
                ));
                if review.units().authority() == ImportUnitAuthority::UserDeclared {
                    ui.label(self.catalog.text("dialog-import-dxf-units"));
                    for (candidate, key) in [
                        (ImportLengthUnit::Millimetre, "unit-millimetre"),
                        (ImportLengthUnit::Centimetre, "unit-centimetre"),
                        (ImportLengthUnit::Metre, "unit-metre"),
                        (ImportLengthUnit::Inch, "unit-inch"),
                        (ImportLengthUnit::Foot, "unit-foot"),
                    ] {
                        if ui
                            .radio_value(&mut unit, candidate, self.catalog.text(key))
                            .clicked()
                        {
                            unit_confirmed = true;
                        }
                    }
                } else {
                    let unit_key = match review.units().source_unit() {
                        ImportLengthUnit::Millimetre => "unit-millimetre",
                        ImportLengthUnit::Centimetre => "unit-centimetre",
                        ImportLengthUnit::Metre => "unit-metre",
                        ImportLengthUnit::Inch => "unit-inch",
                        ImportLengthUnit::Foot => "unit-foot",
                    };
                    ui.label(self.catalog.format(
                        "dialog-import-dxf-file-units",
                        &BTreeMap::from([("unit", self.catalog.text(unit_key))]),
                    ));
                }
                ui.separator();
                ui.label(self.catalog.text("dialog-import-dxf-losses"));
                egui::ScrollArea::vertical()
                    .max_height(160.0)
                    .show(ui, |ui| {
                        for diagnostic in review.diagnostics() {
                            let severity_key = match diagnostic.severity() {
                                ImportDiagnosticSeverity::Info => {
                                    "dialog-import-dxf-diagnostic-info"
                                }
                                ImportDiagnosticSeverity::Warning => {
                                    "dialog-import-dxf-diagnostic-warning"
                                }
                            };
                            let subject = diagnostic
                                .subject()
                                .map(|value| format!(" · {value}"))
                                .unwrap_or_default();
                            ui.label(format!(
                                "{} · {}{} · {}",
                                self.catalog.text(severity_key),
                                diagnostic.code(),
                                subject,
                                diagnostic.count()
                            ));
                        }
                    });
                ui.label(self.catalog.text("dialog-import-dxf-subset-warning"));
                if let Some(error) = review_error.as_deref() {
                    ui.colored_label(Color32::LIGHT_RED, error);
                }
                ui.separator();
                ui.horizontal(|ui| {
                    import = ui
                        .add_enabled(
                            review_error.is_none() && unit_confirmed,
                            egui::Button::new(self.catalog.text("dialog-import-dxf-confirm")),
                        )
                        .clicked();
                    cancel = ui
                        .button(self.catalog.text("dialog-import-dxf-cancel"))
                        .clicked();
                });
            });
        if let Some(pending) = self.pending_dxf_import.as_mut() {
            pending.unit_confirmed = unit_confirmed;
        }
        let updated_source = self.pending_dxf_import.as_ref().and_then(|pending| {
            (pending.plan.source.unit != unit).then(|| {
                let mut source = pending.plan.source.clone();
                source.unit = unit;
                source
            })
        });
        if let Some(source) = updated_source {
            let result = self.prepare_dxf_import_preview_plan(source);
            let pending = self
                .pending_dxf_import
                .as_mut()
                .expect("the DXF review window still has a pending import");
            match result {
                Ok(plan) => {
                    pending.plan = plan;
                    pending.review_error = None;
                }
                Err(error) => pending.review_error = Some(error),
            }
        }
        if cancel {
            self.pending_dxf_import = None;
            self.digest = self.catalog.text("digest-cancelled");
        } else if import {
            let pending = self
                .pending_dxf_import
                .take()
                .expect("the DXF review window has a pending import");
            self.import_dxf_from(&pending);
        }
    }

